(392403,43601,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses klebrige Eis hat absolut alles ruiniert, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Dieses klebrige Eis hat absolut alles ruiniert, oder?'::text),
(392407,43601,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це липке морозиво геть усе зіпсувало, ...?'::text,'чи не так?'::text,'чи не так?'::text,'чи не так?'::text,'Це липке морозиво геть усе зіпсувало, чи не так?'::text),
(392406,43601,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este helado pegajoso lo ha arruinado absolutamente todo, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Este helado pegajoso lo ha arruinado absolutamente todo, ¿verdad?'::text),
(392405,43601,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette glace collante a absolument tout gâché, ... ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'Cette glace collante a absolument tout gâché, n''est-ce pas ?'::text),
(392408,43601,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yapış yapış dondurma kesinlikle her şeyi mahvetti, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Bu yapış yapış dondurma kesinlikle her şeyi mahvetti, değil mi?'::text),
(392409,43601,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a ragacsos fagyi abszolút mindent tönkretett, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Ez a ragacsos fagyi abszolút mindent tönkretett, ugye?'::text),
(392430,43604,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, angeblich heißt es, dass er sich bis zum Mittagessen fünfmal die klebrigen Hände ...'::text,'gewaschen haben wird'::text,'waschen wird'::text,'gewaschen hat'::text,'Okay, angeblich heißt es, dass er sich bis zum Mittagessen fünfmal die klebrigen Hände gewaschen haben wird.'::text),
(392434,43604,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, до обіду він ... свої липкі руки п''ять разів.'::text,'вже помиє'::text,'помиє'::text,'помив'::text,'Коротше, кажуть, до обіду він вже помиє свої липкі руки п''ять разів.'::text),
(392433,43604,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer, para la hora de comer ya se ... las manos pegajosas cinco veces.'::text,'habrá lavado'::text,'lavará'::text,'ha lavado'::text,'Vale, al parecer, para la hora de comer ya se habrá lavado las manos pegajosas cinco veces.'::text),
(392432,43604,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment, d''ici le déjeuner, il se ... les mains collantes cinq fois.'::text,'sera lavé'::text,'lavera'::text,'est lavé'::text,'Bon, apparemment, d''ici le déjeuner, il se sera lavé les mains collantes cinq fois.'::text),
(392435,43604,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre öğle yemeğine kadar yapış yapış ellerini beş kez ...'::text,'yıkamış olacak'::text,'yıkayacak'::text,'yıkadı'::text,'Tamam, duyduğuma göre öğle yemeğine kadar yapış yapış ellerini beş kez yıkamış olacak.'::text),
(392436,43604,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag ebédig már ötször ... a ragacsos kezét.'::text,'megmossa'::text,'mosni fogja'::text,'megmosta'::text,'Szóval, állítólag ebédig már ötször megmossa a ragacsos kezét.'::text),
(392439,43605,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, um drei hat er schon eine Stunde lang an seinen klebrigen Fingern ..., ohne Witz.'::text,'geleckt'::text,'geleckt'::text,'abgeleckt'::text,'Bro, um drei hat er schon eine Stunde lang an seinen klebrigen Fingern geleckt, ohne Witz.'::text),
(392443,43605,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, о третій він уже годину ... свої липкі пальці, без жартів.'::text,'облизуватиме'::text,'облизуватиме'::text,'оближе'::text,'Бро, о третій він уже годину облизуватиме свої липкі пальці, без жартів.'::text),
(392442,43605,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, a las tres ya ... los dedos pegajosos durante una hora, en serio.'::text,'se habrá estado lamiendo'::text,'se estará lamiendo'::text,'se habrá lamido'::text,'Bro, a las tres ya se habrá estado lamiendo los dedos pegajosos durante una hora, en serio.'::text),
(392441,43605,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, à trois heures, ça fera une heure qu''il ... ses doigts collants, sans mentir.'::text,'lèche'::text,'lèche'::text,'aura léché'::text,'Frérot, à trois heures, ça fera une heure qu''il lèche ses doigts collants, sans mentir.'::text),
(392444,43605,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, saat üçte bir saattir yapış yapış parmaklarını ..., cidden.'::text,'yalıyor olacak'::text,'yalıyor olacak'::text,'yalamış olacak'::text,'Kanka, saat üçte bir saattir yapış yapış parmaklarını yalıyor olacak, cidden.'::text),
(392445,43605,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, háromkor már egy órája ... a ragacsos ujjait, komolyan.'::text,'nyalogatja'::text,'nyalogatja'::text,'nyalta le'::text,'Tesó, háromkor már egy órája nyalogatja a ragacsos ujjait, komolyan.'::text),
(392448,43606,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, hätte er es schneller gegessen, ... seine Hände nicht so klebrig geworden, echt.'::text,'wären'::text,'werden'::text,'wurden'::text,'Alter, hätte er es schneller gegessen, wären seine Hände nicht so klebrig geworden, echt.'::text),
(392452,43606,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якби він з''їв його швидше, його руки ... такими липкими, реально.'::text,'не стали б'::text,'не стануть'::text,'не стали'::text,'Чувак, якби він з''їв його швидше, його руки не стали б такими липкими, реально.'::text),
(392451,43606,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si se lo hubiera comido más rápido, sus manos no ... tan pegajosas, en serio.'::text,'se habrían puesto'::text,'se pondrán'::text,'se pusieron'::text,'Tío, si se lo hubiera comido más rápido, sus manos no se habrían puesto tan pegajosas, en serio.'::text),
(392450,43606,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, s''il l''avait mangée plus vite, ses mains ... aussi collantes, grave.'::text,'ne seraient pas devenues'::text,'ne deviendront pas'::text,'ne sont pas devenues'::text,'Mec, s''il l''avait mangée plus vite, ses mains ne seraient pas devenues aussi collantes, grave.'::text),
(392453,43606,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onu daha hızlı yeseydi elleri bu kadar yapış yapış ..., cidden.'::text,'olmazdı'::text,'olmayacak'::text,'olmadı'::text,'Kanka, onu daha hızlı yeseydi elleri bu kadar yapış yapış olmazdı, cidden.'::text),
(392454,43606,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha gyorsabban megette volna, a keze nem ... ennyire ragacsos, komolyan.'::text,'lett volna'::text,'lesz'::text,'lett'::text,'Tesó, ha gyorsabban megette volna, a keze nem lett volna ennyire ragacsos, komolyan.'::text),
(392457,43607,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte er einen Becher für 2 Euro gekauft, ... seine Hände jetzt, kurz vor seinem Meeting, nicht klebrig.'::text,'wären'::text,'wären gewesen'::text,'werden'::text,'Hätte er einen Becher für 2 Euro gekauft, wären seine Hände jetzt, kurz vor seinem Meeting, nicht klebrig.'::text),
(392461,43607,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він купив стаканчик за 2 євро, його руки ... липкими зараз, якраз перед нарадою.'::text,'не були б'::text,'не були б'::text,'не будуть'::text,'Якби він купив стаканчик за 2 євро, його руки не були б липкими зараз, якраз перед нарадою.'::text),
(392460,43607,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera comprado una tarrina de 2 euros, sus manos no ... pegajosas ahora, justo antes de su reunión.'::text,'estarían'::text,'habrían estado'::text,'estarán'::text,'Si hubiera comprado una tarrina de 2 euros, sus manos no estarían pegajosas ahora, justo antes de su reunión.'::text),
(392459,43607,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait acheté un pot à 2 euros, ses mains ne ... pas collantes maintenant, juste avant sa réunion.'::text,'seraient'::text,'auraient été'::text,'seront'::text,'S''il avait acheté un pot à 2 euros, ses mains ne seraient pas collantes maintenant, juste avant sa réunion.'::text),
(392462,43607,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'2 euroluk bir kap alsaydı, toplantısından hemen önce elleri şimdi yapış yapış ...'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'2 euroluk bir kap alsaydı, toplantısından hemen önce elleri şimdi yapış yapış olmazdı.'::text),
(392463,43607,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha vett volna egy 2 eurós poharat, most, közvetlenül a megbeszélés előtt nem ... ragacsos a keze.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha vett volna egy 2 eurós poharat, most, közvetlenül a megbeszélés előtt nem lenne ragacsos a keze.'::text),
(392466,43608,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Softeis ist dafür bekannt, in der Hitze sehr schnell klebrig ...'::text,'zu werden'::text,'werdend'::text,'geworden zu sein'::text,'Softeis ist dafür bekannt, in der Hitze sehr schnell klebrig zu werden.'::text),
(392470,43608,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відомо, що м''яке морозиво в спеку дуже швидко ... липким.'::text,'стає'::text,'стає'::text,'стало'::text,'Відомо, що м''яке морозиво в спеку дуже швидко стає липким.'::text),
(392469,43608,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se sabe que el helado suave ... pegajoso muy rápido con el calor.'::text,'se pone'::text,'se pone'::text,'se ha puesto'::text,'Se sabe que el helado suave se pone pegajoso muy rápido con el calor.'::text),
(392468,43608,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La glace à l''italienne est connue pour ... collante très vite sous la chaleur.'::text,'devenir'::text,'devenant'::text,'être devenue'::text,'La glace à l''italienne est connue pour devenir collante très vite sous la chaleur.'::text),
(392471,43608,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yumuşak dondurmanın sıcakta çok çabuk yapışkan ... bilinir.'::text,'hale geldiği'::text,'hale geldiği'::text,'hale gelmiş olduğu'::text,'Yumuşak dondurmanın sıcakta çok çabuk yapışkan hale geldiği bilinir.'::text),
(392472,43608,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lágy fagyiról köztudott, hogy melegben nagyon gyorsan ... ragacsossá.'::text,'válik'::text,'válik'::text,'vált'::text,'A lágy fagyiról köztudott, hogy melegben nagyon gyorsan válik ragacsossá.'::text),
(392475,43609,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gab der Sonne die Schuld dafür, dass sie seine Hände so klebrig ...'::text,'gemacht hatte'::text,'zu machen'::text,'machte'::text,'Er gab der Sonne die Schuld dafür, dass sie seine Hände so klebrig gemacht hatte.'::text),
(392479,43609,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він звинуватив сонце в тому, що воно ... його руки такими липкими.'::text,'зробило'::text,'зробити'::text,'зробило'::text,'Він звинуватив сонце в тому, що воно зробило його руки такими липкими.'::text),
(392478,43609,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Culpó al sol de ... las manos tan pegajosas.'::text,'dejarle'::text,'dejarle'::text,'le dejó'::text,'Culpó al sol de dejarle las manos tan pegajosas.'::text),
(392477,43609,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a accusé le soleil de ... les mains si collantes.'::text,'lui avoir rendu'::text,'lui rendre'::text,'lui a rendu'::text,'Il a accusé le soleil de lui avoir rendu les mains si collantes.'::text),
(392480,43609,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellerini bu kadar yapış yapış ... için güneşi suçladı.'::text,'yaptığı'::text,'yapmak'::text,'yaptı'::text,'Ellerini bu kadar yapış yapış yaptığı için güneşi suçladı.'::text),
(392481,43609,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A napot hibáztatta, amiért ilyen ragacsossá ... a kezét.'::text,'tette'::text,'tenni'::text,'tette'::text,'A napot hibáztatta, amiért ilyen ragacsossá tette a kezét.'::text),
(392484,43610,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... nach einem Becher fragen sollen; die Waffel hat seine Hände so klebrig gemacht.'::text,'hätte'::text,'muss'::text,'sollte'::text,'Er hätte nach einem Becher fragen sollen; die Waffel hat seine Hände so klebrig gemacht.'::text),
(392488,43610,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому ... попросити стаканчик; ріжок зробив його руки такими липкими.'::text,'треба було'::text,'напевно, довелося'::text,'треба'::text,'Йому треба було попросити стаканчик; ріжок зробив його руки такими липкими.'::text),
(392487,43610,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pedido una tarrina; el cucurucho le dejó las manos muy pegajosas.'::text,'Debería haber'::text,'Debe de haber'::text,'Debería'::text,'Debería haber pedido una tarrina; el cucurucho le dejó las manos muy pegajosas.'::text),
(392486,43610,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... demander un pot ; le cornet lui a rendu les mains si collantes.'::text,'aurait dû'::text,'a dû'::text,'devrait'::text,'Il aurait dû demander un pot ; le cornet lui a rendu les mains si collantes.'::text),
(392489,43610,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kap ...; külah ellerini çok yapış yapış yaptı.'::text,'istemeliydi'::text,'istemiş olmalı'::text,'istemeli'::text,'Bir kap istemeliydi; külah ellerini çok yapış yapış yaptı.'::text),
(392490,43610,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kérnie ... egy poharat; a tölcsér nagyon ragacsossá tette a kezét.'::text,'kellett volna'::text,'kellett'::text,'kellene'::text,'Kérnie kellett volna egy poharat; a tölcsér nagyon ragacsossá tette a kezét.'::text),
(392493,43611,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie ... ich so elegante klebrige Hände gesehen. Wirklich makelloses Essen.'::text,'habe'::text,'habe'::text,'habe'::text,'Nie habe ich so elegante klebrige Hände gesehen. Wirklich makelloses Essen.'::text),
(392497,43611,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ... таких елегантних липких рук. Справді бездоганна трапеза.'::text,'я не бачив'::text,'я не бачив'::text,'я не бачив'::text,'Ніколи я не бачив таких елегантних липких рук. Справді бездоганна трапеза.'::text),
(392496,43611,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... unas manos pegajosas tan elegantes. Una forma de comer realmente impecable.'::text,'he visto'::text,'he visto'::text,'vi'::text,'Nunca he visto unas manos pegajosas tan elegantes. Una forma de comer realmente impecable.'::text),
(392495,43611,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... de mains collantes aussi élégantes. Une dégustation vraiment impeccable.'::text,'je n''ai vu'::text,'j''ai vu'::text,'je ne vis'::text,'Jamais je n''ai vu de mains collantes aussi élégantes. Une dégustation vraiment impeccable.'::text),
(392498,43611,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadar zarif yapış yapış elleri hiç ...! Gerçekten kusursuz bir yeme şekli.'::text,'görmedim'::text,'görmedim'::text,'görmedim'::text,'Bu kadar zarif yapış yapış elleri hiç görmedim! Gerçekten kusursuz bir yeme şekli.'::text),
(392499,43611,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... még ilyen elegáns ragacsos kezeket. Tényleg hibátlan evés.'::text,'nem láttam'::text,'nem láttam'::text,'nem láttam'::text,'Soha nem láttam még ilyen elegáns ragacsos kezeket. Tényleg hibátlan evés.'::text),
(379317,42147,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, er ... sich gerade eine Karte an die Stirn, als ihm endlich die Antwort einfiel, ohne Witz.'::text,'drückte'::text,'drückte'::text,'hat gedrückt'::text,'Yo, er drückte sich gerade eine Karte an die Stirn, als ihm endlich die Antwort einfiel, ohne Witz.'::text),
(379321,42147,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, він ... картку до лоба, коли нарешті згадав відповідь, без жартів.'::text,'притискав'::text,'притиснув'::text,'притиснув'::text,'Йо, він притискав картку до лоба, коли нарешті згадав відповідь, без жартів.'::text),
(379320,42147,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... una tarjeta contra la frente cuando por fin recordó la respuesta, en serio.'::text,'se estaba apretando'::text,'se apretó'::text,'se ha apretado'::text,'Tío, se estaba apretando una tarjeta contra la frente cuando por fin recordó la respuesta, en serio.'::text),
(379319,42147,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, il ... une carte contre son front quand il s''est enfin rappelé la réponse, sans mentir.'::text,'pressait'::text,'a pressé'::text,'a pressé'::text,'Wesh, il pressait une carte contre son front quand il s''est enfin rappelé la réponse, sans mentir.'::text),
(379322,42147,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, sonunda cevabı hatırladığında bir kartı alnına ..., cidden.'::text,'bastırıyordu'::text,'bastırdı'::text,'bastırdı'::text,'Kanka, sonunda cevabı hatırladığında bir kartı alnına bastırıyordu, cidden.'::text),
(379323,42147,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, épp egy kártyát ... a homlokához, amikor végre felidézte a választ, komolyan.'::text,'nyomott'::text,'nyomott'::text,'nyomott'::text,'Tesó, épp egy kártyát nyomott a homlokához, amikor végre felidézte a választ, komolyan.'::text),
(379335,42149,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er den Stapel vor der Deadline ..., erinnerte er sich an 50 Antworten in Folge.'::text,'durcharbeitete'::text,'durcharbeitete'::text,'durchgearbeitet hat'::text,'Während er den Stapel vor der Deadline durcharbeitete, erinnerte er sich an 50 Antworten in Folge.'::text),
(379339,42149,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ... стос перед дедлайном, він згадав 50 відповідей поспіль.'::text,'опрацьовував'::text,'опрацював'::text,'опрацював'::text,'Поки він опрацьовував стос перед дедлайном, він згадав 50 відповідей поспіль.'::text),
(379338,42149,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... el montón antes de la fecha límite, recordó 50 respuestas seguidas.'::text,'repasaba'::text,'repasó'::text,'ha repasado'::text,'Mientras repasaba el montón antes de la fecha límite, recordó 50 respuestas seguidas.'::text),
(379337,42149,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ... la pile avant la date limite, il s''est rappelé 50 réponses d''affilée.'::text,'parcourait'::text,'a parcouru'::text,'a parcouru'::text,'Pendant qu''il parcourait la pile avant la date limite, il s''est rappelé 50 réponses d''affilée.'::text),
(379340,42149,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son teslim tarihinden önce desteyi tek tek ... sırada, arka arkaya 50 cevabı hatırladı.'::text,'geçtiği'::text,'geçtiği'::text,'geçmiş olduğu'::text,'Son teslim tarihinden önce desteyi tek tek geçtiği sırada, arka arkaya 50 cevabı hatırladı.'::text),
(379341,42149,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a határidő előtt a paklin ..., 50 választ idézett fel egymás után.'::text,'dolgozott végig'::text,'végigdolgozott'::text,'végigdolgozott'::text,'Miközben a határidő előtt a paklin dolgozott végig, 50 választ idézett fel egymás után.'::text),
(379344,42150,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat sich heute an jede Karte ..., also hat er sich heute an jede Karte erinnert.'::text,'erinnert'::text,'erinnert'::text,'erinnert'::text,'Er hat sich heute an jede Karte erinnert, also hat er sich heute an jede Karte erinnert.'::text),
(379348,42150,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні він ... кожну картку, тож сьогодні він згадав кожну картку.'::text,'згадав'::text,'згадував'::text,'згадує'::text,'Сьогодні він згадав кожну картку, тож сьогодні він згадав кожну картку.'::text),
(379347,42150,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy ... todas las tarjetas, así que hoy ha recordado todas las tarjetas.'::text,'ha recordado'::text,'ha estado recordando'::text,'está recordando'::text,'Hoy ha recordado todas las tarjetas, así que hoy ha recordado todas las tarjetas.'::text),
(379346,42150,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aujourd''hui, il ... chaque carte, donc aujourd''hui il s''est rappelé chaque carte.'::text,'s''est rappelé'::text,'se rappelle'::text,'se rappelle'::text,'Aujourd''hui, il s''est rappelé chaque carte, donc aujourd''hui il s''est rappelé chaque carte.'::text),
(379349,42150,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün her kartı ..., yani bugün her kartı hatırladı.'::text,'hatırladı'::text,'hatırlayıp duruyor'::text,'hatırlıyor'::text,'Bugün her kartı hatırladı, yani bugün her kartı hatırladı.'::text),
(379350,42150,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma minden kártyát ..., tehát ma minden kártyát felidézett.'::text,'felidézett'::text,'idézget'::text,'idéz fel'::text,'Ma minden kártyát felidézett, tehát ma minden kártyát felidézett.'::text),
(379353,42151,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Typischerweise lässt sich die Versuchsperson von einem Mitschüler die Karten ..., an die sie sich nicht erinnert.'::text,'zeigen'::text,'zu zeigen'::text,'zeigend'::text,'Typischerweise lässt sich die Versuchsperson von einem Mitschüler die Karten zeigen, an die sie sich nicht erinnert.'::text),
(379357,42151,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай суб''єкт просить однокласника ... йому картки, які не може згадати.'::text,'показати'::text,'показати'::text,'показування'::text,'Зазвичай суб''єкт просить однокласника показати йому картки, які не може згадати.'::text),
(379356,42151,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente, el sujeto hace que un compañero le ... las tarjetas que no logra recordar.'::text,'enseñe'::text,'enseñar'::text,'enseñando'::text,'Normalmente, el sujeto hace que un compañero le enseñe las tarjetas que no logra recordar.'::text),
(379355,42151,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En général, le sujet se fait ... par un camarade les cartes qu''il n''arrive pas à se rappeler.'::text,'montrer'::text,'à montrer'::text,'montrant'::text,'En général, le sujet se fait montrer par un camarade les cartes qu''il n''arrive pas à se rappeler.'::text),
(379358,42151,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genellikle denek, hatırlayamadığı kartları bir sınıf arkadaşına ...'::text,'göstertir'::text,'göstermek'::text,'gösterme'::text,'Genellikle denek, hatırlayamadığı kartları bir sınıf arkadaşına göstertir.'::text),
(379359,42151,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vizsgált személy jellemzően ... egy osztálytársával a kártyákat, amelyeket nem tud felidézni.'::text,'megmutattatja'::text,'megmutatni'::text,'megmutatva'::text,'A vizsgált személy jellemzően megmutattatja egy osztálytársával a kártyákat, amelyeket nem tud felidézni.'::text),
(379362,42152,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünschte, er ... sich an die letzte Antwort erinnert, ohne auf die Karte zu schauen.'::text,'hätte'::text,'erinnerte'::text,'hat'::text,'Er wünschte, er hätte sich an die letzte Antwort erinnert, ohne auf die Karte zu schauen.'::text),
(379366,42152,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому б хотілося, щоб він ... останню відповідь, не підглядаючи в картку.'::text,'згадав'::text,'згадав'::text,'згадав'::text,'Йому б хотілося, щоб він згадав останню відповідь, не підглядаючи в картку.'::text),
(379365,42152,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gustaría ... la última respuesta sin mirar la tarjeta.'::text,'haber recordado'::text,'recordar'::text,'ha recordado'::text,'Le gustaría haber recordado la última respuesta sin mirar la tarjeta.'::text),
(379364,42152,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ... la dernière réponse sans regarder la carte.'::text,'s''être rappelé'::text,'se rappeler'::text,'s''est rappelé'::text,'Il aimerait s''être rappelé la dernière réponse sans regarder la carte.'::text),
(379367,42152,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke son cevabı karta bakmadan ... diye içinden geçiriyor.'::text,'hatırlasaydım'::text,'hatırlasam'::text,'hatırladım'::text,'Keşke son cevabı karta bakmadan hatırlasaydım diye içinden geçiriyor.'::text),
(379368,42152,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak ... az utolsó választ anélkül, hogy megnézte volna a kártyát.'::text,'felidézte volna'::text,'felidézné'::text,'felidézte'::text,'Azt kívánja, bárcsak felidézte volna az utolsó választ anélkül, hogy megnézte volna a kártyát.'::text),
(379371,42153,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Student, ... Gedächtnis gerade getestet wird, erinnert sich an eine Antwort nach der anderen.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Student, dessen Gedächtnis gerade getestet wird, erinnert sich an eine Antwort nach der anderen.'::text),
(379375,42153,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Студент, ... пам''ять зараз перевіряють, згадує одну відповідь за іншою.'::text,'чию'::text,'який'::text,'що'::text,'Студент, чию пам''ять зараз перевіряють, згадує одну відповідь за іншою.'::text),
(379374,42153,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El estudiante, ... memoria está siendo puesta a prueba, recuerda una respuesta tras otra.'::text,'cuya'::text,'que'::text,'el cual'::text,'El estudiante, cuya memoria está siendo puesta a prueba, recuerda una respuesta tras otra.'::text),
(379373,42153,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''étudiant, ... la mémoire est mise à l''épreuve, se rappelle une réponse après l''autre.'::text,'dont'::text,'qui'::text,'lequel'::text,'L''étudiant, dont la mémoire est mise à l''épreuve, se rappelle une réponse après l''autre.'::text),
(379376,42153,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hafızası test edilen öğrenci, cevapları birbiri ardına hatırlıyor.'::text,''::text,NULL::text,NULL::text,'Hafızası test edilen öğrenci, cevapları birbiri ardına hatırlıyor.'::text),
(379377,42153,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A diák, ... memóriáját éppen tesztelik, egymás után idézi fel a válaszokat.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A diák, akinek a memóriáját éppen tesztelik, egymás után idézi fel a válaszokat.'::text),
(379380,42154,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er testet sich mit Karten, ... er sich in der Prüfung an die Antworten erinnern kann.'::text,'damit'::text,'im Falle von'::text,'trotz'::text,'Er testet sich mit Karten, damit er sich in der Prüfung an die Antworten erinnern kann.'::text),
(379384,42154,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він перевіряє себе за допомогою карток, ... на іспиті згадати відповіді.'::text,'щоб'::text,'у разі'::text,'попри'::text,'Він перевіряє себе за допомогою карток, щоб на іспиті згадати відповіді.'::text),
(379383,42154,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se pone a prueba con tarjetas ... pueda recordar las respuestas en el examen.'::text,'para que'::text,'en caso de'::text,'a pesar de'::text,'Se pone a prueba con tarjetas para que pueda recordar las respuestas en el examen.'::text),
(379382,42154,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il se teste avec des cartes ... pouvoir se rappeler les réponses à l''examen.'::text,'pour'::text,'en cas de'::text,'malgré'::text,'Il se teste avec des cartes pour pouvoir se rappeler les réponses à l''examen.'::text),
(379385,42154,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sınavda cevapları hatırlayabilmek ... kendini kartlarla test ediyor.'::text,'için'::text,'durumunda'::text,'rağmen'::text,'Sınavda cevapları hatırlayabilmek için kendini kartlarla test ediyor.'::text),
(379386,42154,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kártyákkal teszteli magát, ... a vizsgán fel tudja idézni a válaszokat.'::text,'hogy'::text,'abban az esetben'::text,'annak ellenére'::text,'Kártyákkal teszteli magát, hogy a vizsgán fel tudja idézni a válaszokat.'::text),
(379389,42155,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit zehn Minuten, sich an diese Antwort zu erinnern! Absolut hoffnungslos!'::text,'versucht'::text,'versucht'::text,'versucht'::text,'Er versucht seit zehn Minuten, sich an diese Antwort zu erinnern! Absolut hoffnungslos!'::text),
(379393,42155,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже десять хвилин ... згадати цю відповідь! Абсолютно безнадійно!'::text,'намагається'::text,'намагається'::text,'намагається'::text,'Він уже десять хвилин намагається згадати цю відповідь! Абсолютно безнадійно!'::text),
(379392,42155,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Lleva diez minutos ... recordar esta respuesta! ¡Absolutamente desesperante!'::text,'intentando'::text,'intentando'::text,'intentando'::text,'¡Lleva diez minutos intentando recordar esta respuesta! ¡Absolutamente desesperante!'::text),
(379391,42155,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... de se rappeler cette réponse depuis dix minutes ! Complètement désespéré !'::text,'essaie'::text,'essaie'::text,'essaie'::text,'Il essaie de se rappeler cette réponse depuis dix minutes ! Complètement désespéré !'::text),
(379394,42155,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dakikadır bu cevabı hatırlamaya ...! Tamamen umutsuz!'::text,'çalışıyor'::text,'çalışıyor'::text,'çalışıyor'::text,'On dakikadır bu cevabı hatırlamaya çalışıyor! Tamamen umutsuz!'::text),
(379395,42155,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tíz perce ... felidézni ezt a választ! Teljesen reménytelen!'::text,'próbálja'::text,'próbálja'::text,'próbálja'::text,'Tíz perce próbálja felidézni ezt a választ! Teljesen reménytelen!'::text),
(379407,42157,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stell dir vor: Angeblich wird er sich bis Freitag an jede Karte aus dem Stapel ...'::text,'erinnert haben'::text,'erinnern'::text,'erinnert'::text,'Stell dir vor: Angeblich wird er sich bis Freitag an jede Karte aus dem Stapel erinnert haben.'::text),
(379411,42157,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви: кажуть, до п''ятниці він ... кожну картку з тієї купки.'::text,'вже згадає'::text,'згадає'::text,'згадує'::text,'Уяви: кажуть, до п''ятниці він вже згадає кожну картку з тієї купки.'::text),
(379410,42157,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fíjate: supuestamente, para el viernes ya ... todas las tarjetas de ese montón.'::text,'habrá recordado'::text,'recordará'::text,'recuerda'::text,'Fíjate: supuestamente, para el viernes ya habrá recordado todas las tarjetas de ese montón.'::text),
(379409,42157,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute ça : apparemment, d''ici vendredi, il se ... de chaque carte de cette pile.'::text,'sera souvenu'::text,'souviendra'::text,'souvient'::text,'Écoute ça : apparemment, d''ici vendredi, il se sera souvenu de chaque carte de cette pile.'::text),
(379412,42157,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şuna bak: güya cuma gününe kadar o destedeki her kartı ...'::text,'hatırlamış olacak'::text,'hatırlayacak'::text,'hatırlıyor'::text,'Şuna bak: güya cuma gününe kadar o destedeki her kartı hatırlamış olacak.'::text),
(379413,42157,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj: állítólag péntekig már az összes kártyát ... abból a kupacból.'::text,'felidézi'::text,'fel fogja idézni'::text,'idézi fel'::text,'Figyelj: állítólag péntekig már az összes kártyát felidézi abból a kupacból.'::text),
(375402,41712,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während der Koch Schweinefleisch vom Spieß ..., erreichte der Stand sein Verkaufsziel von 200 Tacos.'::text,'abschnitt'::text,'abschnitt'::text,'abgeschnitten hat'::text,'Während der Koch Schweinefleisch vom Spieß abschnitt, erreichte der Stand sein Verkaufsziel von 200 Tacos.'::text),
(375406,41712,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки кухар ... свинину з рожна, ятка виконала план продажів на 200 тако.'::text,'зрізував'::text,'зрізав'::text,'зрізав'::text,'Поки кухар зрізував свинину з рожна, ятка виконала план продажів на 200 тако.'::text),
(375405,41712,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el cocinero ... cerdo del asador, el puesto alcanzó su objetivo de ventas de 200 tacos.'::text,'cortaba'::text,'cortó'::text,'ha cortado'::text,'Mientras el cocinero cortaba cerdo del asador, el puesto alcanzó su objetivo de ventas de 200 tacos.'::text),
(375404,41712,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le cuisinier ... du porc de la broche, le stand a atteint son objectif de 200 tacos vendus.'::text,'découpait'::text,'a découpé'::text,'a découpé'::text,'Pendant que le cuisinier découpait du porc de la broche, le stand a atteint son objectif de 200 tacos vendus.'::text),
(375407,41712,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aşçı şişten domuz eti ..., stant 200 takoluk satış hedefine ulaştı.'::text,'keserken'::text,'kesti'::text,'kesmiş'::text,'Aşçı şişten domuz eti keserken, stant 200 takoluk satış hedefine ulaştı.'::text),
(375408,41712,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a szakács ... a sertéshúst a nyársról, a stand elérte a 200 tacós eladási célját.'::text,'szeletelte'::text,'leszeletelte'::text,'leszeletelte'::text,'Miközben a szakács szeletelte a sertéshúst a nyársról, a stand elérte a 200 tacós eladási célját.'::text),
(375411,41713,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Koch ... die ganze Nacht Schweinefleisch, also gibt es viel Schweinefleisch.'::text,'schneidet'::text,'schneidet'::text,'schneidet'::text,'Der Koch schneidet die ganze Nacht Schweinefleisch, also gibt es viel Schweinefleisch.'::text),
(375415,41713,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кухар ... свинину всю ніч, тож свинини дуже багато.'::text,'ріже'::text,'ріже'::text,'ріже'::text,'Кухар ріже свинину всю ніч, тож свинини дуже багато.'::text),
(375414,41713,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cocinero ... cerdo toda la noche, así que hay mucho cerdo.'::text,'ha estado cortando'::text,'está cortando'::text,'corta'::text,'El cocinero ha estado cortando cerdo toda la noche, así que hay mucho cerdo.'::text),
(375413,41713,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça fait toute la nuit que le cuisinier ... du porc, donc il y a beaucoup de porc.'::text,'coupe'::text,'coupe'::text,'coupe'::text,'Ça fait toute la nuit que le cuisinier coupe du porc, donc il y a beaucoup de porc.'::text),
(375416,41713,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aşçı bütün gece domuz eti ..., yani çok domuz eti var.'::text,'kesiyor'::text,'kesiyor'::text,'keser'::text,'Aşçı bütün gece domuz eti kesiyor, yani çok domuz eti var.'::text),
(375417,41713,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szakács egész éjjel ... a sertéshúst, szóval sok sertéshús van.'::text,'vágja'::text,'vágja'::text,'vágja'::text,'A szakács egész éjjel vágja a sertéshúst, szóval sok sertéshús van.'::text),
(375429,41715,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mitternacht wirst du diesen ganzen Spieß Schweinefleisch in Tacos ..., ehrlich.'::text,'verwandelt haben'::text,'verwandeln'::text,'verwandelst'::text,'Bis Mitternacht wirst du diesen ganzen Spieß Schweinefleisch in Tacos verwandelt haben, ehrlich.'::text),
(375433,41715,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До півночі ти ... весь цей рожен свинини на тако, чесно.'::text,'вже перетвориш'::text,'перетвориш'::text,'перетворюєш'::text,'До півночі ти вже перетвориш весь цей рожен свинини на тако, чесно.'::text),
(375432,41715,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para medianoche ya ... todo ese asador de cerdo en tacos, en serio.'::text,'habrás convertido'::text,'convertirás'::text,'estás convirtiendo'::text,'Para medianoche ya habrás convertido todo ese asador de cerdo en tacos, en serio.'::text),
(375431,41715,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici minuit, tu ... toute cette broche de porc en tacos, franchement.'::text,'auras transformé'::text,'transformeras'::text,'transformes'::text,'D''ici minuit, tu auras transformé toute cette broche de porc en tacos, franchement.'::text),
(375434,41715,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısına kadar o koca şiş domuz etini takoya ..., cidden.'::text,'dönüştürmüş olacaksın'::text,'dönüştüreceksin'::text,'dönüştürüyorsun'::text,'Gece yarısına kadar o koca şiş domuz etini takoya dönüştürmüş olacaksın, cidden.'::text),
(375435,41715,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélre az egész nyárs sertéshúst tacókká ..., őszintén.'::text,'átváltoztatod'::text,'át fogod változtatni'::text,'változtatod'::text,'Éjfélre az egész nyárs sertéshúst tacókká átváltoztatod, őszintén.'::text),
(375447,41717,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Koch empfahl, die Schweinefleisch-Tacos mit extra Zwiebeln zu ...'::text,'probieren'::text,'probieren'::text,'probiert'::text,'Der Koch empfahl, die Schweinefleisch-Tacos mit extra Zwiebeln zu probieren.'::text),
(375451,41717,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кухар порадив ... тако зі свининою з додатковою цибулею.'::text,'скуштувати'::text,'скуштувати'::text,'скуштував'::text,'Кухар порадив скуштувати тако зі свининою з додатковою цибулею.'::text),
(375450,41717,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cocinero recomendó ... los tacos de cerdo con cebolla extra.'::text,'probar'::text,'probar'::text,'probó'::text,'El cocinero recomendó probar los tacos de cerdo con cebolla extra.'::text),
(375449,41717,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cuisinier a recommandé de ... les tacos au porc avec un supplément d''oignon.'::text,'goûter'::text,'goûter'::text,'goûté'::text,'Le cuisinier a recommandé de goûter les tacos au porc avec un supplément d''oignon.'::text),
(375452,41717,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aşçı, domuz etli takoları ekstra soğanla ... önerdi.'::text,'denemeyi'::text,'denemeyi'::text,'denedi'::text,'Aşçı, domuz etli takoları ekstra soğanla denemeyi önerdi.'::text),
(375453,41717,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szakács azt ajánlotta, hogy ... meg a sertéshúsos tacót extra hagymával.'::text,'kóstolják'::text,'kóstolják'::text,'kóstolták'::text,'A szakács azt ajánlotta, hogy kóstolják meg a sertéshúsos tacót extra hagymával.'::text),
(375456,41718,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kunde ... drei Schweinefleisch-Tacos bestellt haben, denn auf dem Teller liegen drei.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Der Kunde muss drei Schweinefleisch-Tacos bestellt haben, denn auf dem Teller liegen drei.'::text),
(375460,41718,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клієнт ... замовив три тако зі свининою, бо на тарілці їх три.'::text,'напевно'::text,'не міг'::text,'не мав'::text,'Клієнт напевно замовив три тако зі свининою, бо на тарілці їх три.'::text),
(375459,41718,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cliente ... pedido tres tacos de cerdo, porque hay tres en el plato.'::text,'debe de haber'::text,'no puede haber'::text,'no debe haber'::text,'El cliente debe de haber pedido tres tacos de cerdo, porque hay tres en el plato.'::text),
(375458,41718,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le client ... commandé trois tacos au porc, car il y en a trois dans l''assiette.'::text,'a dû'::text,'n''a pas pu'::text,'n''a pas dû'::text,'Le client a dû commandé trois tacos au porc, car il y en a trois dans l''assiette.'::text),
(375461,41718,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabakta üç tane olduğuna göre müşteri üç domuz etli tako ...'::text,'sipariş etmiş olmalı'::text,'sipariş etmiş olamaz'::text,'sipariş etmemiş olmalı'::text,'Tabakta üç tane olduğuna göre müşteri üç domuz etli tako sipariş etmiş olmalı.'::text),
(375462,41718,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendég ... három sertéshúsos tacót, mert három van a tányéron.'::text,'biztosan rendelt'::text,'nem rendelhetett'::text,'nem szabadott rendelnie'::text,'A vendég biztosan rendelt három sertéshúsos tacót, mert három van a tányéron.'::text),
(375465,41719,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, der Besitzer lässt den Koch jeden Abend das Schweinefleisch vom Spieß ...'::text,'abschneiden'::text,'abschneiden'::text,'abschneidend'::text,'Bestie, ich hab gehört, der Besitzer lässt den Koch jeden Abend das Schweinefleisch vom Spieß abschneiden.'::text),
(375469,41719,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що власник щовечора змушує кухаря ... свинину з рожна.'::text,'зрізати'::text,'зрізати'::text,'зрізання'::text,'Подруго, я чула, що власник щовечора змушує кухаря зрізати свинину з рожна.'::text),
(375468,41719,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, he oído que el dueño consigue que el cocinero ... el cerdo del asador cada noche.'::text,'corte'::text,'cortar'::text,'cortando'::text,'Amiga, he oído que el dueño consigue que el cocinero corte el cerdo del asador cada noche.'::text),
(375467,41719,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il paraît que le patron fait ... le porc de la broche au cuisinier tous les soirs.'::text,'découper'::text,'découper'::text,'découpant'::text,'Meuf, il paraît que le patron fait découper le porc de la broche au cuisinier tous les soirs.'::text),
(375470,41719,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki mekan sahibi her gece aşçıya domuz etini şişten ...'::text,'kestiriyormuş'::text,'kestiriyormuş'::text,'kesme'::text,'Kanka, duydum ki mekan sahibi her gece aşçıya domuz etini şişten kestiriyormuş.'::text),
(375471,41719,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, a tulaj minden este ... a szakáccsal a sertéshúst a nyársról.'::text,'levágatja'::text,'levágatja'::text,'levágva'::text,'Csajszi, azt hallottam, a tulaj minden este levágatja a szakáccsal a sertéshúst a nyársról.'::text),
(375474,41720,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er hat mir erzählt, er wünschte, er ... gestern Abend noch einen Schweinefleisch-Taco bestellt.'::text,'hätte'::text,'bestellte'::text,'würde'::text,'Bestie, er hat mir erzählt, er wünschte, er hätte gestern Abend noch einen Schweinefleisch-Taco bestellt.'::text),
(375478,41720,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що хотів би вчора ввечері ... ще одне тако зі свининою.'::text,'замовити'::text,'замовити'::text,'замовити'::text,'Подруго, він сказав мені, що хотів би вчора ввечері замовити ще одне тако зі свининою.'::text),
(375477,41720,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ojalá ... otro taco de cerdo anoche.'::text,'hubiera pedido'::text,'pidiera'::text,'pediría'::text,'Amiga, me dijo que ojalá hubiera pedido otro taco de cerdo anoche.'::text),
(375476,41720,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il m''a dit qu''il aimerait ... un taco au porc de plus hier soir.'::text,'avoir commandé'::text,'commander'::text,'commander'::text,'Ma belle, il m''a dit qu''il aimerait avoir commandé un taco au porc de plus hier soir.'::text),
(375479,41720,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana dedi ki keşke dün akşam bir domuz etli tako daha ...'::text,'sipariş etseydim'::text,'sipariş etsem'::text,'sipariş ederdim'::text,'Kanka, bana dedi ki keşke dün akşam bir domuz etli tako daha sipariş etseydim.'::text),
(375480,41720,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, bárcsak ... még egy sertéshúsos tacót tegnap este.'::text,'rendelt volna'::text,'rendelne'::text,'rendelne'::text,'Csajszi, azt mondta, bárcsak rendelt volna még egy sertéshúsos tacót tegnap este.'::text),
(375483,41721,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Schweinefleisch bleibt saftig ... des langsamen Garens am Spieß.'::text,'dank'::text,'trotz'::text,'obwohl'::text,'Das Schweinefleisch bleibt saftig dank des langsamen Garens am Spieß.'::text),
(375487,41721,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Свинина залишається соковитою ... повільному запіканню на рожні.'::text,'завдяки'::text,'попри'::text,'хоча'::text,'Свинина залишається соковитою завдяки повільному запіканню на рожні.'::text),
(375486,41721,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cerdo se mantiene jugoso ... la lenta cocción en el asador.'::text,'gracias a'::text,'a pesar de'::text,'aunque'::text,'El cerdo se mantiene jugoso gracias a la lenta cocción en el asador.'::text),
(375485,41721,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le porc reste juteux ... la cuisson lente à la broche.'::text,'grâce à'::text,'malgré'::text,'bien que'::text,'Le porc reste juteux grâce à la cuisson lente à la broche.'::text),
(375488,41721,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Domuz eti, şişte yavaş pişirilmesi ... sulu kalıyor.'::text,'sayesinde'::text,'rağmen'::text,'gerçi'::text,'Domuz eti, şişte yavaş pişirilmesi sayesinde sulu kalıyor.'::text),
(375489,41721,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sertéshús a nyárson való lassú sütés ... szaftos marad.'::text,'miatt'::text,'ellenére'::text,'bár'::text,'A sertéshús a nyárson való lassú sütés miatt szaftos marad.'::text),
(375492,41722,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, bis wir da sind, wird er das ganze Schweinefleisch ..., ohne Witz.'::text,'verkauft haben'::text,'verkaufen'::text,'verkauft'::text,'Yo, bis wir da sind, wird er das ganze Schweinefleisch verkauft haben, ohne Witz.'::text),
(375496,41722,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, поки ми туди доберемося, він ... всю свинину, без жартів.'::text,'вже продасть'::text,'продасть'::text,'продає'::text,'Йо, поки ми туди доберемося, він вже продасть всю свинину, без жартів.'::text),
(375495,41722,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, para cuando lleguemos, ya ... todo el cerdo, en serio.'::text,'habrá vendido'::text,'venderá'::text,'vende'::text,'Tío, para cuando lleguemos, ya habrá vendido todo el cerdo, en serio.'::text),
(375494,41722,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, le temps qu''on arrive, il ... tout le porc, sans mentir.'::text,'aura vendu'::text,'vendra'::text,'vend'::text,'Wesh, le temps qu''on arrive, il aura vendu tout le porc, sans mentir.'::text),
(375497,41722,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, biz oraya varana kadar bütün domuz etini ..., cidden.'::text,'satmış olacak'::text,'satacak'::text,'satıyor'::text,'Kanka, biz oraya varana kadar bütün domuz etini satmış olacak, cidden.'::text),
(375498,41722,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire odaérünk, már az összes sertéshúst ..., komolyan.'::text,'eladja'::text,'el fogja adni'::text,'árulja'::text,'Tesó, mire odaérünk, már az összes sertéshúst eladja, komolyan.'::text),
(377769,41975,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Reisende hat den Gipfel der Pyramide ..., was erheblichen Aufwand erfordert.'::text,'erklommen'::text,'erklommen'::text,'erklimmt'::text,'Die Reisende hat den Gipfel der Pyramide erklommen, was erheblichen Aufwand erfordert.'::text),
(377773,41975,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мандрівниця ... на вершину піраміди, що потребує значних зусиль.'::text,'піднялася'::text,'піднімалася'::text,'піднімається'::text,'Мандрівниця піднялася на вершину піраміди, що потребує значних зусиль.'::text),
(377772,41975,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La viajera ... hasta la cima de la pirámide, lo cual requiere un esfuerzo considerable.'::text,'ha subido'::text,'ha estado subiendo'::text,'sube'::text,'La viajera ha subido hasta la cima de la pirámide, lo cual requiere un esfuerzo considerable.'::text),
(377771,41975,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voyageuse ... au sommet de la pyramide, ce qui demande un effort considérable.'::text,'est montée'::text,'monte depuis'::text,'monte'::text,'La voyageuse est montée au sommet de la pyramide, ce qui demande un effort considérable.'::text),
(377774,41975,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gezgin piramidin tepesine ..., bu da ciddi çaba gerektirir.'::text,'tırmandı'::text,'tırmanıyor'::text,'tırmanır'::text,'Gezgin piramidin tepesine tırmandı, bu da ciddi çaba gerektirir.'::text),
(377775,41975,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utazó ... a piramis tetejére, ami jelentős erőfeszítést igényel.'::text,'felmászott'::text,'mászott'::text,'mászik'::text,'Az utazó felmászott a piramis tetejére, ami jelentős erőfeszítést igényel.'::text),
(377778,41976,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... einen Taco gegessen, bevor du auf die Pyramide geklettert bist, kluger Move.'::text,'hattest'::text,'hast'::text,'isst'::text,'Ehrlich, du hattest einen Taco gegessen, bevor du auf die Pyramide geklettert bist, kluger Move.'::text),
(377782,41976,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... тако ще до того, як піднялася на піраміду, розумний хід.'::text,'з''їла'::text,'з''їла'::text,'їси'::text,'Чесно, ти з''їла тако ще до того, як піднялася на піраміду, розумний хід.'::text),
(377781,41976,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... un taco antes de subir a la pirámide, muy lista.'::text,'te habías comido'::text,'te has comido'::text,'te comes'::text,'La verdad, te habías comido un taco antes de subir a la pirámide, muy lista.'::text),
(377780,41976,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... un taco avant de grimper sur la pyramide, bien joué.'::text,'avais mangé'::text,'as mangé'::text,'manges'::text,'Franchement, tu avais mangé un taco avant de grimper sur la pyramide, bien joué.'::text),
(377783,41976,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, piramide tırmanmadan önce bir tako ..., akıllıca hamle.'::text,'yemiştin'::text,'yedin'::text,'yiyorsun'::text,'Açıkçası, piramide tırmanmadan önce bir tako yemiştin, akıllıca hamle.'::text),
(377784,41976,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... egy tacót, mielőtt felmásztál a piramisra, okos húzás.'::text,'megettél'::text,'megettél'::text,'eszel'::text,'Őszintén, megettél egy tacót, mielőtt felmásztál a piramisra, okos húzás.'::text),
(377787,41977,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du das Pyramidenfoto postest, ... es das beste Reisefoto aller Zeiten, ehrlich gesagt.'::text,'wird'::text,'wäre'::text,'war'::text,'Wenn du das Pyramidenfoto postest, wird es das beste Reisefoto aller Zeiten, ehrlich gesagt.'::text),
(377791,41977,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти викладеш те фото з пірамідою, це ... найкраще фото з подорожей усіх часів, не брехатиму.'::text,'буде'::text,'було б'::text,'було'::text,'Якщо ти викладеш те фото з пірамідою, це буде найкраще фото з подорожей усіх часів, не брехатиму.'::text),
(377790,41977,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si subes esa foto de la pirámide, ... la mejor foto de viaje de la historia, no te voy a mentir.'::text,'será'::text,'sería'::text,'era'::text,'Si subes esa foto de la pirámide, será la mejor foto de viaje de la historia, no te voy a mentir.'::text),
(377789,41977,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu postes cette photo de la pyramide, ce ... la meilleure photo de voyage de tous les temps, j''te mens pas.'::text,'sera'::text,'serait'::text,'était'::text,'Si tu postes cette photo de la pyramide, ce sera la meilleure photo de voyage de tous les temps, j''te mens pas.'::text),
(377792,41977,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O piramit fotoğrafını paylaşırsan, gelmiş geçmiş en iyi seyahat fotoğrafı ..., yalan yok.'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'O piramit fotoğrafını paylaşırsan, gelmiş geçmiş en iyi seyahat fotoğrafı olacak, yalan yok.'::text),
(377793,41977,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kirakod azt a piramisos fotót, ... minden idők legjobb utazós képe, nem hazudok.'::text,'az lesz'::text,'az lenne'::text,'az volt'::text,'Ha kirakod azt a piramisos fotót, az lesz minden idők legjobb utazós képe, nem hazudok.'::text),
(377796,41978,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Stufen nicht so abgenutzt wären, ... sie schneller auf die Pyramide klettern.'::text,'würde'::text,'wird'::text,'kletterte'::text,'Wenn die Stufen nicht so abgenutzt wären, würde sie schneller auf die Pyramide klettern.'::text),
(377800,41978,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби сходинки не були такими стертими, вона ... на піраміду швидше.'::text,'піднялася б'::text,'підніметься'::text,'піднялася'::text,'Якби сходинки не були такими стертими, вона піднялася б на піраміду швидше.'::text),
(377799,41978,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los escalones no estuvieran tan desgastados, ... la pirámide más rápido.'::text,'subiría'::text,'subirá'::text,'subió'::text,'Si los escalones no estuvieran tan desgastados, subiría la pirámide más rápido.'::text),
(377798,41978,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les marches n''étaient pas si usées, elle ... la pyramide plus vite.'::text,'gravirait'::text,'gravira'::text,'a gravi'::text,'Si les marches n''étaient pas si usées, elle gravirait la pyramide plus vite.'::text),
(377801,41978,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Basamaklar bu kadar aşınmış olmasaydı, piramide daha hızlı ...'::text,'tırmanırdı'::text,'tırmanacak'::text,'tırmandı'::text,'Basamaklar bu kadar aşınmış olmasaydı, piramide daha hızlı tırmanırdı.'::text),
(377802,41978,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a lépcsők nem lennének ennyire kopottak, gyorsabban ... fel a piramisra.'::text,'mászna'::text,'fog mászni'::text,'mászott'::text,'Ha a lépcsők nem lennének ennyire kopottak, gyorsabban mászna fel a piramisra.'::text),
(377805,41979,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pyramide ... vor Hunderten von Jahren von einem alten Volk erbaut.'::text,'wurde'::text,'baute'::text,'baut'::text,'Die Pyramide wurde vor Hunderten von Jahren von einem alten Volk erbaut.'::text),
(377809,41979,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Піраміда ... стародавнім народом сотні років тому.'::text,'була збудована'::text,'збудувала'::text,'будує'::text,'Піраміда була збудована стародавнім народом сотні років тому.'::text),
(377808,41979,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pirámide ... por un pueblo antiguo hace cientos de años.'::text,'fue construida'::text,'construyó'::text,'está construyendo'::text,'La pirámide fue construida por un pueblo antiguo hace cientos de años.'::text),
(377807,41979,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pyramide ... par un peuple ancien il y a des centaines d''années.'::text,'a été construite'::text,'a construit'::text,'est en train de construire'::text,'La pyramide a été construite par un peuple ancien il y a des centaines d''années.'::text),
(377810,41979,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Piramit yüzlerce yıl önce eski bir halk tarafından ...'::text,'inşa edildi'::text,'inşa etti'::text,'inşa ediyor'::text,'Piramit yüzlerce yıl önce eski bir halk tarafından inşa edildi.'::text),
(377811,41979,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piramis egy ősi nép által ... több száz évvel ezelőtt.'::text,'épült'::text,'épített'::text,'épít'::text,'A piramis egy ősi nép által épült több száz évvel ezelőtt.'::text),
(377814,41980,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die alten Steinstufen bis zur Spitze der Pyramide hinauf.'::text,'stieg'::text,'wurde gestiegen'::text,'steigend'::text,'Sie stieg die alten Steinstufen bis zur Spitze der Pyramide hinauf.'::text),
(377818,41980,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... старими кам''яними сходами аж на вершину піраміди.'::text,'піднялася'::text,'була піднята'::text,'підйом'::text,'Вона піднялася старими кам''яними сходами аж на вершину піраміди.'::text),
(377817,41980,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... los viejos escalones de piedra hasta la cima de la pirámide.'::text,'subió'::text,'fue subida'::text,'subiendo'::text,'Ella subió los viejos escalones de piedra hasta la cima de la pirámide.'::text),
(377816,41980,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les vieilles marches de pierre jusqu''au sommet de la pyramide.'::text,'a gravi'::text,'a été gravie'::text,'gravissant'::text,'Elle a gravi les vieilles marches de pierre jusqu''au sommet de la pyramide.'::text),
(377819,41980,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski taş basamakları piramidin tepesine kadar ...'::text,'çıktı'::text,'çıkıldı'::text,'çıkan'::text,'Eski taş basamakları piramidin tepesine kadar çıktı.'::text),
(377820,41980,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a régi kőlépcsőkön egészen a piramis tetejéig.'::text,'felmászott'::text,'fel lett mászva'::text,'felmászva'::text,'Ő felmászott a régi kőlépcsőkön egészen a piramis tetejéig.'::text),
(377823,41981,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie ist oben auf einer Pyramide; die Aussicht ... angeblich unglaublich sein.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Rate mal, sie ist oben auf einer Pyramide; die Aussicht muss angeblich unglaublich sein.'::text),
(377827,41981,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона на вершині піраміди; кажуть, краєвид ... бути неймовірним.'::text,'мусить'::text,'не може'::text,'не повинен'::text,'Уяви, вона на вершині піраміди; кажуть, краєвид мусить бути неймовірним.'::text),
(377826,41981,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué: está en lo alto de una pirámide; al parecer, la vista ... ser increíble.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Adivina qué: está en lo alto de una pirámide; al parecer, la vista debe de ser increíble.'::text),
(377825,41981,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi : elle est au sommet d''une pyramide ; apparemment, la vue ... être incroyable.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Devine quoi : elle est au sommet d''une pyramide ; apparemment, la vue doit être incroyable.'::text),
(377828,41981,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, bir piramidin tepesinde; anlaşılan manzara inanılmaz ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Bil bakalım ne oldu, bir piramidin tepesinde; anlaşılan manzara inanılmaz olmalı.'::text),
(377829,41981,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, egy piramis tetején van; a kilátás állítólag ... elképesztő.'::text,'biztos'::text,'nem lehet'::text,'nem szabad, hogy'::text,'Képzeld, egy piramis tetején van; a kilátás állítólag biztos elképesztő.'::text),
(377832,41982,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Pyramide, auf ... sie geklettert ist, war lowkey das Beste am Trip.'::text,'die'::text,'wer'::text,'wo'::text,'Bro, die Pyramide, auf die sie geklettert ist, war lowkey das Beste am Trip.'::text),
(377836,41982,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, піраміда, на ... вона піднялася, була, чесно кажучи, найкращою частиною поїздки.'::text,'яку'::text,'кого'::text,'де'::text,'Бро, піраміда, на яку вона піднялася, була, чесно кажучи, найкращою частиною поїздки.'::text),
(377835,41982,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la pirámide ... subió fue, en plan, lo mejor del viaje.'::text,'a la que'::text,'quien'::text,'donde'::text,'Bro, la pirámide a la que subió fue, en plan, lo mejor del viaje.'::text),
(377834,41982,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, la pyramide ... elle a grimpé était genre le meilleur moment du voyage.'::text,'sur laquelle'::text,'qui'::text,'où'::text,'Frérot, la pyramide sur laquelle elle a grimpé était genre le meilleur moment du voyage.'::text),
(377837,41982,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... tırmandığı piramit gizliden gizliye gezinin en iyi kısmıydı.'::text,''::text,NULL::text,NULL::text,'Kanka, tırmandığı piramit gizliden gizliye gezinin en iyi kısmıydı.'::text),
(377838,41982,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a piramis, ... felmászott, lowkey az utazás legjobb része volt.'::text,'amelyikre'::text,'aki'::text,'ahol'::text,'Tesó, a piramis, amelyikre felmászott, lowkey az utazás legjobb része volt.'::text),
(377841,41983,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie meinte, sie ... am Tag davor die Pyramide hochgeklettert, lowkey neidisch.'::text,'sei'::text,'ist'::text,'klettert'::text,'Alter, sie meinte, sie sei am Tag davor die Pyramide hochgeklettert, lowkey neidisch.'::text),
(377845,41983,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, вона сказала, що напередодні ... на піраміду, трохи заздрю.'::text,'піднялася'::text,'піднялася'::text,'піднімається'::text,'Чувак, вона сказала, що напередодні піднялася на піраміду, трохи заздрю.'::text),
(377844,41983,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, dijo que ... a la pirámide el día anterior, me da un poco de envidia.'::text,'había subido'::text,'ha subido'::text,'sube'::text,'Tío, dijo que había subido a la pirámide el día anterior, me da un poco de envidia.'::text),
(377843,41983,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle a dit qu''elle ... la pyramide la veille, un peu jaloux.'::text,'avait gravi'::text,'a gravi'::text,'gravit'::text,'Mec, elle a dit qu''elle avait gravi la pyramide la veille, un peu jaloux.'::text),
(377846,41983,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir gün önce piramide ... söyledi, biraz kıskandım.'::text,'tırmandığını'::text,'tırmandığını'::text,'tırmandığını'::text,'Kanka, bir gün önce piramide tırmandığını söyledi, biraz kıskandım.'::text),
(377847,41983,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azt mondta, hogy előző nap ... a piramisra, lowkey irigylem.'::text,'felmászott'::text,'felmászott'::text,'felmászik'::text,'Tesó, azt mondta, hogy előző nap felmászott a piramisra, lowkey irigylem.'::text),
(377859,41985,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie beschloss, auf die Pyramide zu ..., weil sie da war, also kletterte sie hinauf.'::text,'klettern'::text,'klettern'::text,'klettern'::text,'Sie beschloss, auf die Pyramide zu klettern, weil sie da war, also kletterte sie hinauf.'::text),
(377863,41985,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вирішила ... на піраміду, бо вона там була, тож вона на неї піднялася.'::text,'піднятися'::text,'піднятися'::text,'піднятися'::text,'Вона вирішила піднятися на піраміду, бо вона там була, тож вона на неї піднялася.'::text),
(377862,41985,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Decidió ... a la pirámide porque estaba ahí, así que subió.'::text,'subir'::text,'subir'::text,'subir'::text,'Decidió subir a la pirámide porque estaba ahí, así que subió.'::text),
(377861,41985,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a décidé de ... la pyramide parce qu''elle était là, alors elle l''a gravie.'::text,'gravir'::text,'gravir'::text,'gravir'::text,'Elle a décidé de gravir la pyramide parce qu''elle était là, alors elle l''a gravie.'::text),
(377864,41985,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Piramit orada olduğu için ona ... karar verdi, o yüzden tırmandı.'::text,'tırmanmaya'::text,'tırmanmaya'::text,'tırmanmaya'::text,'Piramit orada olduğu için ona tırmanmaya karar verdi, o yüzden tırmandı.'::text),
(377865,41985,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy döntött, hogy ... a piramisra, mert ott volt, ezért felmászott rá.'::text,'felmászik'::text,'felmászik'::text,'felmászik'::text,'Úgy döntött, hogy felmászik a piramisra, mert ott volt, ezért felmászott rá.'::text),
(334371,37153,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie gerade Beeren für noch einen Kuchen.'::text,'waschen'::text,'waschen'::text,'waschen'::text,'Morgen um diese Zeit waschen sie gerade Beeren für noch einen Kuchen.'::text),
(334375,37153,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вони ... ягоди для ще одного торта.'::text,'митимуть'::text,'помиють'::text,'миють'::text,'Завтра в цей час вони митимуть ягоди для ще одного торта.'::text),
(334374,37153,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... frutos rojos para otra tarta.'::text,'estarán lavando'::text,'lavarán'::text,'lavan'::text,'Mañana a esta hora estarán lavando frutos rojos para otra tarta.'::text),
(334373,37153,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, elles ... des fruits rouges pour un autre gâteau.'::text,'seront en train de laver'::text,'laveront'::text,'lavent'::text,'Demain à cette heure-ci, elles seront en train de laver des fruits rouges pour un autre gâteau.'::text),
(334376,37153,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte başka bir kek için orman meyvesi ...'::text,'yıkıyor olacaklar'::text,'yıkayacaklar'::text,'yıkıyorlar'::text,'Yarın bu saatte başka bir kek için orman meyvesi yıkıyor olacaklar.'::text),
(334377,37153,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor épp bogyós gyümölcsöt ... egy újabb tortához.'::text,'fognak mosni'::text,'megmosnak'::text,'mosnak'::text,'Holnap ilyenkor épp bogyós gyümölcsöt fognak mosni egy újabb tortához.'::text),
(334380,37154,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie beschließen gerade, dass sie beim nächsten Mal weniger Beeren ...'::text,'hinzufügen werden'::text,'hinzufügen werden'::text,'hinzufügen'::text,'Sie beschließen gerade, dass sie beim nächsten Mal weniger Beeren hinzufügen werden.'::text),
(334384,37154,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони просто зараз вирішують, що наступного разу ... менше ягід.'::text,'додадуть'::text,'додаватимуть'::text,'додають'::text,'Вони просто зараз вирішують, що наступного разу додадуть менше ягід.'::text),
(334383,37154,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deciden ahora mismo que la próxima vez ... menos frutos rojos.'::text,'añadirán'::text,'estarán añadiendo'::text,'están añadiendo'::text,'Deciden ahora mismo que la próxima vez añadirán menos frutos rojos.'::text),
(334382,37154,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles décident à l''instant que la prochaine fois, elles ... moins de fruits rouges.'::text,'mettront'::text,'seront en train de mettre'::text,'mettent'::text,'Elles décident à l''instant que la prochaine fois, elles mettront moins de fruits rouges.'::text),
(334385,37154,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda bir dahaki sefere daha az orman meyvesi ... karar veriyorlar.'::text,'koyacaklarına'::text,'koyuyor olacaklarına'::text,'koyduklarına'::text,'Şu anda bir dahaki sefere daha az orman meyvesi koyacaklarına karar veriyorlar.'::text),
(334386,37154,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most döntik el, hogy legközelebb kevesebb bogyós gyümölcsöt ... bele.'::text,'tesznek'::text,'fognak tenni'::text,'tesznek'::text,'Épp most döntik el, hogy legközelebb kevesebb bogyós gyümölcsöt tesznek bele.'::text),
(334389,37155,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du Beeren in den Teig ..., hat der Teig Beeren, also ist es Beerenteig.'::text,'kippst'::text,'kipptest'::text,'kippen wirst'::text,'Wenn du Beeren in den Teig kippst, hat der Teig Beeren, also ist es Beerenteig.'::text),
(334393,37155,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ... ягоди в тісто, то в тісті є ягоди, тож це ягідне тісто.'::text,'висипаєш'::text,'висипав'::text,'висипатимеш'::text,'Якщо висипаєш ягоди в тісто, то в тісті є ягоди, тож це ягідне тісто.'::text),
(334392,37155,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ... frutos rojos en la masa, la masa tiene frutos rojos, así que es masa de frutos rojos.'::text,'echas'::text,'echaste'::text,'echarás'::text,'Si echas frutos rojos en la masa, la masa tiene frutos rojos, así que es masa de frutos rojos.'::text),
(334391,37155,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu ... des fruits rouges dans la pâte, la pâte contient des fruits rouges, donc c''est une pâte aux fruits rouges.'::text,'verses'::text,'versais'::text,'verseras'::text,'Si tu verses des fruits rouges dans la pâte, la pâte contient des fruits rouges, donc c''est une pâte aux fruits rouges.'::text),
(334394,37155,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamura orman meyvesi ..., hamurda orman meyvesi olur, yani bu orman meyveli hamurdur.'::text,'dökersen'::text,'döktüysen'::text,'dökeceksen'::text,'Hamura orman meyvesi dökersen, hamurda orman meyvesi olur, yani bu orman meyveli hamurdur.'::text),
(334395,37155,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha bogyós gyümölcsöt ... a tésztába, a tésztában bogyós gyümölcs van, tehát ez bogyós tészta.'::text,'öntesz'::text,'öntöttél'::text,'fogsz önteni'::text,'Ha bogyós gyümölcsöt öntesz a tésztába, a tésztában bogyós gyümölcs van, tehát ez bogyós tészta.'::text),
(334398,37156,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine der Bäckerinnen stellte fest, dass der Teig schwerer ..., nachdem die Beeren hinzugefügt worden waren.'::text,'geworden war'::text,'geworden ist'::text,'wird'::text,'Eine der Bäckerinnen stellte fest, dass der Teig schwerer geworden war, nachdem die Beeren hinzugefügt worden waren.'::text),
(334402,37156,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна з пекарок зауважила, що тісто ... важчим, щойно додали ягоди.'::text,'стало'::text,'стало'::text,'стає'::text,'Одна з пекарок зауважила, що тісто стало важчим, щойно додали ягоди.'::text),
(334401,37156,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una de las reposteras observó que la masa ... más pesada una vez añadidos los frutos rojos.'::text,'se había vuelto'::text,'se ha vuelto'::text,'se vuelve'::text,'Una de las reposteras observó que la masa se había vuelto más pesada una vez añadidos los frutos rojos.'::text),
(334400,37156,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''une des pâtissières a observé que la pâte ... plus lourde une fois les fruits rouges ajoutés.'::text,'était devenue'::text,'est devenue'::text,'devient'::text,'L''une des pâtissières a observé que la pâte était devenue plus lourde une fois les fruits rouges ajoutés.'::text),
(334403,37156,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pastacılardan biri, orman meyveleri eklendikten sonra hamurun ... gözlemledi.'::text,'ağırlaşmış olduğunu'::text,'ağırlaştığını'::text,'ağırlaştığını'::text,'Pastacılardan biri, orman meyveleri eklendikten sonra hamurun ağırlaşmış olduğunu gözlemledi.'::text),
(334404,37156,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyik cukrász megfigyelte, hogy a tészta nehezebb ..., amint hozzáadták a bogyós gyümölcsöt.'::text,'lett'::text,'lett'::text,'lesz'::text,'Az egyik cukrász megfigyelte, hogy a tészta nehezebb lett, amint hozzáadták a bogyós gyümölcsöt.'::text),
(334416,37158,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie können nicht aufhören, den Beerenteig zu ..., und er ist komplett ruiniert!'::text,'rühren'::text,'rühren'::text,'rühren'::text,'Sie können nicht aufhören, den Beerenteig zu rühren, und er ist komplett ruiniert!'::text),
(334420,37158,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони не можуть перестати ... ягідне тісто, і воно геть зіпсоване!'::text,'мішати'::text,'мішати'::text,'мішати'::text,'Вони не можуть перестати мішати ягідне тісто, і воно геть зіпсоване!'::text),
(334419,37158,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No pueden dejar de ... la masa de frutos rojos y está totalmente arruinada!'::text,'remover'::text,'remover'::text,'remover'::text,'¡No pueden dejar de remover la masa de frutos rojos y está totalmente arruinada!'::text),
(334418,37158,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles n''arrivent pas à arrêter de ... la pâte aux fruits rouges, et elle est complètement fichue !'::text,'remuer'::text,'remuer'::text,'remuer'::text,'Elles n''arrivent pas à arrêter de remuer la pâte aux fruits rouges, et elle est complètement fichue !'::text),
(334421,37158,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Orman meyveli hamuru ... duramıyorlar ve hamur tamamen mahvoldu!'::text,'karıştırmadan'::text,'karıştırmadan'::text,'karıştırmadan'::text,'Orman meyveli hamuru karıştırmadan duramıyorlar ve hamur tamamen mahvoldu!'::text),
(334422,37158,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem tudják abbahagyni a bogyós tészta ..., és teljesen tönkrement!'::text,'kavargatását'::text,'kavargatását'::text,'kavargatását'::text,'Nem tudják abbahagyni a bogyós tészta kavargatását, és teljesen tönkrement!'::text),
(334425,37159,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zu viele Beeren haben den Teig komplett zerstört, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Zu viele Beeren haben den Teig komplett zerstört, oder?'::text),
(334429,37159,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Забагато ягід повністю зіпсували тісто, ...?'::text,'чи не так?'::text,'чи не так?'::text,'чи не так?'::text,'Забагато ягід повністю зіпсували тісто, чи не так?'::text),
(334428,37159,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demasiados frutos rojos han destrozado la masa por completo, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Demasiados frutos rojos han destrozado la masa por completo, ¿verdad?'::text),
(334427,37159,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trop de fruits rouges ont complètement détruit la pâte, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Trop de fruits rouges ont complètement détruit la pâte, non ?'::text),
(334430,37159,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fazla orman meyvesi hamuru tamamen mahvetti, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Fazla orman meyvesi hamuru tamamen mahvetti, değil mi?'::text),
(334431,37159,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A túl sok bogyós gyümölcs teljesen tönkretette a tésztát, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'A túl sok bogyós gyümölcs teljesen tönkretette a tésztát, ugye?'::text),
(334434,37160,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich liebt sie Beeren, und ...'::text,'ihre Freundin auch.'::text,'ihre Freundin auch.'::text,'ihre Freundin auch nicht.'::text,'Mädel, angeblich liebt sie Beeren, und ihre Freundin auch.'::text),
(334438,37160,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона обожнює ягоди, і ...'::text,'її подруга теж.'::text,'її подруга теж.'::text,'її подруга теж ні.'::text,'Подруго, кажуть, вона обожнює ягоди, і її подруга теж.'::text),
(334437,37160,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer a ella le encantan los frutos rojos, y ...'::text,'a su amiga también.'::text,'a su amiga también.'::text,'a su amiga tampoco.'::text,'Tía, al parecer a ella le encantan los frutos rojos, y a su amiga también.'::text),
(334436,37160,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle adore les fruits rouges, et ...'::text,'son amie aussi.'::text,'son amie aussi.'::text,'son amie non plus.'::text,'Meuf, apparemment elle adore les fruits rouges, et son amie aussi.'::text),
(334439,37160,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya o orman meyvelerine bayılıyor, ve ...'::text,'arkadaşı da öyle.'::text,'arkadaşı da öyle.'::text,'arkadaşı da bayılmıyor.'::text,'Kızım, güya o orman meyvelerine bayılıyor, ve arkadaşı da öyle.'::text),
(334440,37160,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag imádja a bogyós gyümölcsöt, és ...'::text,'a barátnője is.'::text,'a barátnője is.'::text,'a barátnője sem.'::text,'Csajszi, állítólag imádja a bogyós gyümölcsöt, és a barátnője is.'::text),
(334443,37161,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat mir gesagt, dass sie bis heute Abend jede Beere in der Küche ...'::text,'verbraucht haben werden'::text,'verbrauchen werden'::text,'verwenden werden'::text,'Bestie, sie hat mir gesagt, dass sie bis heute Abend jede Beere in der Küche verbraucht haben werden.'::text),
(334447,37161,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що до вечора вони ... кожну ягідку на кухні.'::text,'використають'::text,'використають'::text,'використовуватимуть'::text,'Подруго, вона сказала мені, що до вечора вони використають кожну ягідку на кухні.'::text),
(334446,37161,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que para esta noche ... todos los frutos rojos de la cocina.'::text,'habrán usado'::text,'usarán'::text,'estarán usando'::text,'Amiga, me dijo que para esta noche habrán usado todos los frutos rojos de la cocina.'::text),
(334445,37161,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit que d''ici ce soir, elles ... tous les fruits rouges de la cuisine.'::text,'auront utilisé'::text,'utiliseront'::text,'seront en train d''utiliser'::text,'Ma belle, elle m''a dit que d''ici ce soir, elles auront utilisé tous les fruits rouges de la cuisine.'::text),
(334448,37161,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana bu akşama kadar mutfaktaki bütün orman meyvelerini ... söyledi.'::text,'kullanmış olacaklarını'::text,'kullanacaklarını'::text,'kullanıyor olacaklarını'::text,'Kanka, bana bu akşama kadar mutfaktaki bütün orman meyvelerini kullanmış olacaklarını söyledi.'::text),
(334449,37161,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, estére a konyhában minden bogyót ...'::text,'felhasználnak'::text,'fel fognak használni'::text,'használni fognak'::text,'Csajszi, azt mondta, estére a konyhában minden bogyót felhasználnak.'::text),
(334461,37163,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Beerenteig schon fünf Minuten lang gerührt, als er braun wurde.'::text,'hatten'::text,'haben'::text,'rühren'::text,'Sie hatten den Beerenteig schon fünf Minuten lang gerührt, als er braun wurde.'::text),
(334465,37163,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... ягідне тісто вже п''ять хвилин, коли воно побуріло.'::text,'мішали'::text,'мішають'::text,'мішають'::text,'Вони мішали ягідне тісто вже п''ять хвилин, коли воно побуріло.'::text),
(334464,37163,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la masa de frutos rojos desde hacía cinco minutos cuando se puso marrón.'::text,'Habían estado removiendo'::text,'Han estado removiendo'::text,'Remueven'::text,'Habían estado removiendo la masa de frutos rojos desde hacía cinco minutos cuando se puso marrón.'::text),
(334463,37163,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ... la pâte aux fruits rouges depuis cinq minutes quand elle a bruni.'::text,'remuaient'::text,'remuent'::text,'remuent'::text,'Elles remuaient la pâte aux fruits rouges depuis cinq minutes quand elle a bruni.'::text),
(334466,37163,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kahverengiye döndüğünde orman meyveli hamuru beş dakikadır ...'::text,'karıştırıyorlardı'::text,'karıştırıyorlar'::text,'karıştırırlar'::text,'Kahverengiye döndüğünde orman meyveli hamuru beş dakikadır karıştırıyorlardı.'::text),
(334467,37163,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már öt perce ... a bogyós tésztát, amikor megbarnult.'::text,'kavarták'::text,'kavarják'::text,'kavarják'::text,'Már öt perce kavarták a bogyós tésztát, amikor megbarnult.'::text),
(386013,42891,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Meeting endete, ... sie den ganzen Boden schon komplett zum Glänzen gebracht!'::text,'hatte'::text,'hat'::text,'bringt'::text,'Als das Meeting endete, hatte sie den ganzen Boden schon komplett zum Glänzen gebracht!'::text),
(386017,42891,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки нарада закінчилася, вона вже ... всю підлогу абсолютно блискучою!'::text,'зробила'::text,'зробила'::text,'робить'::text,'Поки нарада закінчилася, вона вже зробила всю підлогу абсолютно блискучою!'::text),
(386016,42891,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando terminó la reunión, ya ... todo el suelo completamente reluciente!'::text,'había dejado'::text,'ha dejado'::text,'deja'::text,'¡Para cuando terminó la reunión, ya había dejado todo el suelo completamente reluciente!'::text),
(386015,42891,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que la réunion se termine, elle ... tout le sol complètement brillant !'::text,'avait rendu'::text,'a rendu'::text,'rend'::text,'Le temps que la réunion se termine, elle avait rendu tout le sol complètement brillant !'::text),
(386018,42891,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toplantı bittiğinde bütün zemini çoktan pırıl pırıl ...!'::text,'yapmıştı'::text,'yaptı'::text,'yapıyor'::text,'Toplantı bittiğinde bütün zemini çoktan pırıl pırıl yapmıştı!'::text),
(386019,42891,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a megbeszélés véget ért, az egész padlót teljesen fényesre ...!'::text,'sikálta'::text,'sikálta'::text,'sikálja'::text,'Mire a megbeszélés véget ért, az egész padlót teljesen fényesre sikálta!'::text),
(386022,42892,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die ganze Halle wischt, ... der Boden bis zum Abend.'::text,'glänzt'::text,'würde glänzen'::text,'glänzte'::text,'Wenn sie die ganze Halle wischt, glänzt der Boden bis zum Abend.'::text),
(386026,42892,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона вимиє весь хол, підлога ... блискучою до вечора.'::text,'буде'::text,'була б'::text,'була'::text,'Якщо вона вимиє весь хол, підлога буде блискучою до вечора.'::text),
(386025,42892,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si friega todo el vestíbulo, el suelo ... reluciente por la tarde.'::text,'estará'::text,'estaría'::text,'estaba'::text,'Si friega todo el vestíbulo, el suelo estará reluciente por la tarde.'::text),
(386024,42892,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle passe la serpillière dans tout le hall, le sol ... brillant d''ici ce soir.'::text,'sera'::text,'serait'::text,'était'::text,'Si elle passe la serpillière dans tout le hall, le sol sera brillant d''ici ce soir.'::text),
(386027,42892,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün salonu paspaslarsa, zemin akşama kadar parlak ...'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Bütün salonu paspaslarsa, zemin akşama kadar parlak olacak.'::text),
(386028,42892,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha felmossa az egész csarnokot, estére fényes ... a padló.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha felmossa az egész csarnokot, estére fényes lesz a padló.'::text),
(386031,42893,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Boden nicht so glänzend wäre, ... sich die Lichter nicht darin spiegeln.'::text,'würden'::text,'werden'::text,'spiegelten'::text,'Wenn der Boden nicht so glänzend wäre, würden sich die Lichter nicht darin spiegeln.'::text),
(386035,42893,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби підлога не була такою блискучою, світло ... в ній.'::text,'не відбивалося б'::text,'не відбиватиметься'::text,'не відбивалося'::text,'Якби підлога не була такою блискучою, світло не відбивалося б в ній.'::text),
(386034,42893,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el suelo no fuera tan brillante, las luces no ... en él.'::text,'se reflejarían'::text,'se reflejarán'::text,'se reflejaron'::text,'Si el suelo no fuera tan brillante, las luces no se reflejarían en él.'::text),
(386033,42893,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le sol n''était pas si brillant, les lumières ne ... pas dedans.'::text,'se refléteraient'::text,'se refléteront'::text,'se reflétaient'::text,'Si le sol n''était pas si brillant, les lumières ne se refléteraient pas dedans.'::text),
(386036,42893,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zemin bu kadar parlak olmasaydı, ışıklar içinde ...'::text,'yansımazdı'::text,'yansımayacak'::text,'yansımadı'::text,'Zemin bu kadar parlak olmasaydı, ışıklar içinde yansımazdı.'::text),
(386037,42893,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a padló nem lenne ilyen fényes, a lámpák nem ... benne.'::text,'tükröződnének'::text,'fognak tükröződni'::text,'tükröződtek'::text,'Ha a padló nem lenne ilyen fényes, a lámpák nem tükröződnének benne.'::text),
(386040,42894,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kein Witz, es heißt, der Boden ... gewischt, bis er glänzte, und im Meeting hat es keiner gemerkt.'::text,'wurde'::text,'wischte'::text,'wird'::text,'Kein Witz, es heißt, der Boden wurde gewischt, bis er glänzte, und im Meeting hat es keiner gemerkt.'::text),
(386044,42894,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, кажуть, підлогу ... до блиску, а на нараді ніхто й не помітив.'::text,'мили'::text,'мила'::text,'миють'::text,'Та ну, кажуть, підлогу мили до блиску, а на нараді ніхто й не помітив.'::text),
(386043,42894,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué fuerte, dicen que el suelo ... hasta que quedó reluciente, y en la reunión nadie se dio cuenta.'::text,'fue fregado'::text,'fregó'::text,'es fregado'::text,'Qué fuerte, dicen que el suelo fue fregado hasta que quedó reluciente, y en la reunión nadie se dio cuenta.'::text),
(386042,42894,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sérieux, il paraît que le sol ... jusqu''à ce qu''il brille, et la réunion n''a rien remarqué.'::text,'a été lavé'::text,'a lavé'::text,'est lavé'::text,'Sérieux, il paraît que le sol a été lavé jusqu''à ce qu''il brille, et la réunion n''a rien remarqué.'::text),
(386045,42894,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok artık, dediklerine göre zemin parlayana kadar ... ve toplantıdakiler hiç fark etmedi.'::text,'paspaslandı'::text,'paspasladı'::text,'paspaslanır'::text,'Yok artık, dediklerine göre zemin parlayana kadar paspaslandı ve toplantıdakiler hiç fark etmedi.'::text),
(386046,42894,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hiszem el, azt mondják, a padlót addig ..., amíg fényes nem lett, és a megbeszélésen senki sem vette észre.'::text,'mosták fel'::text,'felmosta'::text,'felmossák'::text,'Nem hiszem el, azt mondják, a padlót addig mosták fel, amíg fényes nem lett, és a megbeszélésen senki sem vette észre.'::text),
(386049,42895,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Reinigungskraft ... den Steinboden, bis er glänzte.'::text,'wischte'::text,'wurde gewischt'::text,'wischend'::text,'Die Reinigungskraft wischte den Steinboden, bis er glänzte.'::text),
(386053,42895,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прибиральниця ... кам''яну підлогу, доки вона не заблищала.'::text,'мила'::text,'була вимита'::text,'миття'::text,'Прибиральниця мила кам''яну підлогу, доки вона не заблищала.'::text),
(386052,42895,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La limpiadora ... el suelo de piedra hasta que quedó reluciente.'::text,'fregó'::text,'fue fregada'::text,'fregando'::text,'La limpiadora fregó el suelo de piedra hasta que quedó reluciente.'::text),
(386051,42895,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme de ménage ... le sol en pierre jusqu''à ce qu''il brille.'::text,'a lavé'::text,'a été lavée'::text,'lavant'::text,'La femme de ménage a lavé le sol en pierre jusqu''à ce qu''il brille.'::text),
(386054,42895,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Temizlikçi taş zemini parlayana kadar ...'::text,'paspasladı'::text,'paspaslandı'::text,'paspaslayan'::text,'Temizlikçi taş zemini parlayana kadar paspasladı.'::text),
(386055,42895,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A takarítónő addig ... a kőpadlót, amíg fényes nem lett.'::text,'mosta fel'::text,'fel lett mosva'::text,'felmosva'::text,'A takarítónő addig mosta fel a kőpadlót, amíg fényes nem lett.'::text),
(386058,42896,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ein so glänzender Boden ... deine Arbeit sein. Respekt.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Ehrlich, ein so glänzender Boden muss deine Arbeit sein. Respekt.'::text),
(386062,42896,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, така блискуча підлога ... бути твоєю роботою. Респект.'::text,'мусить'::text,'не може'::text,'не повинна'::text,'Чесно, така блискуча підлога мусить бути твоєю роботою. Респект.'::text),
(386061,42896,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, un suelo tan reluciente ... ser obra tuya. Respeto.'::text,'tiene que'::text,'no puede'::text,'no debe'::text,'La verdad, un suelo tan reluciente tiene que ser obra tuya. Respeto.'::text),
(386060,42896,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, un sol aussi brillant, ça ... être ton œuvre. Respect.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Franchement, un sol aussi brillant, ça doit être ton œuvre. Respect.'::text),
(386063,42896,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bu kadar parlak bir zemin senin işin ...! Saygılar.'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Açıkçası, bu kadar parlak bir zemin senin işin olmalı! Saygılar.'::text),
(386064,42896,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, egy ilyen fényes padló ... a te munkád. Respekt.'::text,'biztosan'::text,'nem lehet'::text,'nem szabad, hogy'::text,'Őszintén, egy ilyen fényes padló biztosan a te munkád. Respekt.'::text),
(386067,42897,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Leute, ... im Meeting sitzen, bewundern natürlich den glänzenden Boden.'::text,'die'::text,'welches'::text,'deren'::text,'Die Leute, die im Meeting sitzen, bewundern natürlich den glänzenden Boden.'::text),
(386071,42897,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Люди, ... сидять на нараді, звісно ж, захоплюються блискучою підлогою.'::text,'які'::text,'що'::text,'чиї'::text,'Люди, які сидять на нараді, звісно ж, захоплюються блискучою підлогою.'::text),
(386070,42897,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las personas ... están sentadas en la reunión obviamente admiran el suelo reluciente.'::text,'que'::text,'las cuales'::text,'cuyas'::text,'Las personas que están sentadas en la reunión obviamente admiran el suelo reluciente.'::text),
(386069,42897,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les gens ... sont assis en réunion admirent évidemment le sol brillant.'::text,'qui'::text,'lesquels'::text,'dont'::text,'Les gens qui sont assis en réunion admirent évidemment le sol brillant.'::text),
(386072,42897,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toplantıda ... oturan insanlar tabii ki parlak zemine hayran.'::text,''::text,NULL::text,NULL::text,'Toplantıda oturan insanlar tabii ki parlak zemine hayran.'::text),
(386073,42897,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az emberek, ... a megbeszélésen ülnek, nyilván a fényes padlót csodálják.'::text,'akik'::text,'amelyek'::text,'akiknek a'::text,'Az emberek, akik a megbeszélésen ülnek, nyilván a fényes padlót csodálják.'::text),
(386076,42898,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, der Boden ... in zehn Minuten glänzen.'::text,'würde'::text,'wird'::text,'ist'::text,'Sie sagte, der Boden würde in zehn Minuten glänzen.'::text),
(386080,42898,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що підлога ... блискучою за десять хвилин.'::text,'буде'::text,'буде'::text,'є'::text,'Вона сказала, що підлога буде блискучою за десять хвилин.'::text),
(386079,42898,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que el suelo ... reluciente en diez minutos.'::text,'estaría'::text,'estará'::text,'está'::text,'Dijo que el suelo estaría reluciente en diez minutos.'::text),
(386078,42898,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit que le sol ... brillant dans dix minutes.'::text,'serait'::text,'sera'::text,'est'::text,'Elle a dit que le sol serait brillant dans dix minutes.'::text),
(386081,42898,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zeminin on dakika içinde parlak ... söyledi.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Zeminin on dakika içinde parlak olacağını söyledi.'::text),
(386082,42898,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a padló tíz perc múlva fényes ...'::text,'lesz'::text,'lesz'::text,NULL::text,'Azt mondta, hogy a padló tíz perc múlva fényes lesz.'::text),
(386094,42900,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Boden immer weiter, bis jeder Streifen glänzt.'::text,'wischt'::text,'wischt'::text,'wischt'::text,'Sie wischt den Boden immer weiter, bis jeder Streifen glänzt.'::text),
(386098,42900,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона все ... підлогу, доки кожна смуга не заблищить.'::text,'миє'::text,'миє'::text,'миє'::text,'Вона все миє підлогу, доки кожна смуга не заблищить.'::text),
(386097,42900,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sigue ... el suelo hasta que cada franja queda reluciente.'::text,'fregando'::text,'fregar'::text,'friega'::text,'Sigue fregando el suelo hasta que cada franja queda reluciente.'::text),
(386096,42900,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle continue de ... le sol jusqu''à ce que chaque bande brille.'::text,'laver'::text,'laver'::text,'lave'::text,'Elle continue de laver le sol jusqu''à ce que chaque bande brille.'::text),
(386099,42900,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her şerit parlayana kadar zemini ... devam ediyor.'::text,'paspaslamaya'::text,'paspaslamaya'::text,'paspaslar'::text,'Her şerit parlayana kadar zemini paspaslamaya devam ediyor.'::text),
(386100,42900,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Addig ... a padlót, amíg minden sáv fényes nem lesz.'::text,'mossa fel'::text,'mossa fel'::text,'mossa fel'::text,'Addig mossa fel a padlót, amíg minden sáv fényes nem lesz.'::text),
(371739,41305,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den verwilderten Garten jetzt schon seit zwei Stunden.'::text,'mäht'::text,'mäht'::text,'mäht'::text,'Er mäht den verwilderten Garten jetzt schon seit zwei Stunden.'::text),
(371743,41305,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... зарослий сад уже дві години.'::text,'косить'::text,'косить'::text,'косить'::text,'Він косить зарослий сад уже дві години.'::text),
(371742,41305,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el césped del jardín invadido por la maleza desde hace dos horas.'::text,'Ha estado cortando'::text,'Está cortando'::text,'Corta'::text,'Ha estado cortando el césped del jardín invadido por la maleza desde hace dos horas.'::text),
(371741,41305,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça fait maintenant deux heures qu''il ... le jardin envahi par la végétation.'::text,'tond'::text,'tond'::text,'tond'::text,'Ça fait maintenant deux heures qu''il tond le jardin envahi par la végétation.'::text),
(371744,41305,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki saattir otları büyümüş bahçeyi ...'::text,'biçiyor'::text,'biçiyor'::text,'biçer'::text,'İki saattir otları büyümüş bahçeyi biçiyor.'::text),
(371745,41305,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már két órája ... a benőtt kertet.'::text,'kaszálja'::text,'kaszálja'::text,'kaszálja'::text,'Már két órája kaszálja a benőtt kertet.'::text),
(371748,41306,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den ersten Streifen, drehte dann um und mähte einen zweiten durch das verwilderte Gras.'::text,'mähte'::text,'mähte gerade'::text,'hat gemäht'::text,'Er mähte den ersten Streifen, drehte dann um und mähte einen zweiten durch das verwilderte Gras.'::text),
(371752,41306,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... першу смугу, потім розвернувся і скосив другу крізь зарослу траву.'::text,'скосив'::text,'косив'::text,'скосив'::text,'Він скосив першу смугу, потім розвернувся і скосив другу крізь зарослу траву.'::text),
(371751,41306,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la primera franja, luego se giró y cortó una segunda a través de la hierba crecida.'::text,'Cortó'::text,'Estaba cortando'::text,'Ha cortado'::text,'Cortó la primera franja, luego se giró y cortó una segunda a través de la hierba crecida.'::text),
(371750,41306,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la première bande, puis s''est retourné et en a tondu une deuxième dans l''herbe envahissante.'::text,'a tondu'::text,'tondait'::text,'a tondu'::text,'Il a tondu la première bande, puis s''est retourné et en a tondu une deuxième dans l''herbe envahissante.'::text),
(371753,41306,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İlk şeridi ..., sonra döndü ve uzamış otların arasından ikinci bir şerit biçti.'::text,'biçti'::text,'biçiyordu'::text,'biçmiş'::text,'İlk şeridi biçti, sonra döndü ve uzamış otların arasından ikinci bir şerit biçti.'::text),
(371754,41306,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... az első sávot, aztán megfordult, és a benőtt fűben lenyírt egy másodikat is.'::text,'Lenyírta'::text,'Nyírta'::text,'Lenyírta'::text,'Lenyírta az első sávot, aztán megfordult, és a benőtt fűben lenyírt egy másodikat is.'::text),
(371757,41307,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, dass er von dem verwilderten Rasen bis jetzt erst zwei Streifen ...'::text,'gemäht hat'::text,'mäht'::text,'mäht'::text,'Hör zu, er hat mir erzählt, dass er von dem verwilderten Rasen bis jetzt erst zwei Streifen gemäht hat.'::text),
(371761,41307,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він мені сказав, що поки ... лише дві смуги того зарослого газону.'::text,'скосив'::text,'косив'::text,'косить'::text,'Слухай, він мені сказав, що поки скосив лише дві смуги того зарослого газону.'::text),
(371760,41307,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que hasta ahora solo ... dos franjas de ese césped descuidado.'::text,'ha cortado'::text,'ha estado cortando'::text,'corta'::text,'Escucha, me dijo que hasta ahora solo ha cortado dos franjas de ese césped descuidado.'::text),
(371759,41307,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que jusqu''ici il ... seulement deux bandes de cette pelouse envahie.'::text,'a tondu'::text,'tond depuis'::text,'tond'::text,'Écoute, il m''a dit que jusqu''ici il a tondu seulement deux bandes de cette pelouse envahie.'::text),
(371762,41307,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana o uzamış çimin şimdiye kadar sadece iki şeridini ... söyledi.'::text,'biçtiğini'::text,'biçmekte olduğunu'::text,'biçtiğini'::text,'Dinle, bana o uzamış çimin şimdiye kadar sadece iki şeridini biçtiğini söyledi.'::text),
(371763,41307,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy eddig csak két sávot ... le abból a benőtt gyepből.'::text,'nyírt'::text,'nyírt'::text,'nyír'::text,'Figyelj, azt mondta, hogy eddig csak két sávot nyírt le abból a benőtt gyepből.'::text),
(371766,41308,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, angeblich ... der Garten schon komplett verwildert, als er nach Hause kam.'::text,'war'::text,'ist'::text,'wird'::text,'Okay, angeblich war der Garten schon komplett verwildert, als er nach Hause kam.'::text),
(371770,41308,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, поки він повернувся додому, сад уже ... геть зарослим.'::text,'став'::text,'став'::text,'стає'::text,'Отже, кажуть, поки він повернувся додому, сад уже став геть зарослим.'::text),
(371769,41308,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer, para cuando llegó a casa, el jardín ya ... completamente invadido por la maleza.'::text,'había quedado'::text,'ha quedado'::text,'queda'::text,'Vale, al parecer, para cuando llegó a casa, el jardín ya había quedado completamente invadido por la maleza.'::text),
(371768,41308,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment, quand il est rentré, le jardin ... complètement envahi par la végétation.'::text,'était devenu'::text,'est devenu'::text,'devient'::text,'Bon, apparemment, quand il est rentré, le jardin était devenu complètement envahi par la végétation.'::text),
(371771,41308,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre o eve döndüğünde bahçeyi tamamen ot ...'::text,'bürümüştü'::text,'bürüdü'::text,'bürüyor'::text,'Tamam, duyduğuma göre o eve döndüğünde bahçeyi tamamen ot bürümüştü.'::text),
(371772,41308,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag mire hazaért, a kert már teljesen ...'::text,'elvadult'::text,'elvadult'::text,'elvadul'::text,'Szóval állítólag mire hazaért, a kert már teljesen elvadult.'::text),
(371775,41309,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, morgen um diese Zeit ... er schon wieder dieses verwilderte Chaos, ohne Witz.'::text,'mäht'::text,'mäht'::text,'mäht'::text,'Alter, morgen um diese Zeit mäht er schon wieder dieses verwilderte Chaos, ohne Witz.'::text),
(371779,41309,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, завтра в цей час він знову ... той зарослий безлад, без жартів.'::text,'коситиме'::text,'скосить'::text,'косить'::text,'Чувак, завтра в цей час він знову коситиме той зарослий безлад, без жартів.'::text),
(371778,41309,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, mañana a esta hora ... otra vez ese desastre de maleza, en serio.'::text,'estará cortando'::text,'cortará'::text,'corta'::text,'Tío, mañana a esta hora estará cortando otra vez ese desastre de maleza, en serio.'::text),
(371777,41309,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, demain à cette heure-ci, il ... encore ce bazar envahi d''herbe, sans mentir.'::text,'sera en train de tondre'::text,'tondra'::text,'tond'::text,'Mec, demain à cette heure-ci, il sera en train de tondre encore ce bazar envahi d''herbe, sans mentir.'::text),
(371780,41309,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatte yine o otları uzamış karmaşayı ..., cidden.'::text,'biçiyor olacak'::text,'biçecek'::text,'biçer'::text,'Kanka, yarın bu saatte yine o otları uzamış karmaşayı biçiyor olacak, cidden.'::text),
(371781,41309,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnap ilyenkor megint azt a benőtt káoszt ..., komolyan.'::text,'fogja nyírni'::text,'lenyírja'::text,'nyírja'::text,'Tesó, holnap ilyenkor megint azt a benőtt káoszt fogja nyírni, komolyan.'::text),
(371784,41310,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, ich hab keinen Bock mehr auf dieses verwilderte Gras, ich ... es jetzt sofort selbst.'::text,'mähe'::text,'werde mähen'::text,'mähe'::text,'Nee Bro, ich hab keinen Bock mehr auf dieses verwilderte Gras, ich mähe es jetzt sofort selbst.'::text),
(371788,41310,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, мене дістала ця заросла трава, я ... її сам просто зараз.'::text,'скошу'::text,'коситиму'::text,'кошу'::text,'Не, бро, мене дістала ця заросла трава, я скошу її сам просто зараз.'::text),
(371787,41310,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, bro, estoy harto de esta hierba crecida, la ... yo mismo ahora mismo.'::text,'cortaré'::text,'estaré cortando'::text,'corto'::text,'Qué va, bro, estoy harto de esta hierba crecida, la cortaré yo mismo ahora mismo.'::text),
(371786,41310,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frérot, j''en ai marre de cette herbe envahissante, je la ... moi-même tout de suite.'::text,'vais couper'::text,'serai en train de couper'::text,'coupe'::text,'Non frérot, j''en ai marre de cette herbe envahissante, je la vais couper moi-même tout de suite.'::text),
(371789,41310,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bu uzamış otlardan bıktım, şimdi kendim ...'::text,'biçeceğim'::text,'biçiyor olacağım'::text,'biçerim'::text,'Yok kanka, bu uzamış otlardan bıktım, şimdi kendim biçeceğim.'::text),
(371790,41310,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, elegem van ebből a benőtt fűből, most rögtön én magam ... le.'::text,'nyírom'::text,'fogom nyírni'::text,'nyírom'::text,'Á, tesó, elegem van ebből a benőtt fűből, most rögtön én magam nyírom le.'::text),
(371793,41311,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Gras 30 Tage lang ungemäht ..., verwildert der Garten, so der Bericht.'::text,'bleibt'::text,'blieb'::text,'bleiben wird'::text,'Wenn Gras 30 Tage lang ungemäht bleibt, verwildert der Garten, so der Bericht.'::text),
(371797,41311,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо трава ... нескошеною 30 днів, сад заростає, йдеться у звіті.'::text,'залишається'::text,'залишилася'::text,'залишиться'::text,'Якщо трава залишається нескошеною 30 днів, сад заростає, йдеться у звіті.'::text),
(371796,41311,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el césped ... sin cortar durante 30 días, el jardín se llena de maleza, según el informe.'::text,'se queda'::text,'se quedó'::text,'se quedará'::text,'Si el césped se queda sin cortar durante 30 días, el jardín se llena de maleza, según el informe.'::text),
(371795,41311,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''herbe ... non tondue pendant 30 jours, le jardin est envahi par la végétation, selon le rapport.'::text,'reste'::text,'restait'::text,'restera'::text,'Si l''herbe reste non tondue pendant 30 jours, le jardin est envahi par la végétation, selon le rapport.'::text),
(371798,41311,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapora göre, çimler 30 gün biçilmeden ..., bahçeyi ot bürür.'::text,'kalırsa'::text,'kaldıysa'::text,'kalacaksa'::text,'Rapora göre, çimler 30 gün biçilmeden kalırsa, bahçeyi ot bürür.'::text),
(371799,41311,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a fű 30 napig nyíratlanul ..., a kert elvadul, áll a jelentésben.'::text,'marad'::text,'maradt'::text,'marad majd'::text,'Ha a fű 30 napig nyíratlanul marad, a kert elvadul, áll a jelentésben.'::text),
(371802,41312,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er das verwilderte Gras nicht mäht, ... es lang, weil es lang ist.'::text,'bleibt'::text,'bliebe'::text,'blieb'::text,'Wenn er das verwilderte Gras nicht mäht, bleibt es lang, weil es lang ist.'::text),
(371806,41312,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він не скосить зарослу траву, вона ... довгою, бо вона довга.'::text,'залишиться'::text,'залишилася б'::text,'залишилася'::text,'Якщо він не скосить зарослу траву, вона залишиться довгою, бо вона довга.'::text),
(371805,41312,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no corta la hierba crecida, ... larga, porque es larga.'::text,'seguirá'::text,'seguiría'::text,'siguió'::text,'Si no corta la hierba crecida, seguirá larga, porque es larga.'::text),
(371804,41312,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ne tond pas l''herbe envahissante, elle ... longue, parce qu''elle est longue.'::text,'restera'::text,'resterait'::text,'restait'::text,'S''il ne tond pas l''herbe envahissante, elle restera longue, parce qu''elle est longue.'::text),
(371807,41312,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uzamış otları biçmezse, otlar uzun ..., çünkü uzun.'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Uzamış otları biçmezse, otlar uzun kalacak, çünkü uzun.'::text),
(371808,41312,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem nyírja le a benőtt füvet, hosszú ..., mert hosszú.'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha nem nyírja le a benőtt füvet, hosszú marad, mert hosszú.'::text),
(371811,41313,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Rasen ... seit mehreren Wochen verwildert, was typischerweise auf Vernachlässigung hindeutet.'::text,'ist'::text,'ist'::text,'wurde'::text,'Der Rasen ist seit mehreren Wochen verwildert, was typischerweise auf Vernachlässigung hindeutet.'::text),
(371815,41313,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Газон ... зарослим уже кілька тижнів, що зазвичай свідчить про занедбаність.'::text,'залишається'::text,'залишається'::text,'залишався'::text,'Газон залишається зарослим уже кілька тижнів, що зазвичай свідчить про занедбаність.'::text),
(371814,41313,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El césped ... descuidado desde hace varias semanas, lo que suele indicar abandono.'::text,'está'::text,'está'::text,'estaba siendo'::text,'El césped está descuidado desde hace varias semanas, lo que suele indicar abandono.'::text),
(371813,41313,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pelouse ... envahie depuis plusieurs semaines, ce qui indique généralement un manque d''entretien.'::text,'est'::text,'est'::text,'était en train d''être'::text,'La pelouse est envahie depuis plusieurs semaines, ce qui indique généralement un manque d''entretien.'::text),
(371816,41313,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çimi birkaç haftadır ot ..., bu da genellikle ihmale işaret eder.'::text,'bürümüş durumda'::text,'bürüyor'::text,'bürüyordu'::text,'Çimi birkaç haftadır ot bürümüş durumda, bu da genellikle ihmale işaret eder.'::text),
(371817,41313,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyep hetek óta ... benőtt, ami jellemzően elhanyagoltságra utal.'::text,''::text,NULL::text,'volt'::text,'A gyep hetek óta benőtt, ami jellemzően elhanyagoltságra utal.'::text),
(387471,43053,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächsten Monat um diese Zeit ... der dünne junge Mann jeden Tag im Gym.'::text,'trainiert'::text,'wird trainieren'::text,'trainiert'::text,'Nächsten Monat um diese Zeit trainiert der dünne junge Mann jeden Tag im Gym.'::text),
(387475,43053,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного місяця в цей час худий хлопець ... в залі щодня.'::text,'тренуватиметься'::text,'потренується'::text,'тренується'::text,'Наступного місяця в цей час худий хлопець тренуватиметься в залі щодня.'::text),
(387474,43053,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mes que viene a estas alturas, el chico flaco ... en el gimnasio todos los días.'::text,'estará entrenando'::text,'entrenará'::text,'entrena'::text,'El mes que viene a estas alturas, el chico flaco estará entrenando en el gimnasio todos los días.'::text),
(387473,43053,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mois prochain à la même époque, le jeune homme maigre ... à la salle tous les jours.'::text,'s''entraînera'::text,'s''entraînera'::text,'s''entraîne'::text,'Le mois prochain à la même époque, le jeune homme maigre s''entraînera à la salle tous les jours.'::text),
(387476,43053,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek ay bu zamanlar sıska genç her gün spor salonunda ...'::text,'antrenman yapıyor olacak'::text,'antrenman yapacak'::text,'antrenman yapıyor'::text,'Gelecek ay bu zamanlar sıska genç her gün spor salonunda antrenman yapıyor olacak.'::text),
(387477,43053,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő hónapban ilyenkor a sovány srác már minden nap ... az edzőteremben.'::text,'edzeni fog'::text,'edz majd'::text,'edz'::text,'Jövő hónapban ilyenkor a sovány srác már minden nap edzeni fog az edzőteremben.'::text),
(387480,43054,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der dünne Mann verspricht, dass er härter als der Bodybuilder ...'::text,'trainieren wird'::text,'trainieren wird'::text,'trainiert'::text,'Der dünne Mann verspricht, dass er härter als der Bodybuilder trainieren wird.'::text),
(387484,43054,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Худий чоловік обіцяє, що ... наполегливіше за бодібілдера.'::text,'тренуватиметься'::text,'тренуватиметься'::text,'тренується'::text,'Худий чоловік обіцяє, що тренуватиметься наполегливіше за бодібілдера.'::text),
(387483,43054,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre flaco promete que ... más duro que el culturista.'::text,'entrenará'::text,'estará entrenando'::text,'está entrenando'::text,'El hombre flaco promete que entrenará más duro que el culturista.'::text),
(387482,43054,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme maigre promet qu''il ... plus dur que le culturiste.'::text,'s''entraînera'::text,'sera en train de s''entraîner'::text,'s''entraîne'::text,'L''homme maigre promet qu''il s''entraînera plus dur que le culturiste.'::text),
(387485,43054,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıska adam vücut geliştiriciden daha sıkı ... söz veriyor.'::text,'çalışacağına'::text,'çalışıyor olacağına'::text,'çalıştığına'::text,'Sıska adam vücut geliştiriciden daha sıkı çalışacağına söz veriyor.'::text),
(387486,43054,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sovány férfi megígéri, hogy keményebben ..., mint a testépítő.'::text,'fog edzeni'::text,'fog edzeni'::text,'edz'::text,'A sovány férfi megígéri, hogy keményebben fog edzeni, mint a testépítő.'::text),
(387489,43055,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, wenn du nur fest genug das Gesicht verziehst, ... ein dünner Arm größer.'::text,'wird'::text,'wurde'::text,'wird'::text,'Klar, wenn du nur fest genug das Gesicht verziehst, wird ein dünner Arm größer.'::text),
(387493,43055,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, якщо просто досить сильно скривитися, худа рука ... більшою.'::text,'стає'::text,'стала'::text,'стане'::text,'Звісно, якщо просто досить сильно скривитися, худа рука стає більшою.'::text),
(387492,43055,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, si solo haces una mueca lo bastante fuerte, un brazo flaco se ... más grande.'::text,'hace'::text,'hizo'::text,'hará'::text,'Obviamente, si solo haces una mueca lo bastante fuerte, un brazo flaco se hace más grande.'::text),
(387491,43055,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, si tu grimaces assez fort, un bras maigre ... plus gros.'::text,'devient'::text,'devenait'::text,'deviendra'::text,'Évidemment, si tu grimaces assez fort, un bras maigre devient plus gros.'::text),
(387494,43055,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki, yeterince sert surat yaparsan sıska bir kol ...'::text,'büyür'::text,'büyüdü'::text,'büyüyecek'::text,'Tabii ki, yeterince sert surat yaparsan sıska bir kol büyür.'::text),
(387495,43055,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván, ha elég erősen grimaszolsz, egy sovány kar ...'::text,'megnő'::text,'megnőtt'::text,'meg fog nőni'::text,'Nyilván, ha elég erősen grimaszolsz, egy sovány kar megnő.'::text),
(387507,43057,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, der dünne Typ kann noch keine Doppelbizeps-Pose, und ...'::text,'ich auch nicht, echt.'::text,'ich auch, echt.'::text,'ich auch nicht, echt.'::text,'Nee, der dünne Typ kann noch keine Doppelbizeps-Pose, und ich auch nicht, echt.'::text),
(387511,43057,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, той худий хлопець ще не вміє робити позу з подвійним біцепсом, і ...'::text,'я теж ні, реально.'::text,'я теж, реально.'::text,'я теж ні, реально.'::text,'Не, той худий хлопець ще не вміє робити позу з подвійним біцепсом, і я теж ні, реально.'::text),
(387510,43057,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, el flaco todavía no sabe hacer la pose de doble bíceps, y ...'::text,'yo tampoco, en serio.'::text,'yo también, en serio.'::text,'yo tampoco, en serio.'::text,'Qué va, el flaco todavía no sabe hacer la pose de doble bíceps, y yo tampoco, en serio.'::text),
(387509,43057,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, le maigrichon ne sait pas encore faire la pose double biceps, et ...'::text,'moi non plus, grave.'::text,'moi aussi, grave.'::text,'moi non plus, grave.'::text,'Nan, le maigrichon ne sait pas encore faire la pose double biceps, et moi non plus, grave.'::text),
(387512,43057,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, sıska çocuk henüz çift pazu pozu veremiyor, ...'::text,'ben de veremiyorum, cidden.'::text,'ben de verebiliyorum, cidden.'::text,'ben de vermiyorum, cidden.'::text,'Yok, sıska çocuk henüz çift pazu pozu veremiyor, ben de veremiyorum, cidden.'::text),
(387513,43057,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, a sovány srác még nem tud dupla bicepszpózt csinálni, és ...'::text,'én sem, komolyan.'::text,'én is, komolyan.'::text,'én sem, komolyan.'::text,'Á, a sovány srác még nem tud dupla bicepszpózt csinálni, és én sem, komolyan.'::text),
(387516,43058,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Programms wird der dünne Kunde 5 Kilo Muskeln ...'::text,'zugelegt haben'::text,'zulegen'::text,'zugelegt'::text,'Bis zum Ende des Programms wird der dünne Kunde 5 Kilo Muskeln zugelegt haben.'::text),
(387520,43058,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця програми худий клієнт ... 5 кілограмів м''язів.'::text,'вже набере'::text,'набере'::text,'набрав'::text,'До кінця програми худий клієнт вже набере 5 кілограмів м''язів.'::text),
(387519,43058,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al final del programa, el cliente flaco ... 5 kilos de músculo.'::text,'habrá ganado'::text,'ganará'::text,'ha ganado'::text,'Al final del programa, el cliente flaco habrá ganado 5 kilos de músculo.'::text),
(387518,43058,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du programme, le client maigre ... 5 kilos de muscle.'::text,'aura pris'::text,'prendra'::text,'a pris'::text,'D''ici la fin du programme, le client maigre aura pris 5 kilos de muscle.'::text),
(387521,43058,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Programın sonuna kadar sıska müşteri 5 kilo kas ...'::text,'kazanmış olacak'::text,'kazanacak'::text,'kazandı'::text,'Programın sonuna kadar sıska müşteri 5 kilo kas kazanmış olacak.'::text),
(387522,43058,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A program végére a sovány ügyfél már ... 5 kiló izmot.'::text,'felszed'::text,'fel fog szedni'::text,'felszedett'::text,'A program végére a sovány ügyfél már felszed 5 kiló izmot.'::text),
(387525,43059,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte der dünne Mann letztes Jahr schwerere Gewichte gehoben, ... er mehr Muskeln aufgebaut.'::text,'hätte'::text,'wird'::text,'baute'::text,'Hätte der dünne Mann letztes Jahr schwerere Gewichte gehoben, hätte er mehr Muskeln aufgebaut.'::text),
(387529,43059,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби худий чоловік торік піднімав важчі ваги, він ... більше м''язів.'::text,'наростив би'::text,'наростить'::text,'наростив'::text,'Якби худий чоловік торік піднімав важчі ваги, він наростив би більше м''язів.'::text),
(387528,43059,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el hombre flaco hubiera levantado pesas más pesadas el año pasado, ... más músculo.'::text,'habría ganado'::text,'ganará'::text,'ganó'::text,'Si el hombre flaco hubiera levantado pesas más pesadas el año pasado, habría ganado más músculo.'::text),
(387527,43059,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''homme maigre avait soulevé des poids plus lourds l''an dernier, il ... plus de muscle.'::text,'aurait pris'::text,'prendra'::text,'a pris'::text,'Si l''homme maigre avait soulevé des poids plus lourds l''an dernier, il aurait pris plus de muscle.'::text),
(387530,43059,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıska adam geçen yıl daha ağır ağırlıklar kaldırsaydı, daha fazla kas ...'::text,'yapardı'::text,'yapacak'::text,'yaptı'::text,'Sıska adam geçen yıl daha ağır ağırlıklar kaldırsaydı, daha fazla kas yapardı.'::text),
(387531,43059,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sovány férfi tavaly nehezebb súlyokat emelt volna, több izmot ...'::text,'épített volna'::text,'fog építeni'::text,'épített'::text,'Ha a sovány férfi tavaly nehezebb súlyokat emelt volna, több izmot épített volna.'::text),
(387534,43060,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswerterweise bestand die dünne Versuchsperson darauf, die Pose trotz der erforderlichen Anstrengung zu ...'::text,'halten'::text,'halten'::text,'halten'::text,'Bemerkenswerterweise bestand die dünne Versuchsperson darauf, die Pose trotz der erforderlichen Anstrengung zu halten.'::text),
(387538,43060,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Примітно, що худий суб''єкт наполягав на тому, щоб ... позу попри зусилля, яких вона вимагала.'::text,'утримувати'::text,'утримувати'::text,'утримувати'::text,'Примітно, що худий суб''єкт наполягав на тому, щоб утримувати позу попри зусилля, яких вона вимагала.'::text),
(387537,43060,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cabe destacar que el sujeto flaco insistió en ... la pose pese al esfuerzo que requería.'::text,'mantener'::text,'mantener'::text,'mantener'::text,'Cabe destacar que el sujeto flaco insistió en mantener la pose pese al esfuerzo que requería.'::text),
(387536,43060,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait notable, le sujet maigre a tenu à ... la pose malgré l''effort qu''elle exigeait.'::text,'garder'::text,'garder'::text,'garder'::text,'Fait notable, le sujet maigre a tenu à garder la pose malgré l''effort qu''elle exigeait.'::text),
(387539,43060,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat çekici biçimde sıska denek, gerektirdiği çabaya rağmen pozu ... ısrar etti.'::text,'korumakta'::text,'korumakta'::text,'korumakta'::text,'Dikkat çekici biçimde sıska denek, gerektirdiği çabaya rağmen pozu korumakta ısrar etti.'::text),
(387540,43060,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó, hogy a sovány alany ragaszkodott a póz ..., a szükséges erőfeszítés ellenére.'::text,'megtartásához'::text,'megtartásához'::text,'megtartásához'::text,'Figyelemre méltó, hogy a sovány alany ragaszkodott a póz megtartásához, a szükséges erőfeszítés ellenére.'::text),
(387543,43061,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bodybuilder ... nicht den ganzen Jubel stehlen dürfen! Der Moment des dünnen Typen ist komplett ruiniert!'::text,'hätte'::text,'darf'::text,'konnte'::text,'Der Bodybuilder hätte nicht den ganzen Jubel stehlen dürfen! Der Moment des dünnen Typen ist komplett ruiniert!'::text),
(387547,43061,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бодібілдерові ... красти всі оплески! Момент худого хлопця повністю зіпсовано!'::text,'не слід було'::text,'не можна було'::text,'не міг'::text,'Бодібілдерові не слід було красти всі оплески! Момент худого хлопця повністю зіпсовано!'::text),
(387546,43061,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El culturista no ... robado todos los aplausos! ¡El momento del chico flaco está totalmente arruinado!'::text,'debería haber'::text,'debe haber'::text,'podía'::text,'¡El culturista no debería haber robado todos los aplausos! ¡El momento del chico flaco está totalmente arruinado!'::text),
(387545,43061,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le culturiste ... voler toutes les acclamations ! Le moment du maigrichon est complètement gâché !'::text,'n''aurait pas dû'::text,'ne doit pas avoir'::text,'ne pouvait pas'::text,'Le culturiste n''aurait pas dû voler toutes les acclamations ! Le moment du maigrichon est complètement gâché !'::text),
(387548,43061,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vücut geliştirici bütün alkışları ...! Sıska çocuğun anı tamamen mahvoldu!'::text,'çalmamalıydı'::text,'çalmamış olmalı'::text,'çalamadı'::text,'Vücut geliştirici bütün alkışları çalmamalıydı! Sıska çocuğun anı tamamen mahvoldu!'::text),
(387549,43061,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A testépítőnek nem ... ellopnia az összes ovációt! A sovány srác pillanata teljesen tönkrement!'::text,'kellett volna'::text,'szabadott'::text,'tudta'::text,'A testépítőnek nem kellett volna ellopnia az összes ovációt! A sovány srác pillanata teljesen tönkrement!'::text),
(387552,43062,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der dünne Typ ließ seinen Kumpel seine Pose ..., und jetzt ist sie für immer im Netz!'::text,'filmen'::text,'zu filmen'::text,'gefilmt'::text,'Der dünne Typ ließ seinen Kumpel seine Pose filmen, und jetzt ist sie für immer im Netz!'::text),
(387556,43062,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Худий хлопець попросив друга ... його позування, і тепер це назавжди в інтернеті!'::text,'зняти'::text,'зняти'::text,'знятий'::text,'Худий хлопець попросив друга зняти його позування, і тепер це назавжди в інтернеті!'::text),
(387555,43062,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El chico flaco hizo que su amigo ... su pose, y ahora está en internet para siempre!'::text,'grabara'::text,'grabar'::text,'grabado'::text,'¡El chico flaco hizo que su amigo grabara su pose, y ahora está en internet para siempre!'::text),
(387554,43062,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le maigrichon a fait ... sa pose par son pote, et maintenant elle est en ligne pour toujours !'::text,'filmer'::text,'filmer'::text,'filmée'::text,'Le maigrichon a fait filmer sa pose par son pote, et maintenant elle est en ligne pour toujours !'::text),
(387557,43062,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıska çocuk pozunu arkadaşına ... ve artık sonsuza dek internette!'::text,'çektirdi'::text,'çekmek'::text,'çekilmiş'::text,'Sıska çocuk pozunu arkadaşına çektirdi ve artık sonsuza dek internette!'::text),
(387558,43062,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sovány srác ... a barátjával a pózolását, és most örökre fent van a neten!'::text,'levideóztatta'::text,'levideózni'::text,'levideózva'::text,'A sovány srác levideóztatta a barátjával a pózolását, és most örökre fent van a neten!'::text),
(332544,36950,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... jetzt schon so zehn Minuten in totaler Ehrfurcht dieses Skelett an, echt.'::text,'starrt'::text,'starrt'::text,'starrt'::text,'Bro, er starrt jetzt schon so zehn Minuten in totaler Ehrfurcht dieses Skelett an, echt.'::text),
(332548,36950,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... на той скелет у повному захваті вже хвилин десять, реально.'::text,'витріщається'::text,'витріщається'::text,'витріщається'::text,'Бро, він витріщається на той скелет у повному захваті вже хвилин десять, реально.'::text),
(332547,36950,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, lleva como diez minutos ... ese esqueleto totalmente alucinado, en serio.'::text,'mirando'::text,'mirando'::text,'mirando'::text,'Bro, lleva como diez minutos mirando ese esqueleto totalmente alucinado, en serio.'::text),
(332546,36950,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ça fait genre dix minutes qu''il ... ce squelette, complètement émerveillé, grave.'::text,'fixe'::text,'fixe'::text,'fixe'::text,'Frérot, ça fait genre dix minutes qu''il fixe ce squelette, complètement émerveillé, grave.'::text),
(332549,36950,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, on dakikadır falan o iskelete tam bir hayranlıkla ..., cidden.'::text,'bakıyor'::text,'bakıyor'::text,'bakar'::text,'Kanka, on dakikadır falan o iskelete tam bir hayranlıkla bakıyor, cidden.'::text),
(332550,36950,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, már vagy tíz perce ... azt a csontvázat teljes ámulatban, komolyan.'::text,'bámulja'::text,'bámulja'::text,'bámulja'::text,'Tesó, már vagy tíz perce bámulja azt a csontvázat teljes ámulatban, komolyan.'::text),
(332553,36951,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, hätte er nicht hochgeschaut, ... er das Skelett, das ihn in Ehrfurcht versetzt hat, nicht gesehen, echt.'::text,'hätte'::text,'wird'::text,'sah'::text,'Alter, hätte er nicht hochgeschaut, hätte er das Skelett, das ihn in Ehrfurcht versetzt hat, nicht gesehen, echt.'::text),
(332557,36951,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якби він не подивився вгору, він ... скелета, від якого завмер у захваті, реально.'::text,'не побачив би'::text,'не побачить'::text,'не бачив'::text,'Чувак, якби він не подивився вгору, він не побачив би скелета, від якого завмер у захваті, реально.'::text),
(332556,36951,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si no hubiera mirado hacia arriba, no ... el esqueleto que lo dejó alucinado, en serio.'::text,'habría visto'::text,'verá'::text,'vio'::text,'Tío, si no hubiera mirado hacia arriba, no habría visto el esqueleto que lo dejó alucinado, en serio.'::text),
(332555,36951,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, s''il n''avait pas levé les yeux, il ... le squelette qui l''a laissé bouche bée, grave.'::text,'n''aurait pas vu'::text,'ne verra pas'::text,'n''a pas vu'::text,'Mec, s''il n''avait pas levé les yeux, il n''aurait pas vu le squelette qui l''a laissé bouche bée, grave.'::text),
(332558,36951,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yukarı bakmasaydı onu hayranlıkla donduran iskeleti ..., cidden.'::text,'görmezdi'::text,'görmeyecek'::text,'görmedi'::text,'Kanka, yukarı bakmasaydı onu hayranlıkla donduran iskeleti görmezdi, cidden.'::text),
(332559,36951,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nem nézett volna fel, nem ... a csontvázat, amitől elállt a lélegzete, komolyan.'::text,'látta volna'::text,'fogja látni'::text,'látta'::text,'Tesó, ha nem nézett volna fel, nem látta volna a csontvázat, amitől elállt a lélegzete, komolyan.'::text),
(332562,36952,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Museumsleiter berichtete, dieses Quartal Hunderte Besucher in Ehrfurcht vor dem Skelett ...'::text,'gesehen zu haben'::text,'zu sehen'::text,'sah'::text,'Der Museumsleiter berichtete, dieses Quartal Hunderte Besucher in Ehrfurcht vor dem Skelett gesehen zu haben.'::text),
(332566,36952,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Менеджер музею повідомив, що цього кварталу ... сотні відвідувачів, які завмирали в захваті перед скелетом.'::text,'бачив'::text,'бачити'::text,'бачив'::text,'Менеджер музею повідомив, що цього кварталу бачив сотні відвідувачів, які завмирали в захваті перед скелетом.'::text),
(332565,36952,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gerente del museo informó de ... cientos de visitantes asombrados ante el esqueleto este trimestre.'::text,'haber visto'::text,'ver'::text,'vio'::text,'El gerente del museo informó de haber visto cientos de visitantes asombrados ante el esqueleto este trimestre.'::text),
(332564,36952,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le directeur du musée a déclaré ... des centaines de visiteurs émerveillés devant le squelette ce trimestre.'::text,'avoir vu'::text,'voir'::text,'a vu'::text,'Le directeur du musée a déclaré avoir vu des centaines de visiteurs émerveillés devant le squelette ce trimestre.'::text),
(332567,36952,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müze müdürü bu çeyrekte yüzlerce ziyaretçiyi iskelet karşısında hayranlık içinde ... bildirdi.'::text,'gördüğünü'::text,'görmeyi'::text,'gördü'::text,'Müze müdürü bu çeyrekte yüzlerce ziyaretçiyi iskelet karşısında hayranlık içinde gördüğünü bildirdi.'::text),
(332568,36952,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A múzeum vezetője arról számolt be, hogy ebben a negyedévben több száz látogatót ... a csontváz előtt ámulatban.'::text,'látott'::text,'látni'::text,'látott'::text,'A múzeum vezetője arról számolt be, hogy ebben a negyedévben több száz látogatót látott a csontváz előtt ámulatban.'::text),
(332571,36953,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor lauter Ehrfurcht wäre er fast gegen eine Säule gelaufen; er ... schauen sollen, wo er hingeht.'::text,'hätte'::text,'muss'::text,'kann nicht'::text,'Vor lauter Ehrfurcht wäre er fast gegen eine Säule gelaufen; er hätte schauen sollen, wo er hingeht.'::text),
(332575,36953,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Заглибившись у захват, він мало не врізався в колону; йому ... дивитися, куди він іде.'::text,'треба було'::text,'мусив'::text,'не міг'::text,'Заглибившись у захват, він мало не врізався в колону; йому треба було дивитися, куди він іде.'::text),
(332574,36953,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absorto en su asombro, casi choca con una columna; ... mirado por dónde iba.'::text,'debería haber'::text,'debe de haber'::text,'no puede haber'::text,'Absorto en su asombro, casi choca con una columna; debería haber mirado por dónde iba.'::text),
(332573,36953,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perdu dans son émerveillement, il a failli percuter un pilier ; il ... regarder où il allait.'::text,'aurait dû'::text,'a dû'::text,'n''a pas pu'::text,'Perdu dans son émerveillement, il a failli percuter un pilier ; il aurait dû regarder où il allait.'::text),
(332576,36953,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayranlığa dalmışken neredeyse bir sütuna çarpıyordu; nereye gittiğine ...'::text,'bakmalıydı'::text,'bakmış olmalı'::text,'bakmış olamaz'::text,'Hayranlığa dalmışken neredeyse bir sütuna çarpıyordu; nereye gittiğine bakmalıydı.'::text),
(332577,36953,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ámulattól majdnem nekiment egy oszlopnak; ..., merre megy.'::text,'figyelnie kellett volna'::text,'biztosan figyelt'::text,'nem figyelhetett'::text,'Az ámulattól majdnem nekiment egy oszlopnak; figyelnie kellett volna, merre megy.'::text),
(332589,36955,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich offensichtlich, er ... zu Hause geblieben. Null Ehrfurcht in diesem Gesicht.'::text,'wäre'::text,'bliebe'::text,'würde'::text,'Er wünscht sich offensichtlich, er wäre zu Hause geblieben. Null Ehrfurcht in diesem Gesicht.'::text),
(332593,36955,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він явно хотів би ... вдома. На цьому обличчі жодного захвату.'::text,'залишитися'::text,'залишитися'::text,'залишитися'::text,'Він явно хотів би залишитися вдома. На цьому обличчі жодного захвату.'::text),
(332592,36955,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, desearía ... en casa. Ni pizca de asombro en esa cara.'::text,'haberse quedado'::text,'quedarse'::text,'quedarse'::text,'Obviamente, desearía haberse quedado en casa. Ni pizca de asombro en esa cara.'::text),
