(332594,36955,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki keşke evde ... diye düşünüyor. O yüzde hiç hayranlık yok.'::text,'kalsaydım'::text,'kalsam'::text,'kalırdım'::text,'Belli ki keşke evde kalsaydım diye düşünüyor. O yüzde hiç hayranlık yok.'::text),
