(392309,43590,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bayrağını Asya''ya ..., sonra dönüp sevinçle bağırdın. Havalı.'::text,'taktın'::text,'takıyordun'::text,'takmışsın'::text,'Açıkçası, bayrağını Asya''ya taktın, sonra dönüp sevinçle bağırdın. Havalı.'::text),
(392310,43590,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... a zászlódat Ázsiára, aztán megfordultál és ujjongtál. Menő.'::text,'kitűzted'::text,'tűzted'::text,'kitűzted'::text,'Őszintén, kitűzted a zászlódat Ázsiára, aztán megfordultál és ujjongtál. Menő.'::text),
(392322,43592,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie für die Kamera posierten, ... alle vier ihre Fotos schon auf die Karte geklebt.'::text,'hatten'::text,'haben'::text,'kleben'::text,'Als sie für die Kamera posierten, hatten alle vier ihre Fotos schon auf die Karte geklebt.'::text),
(392326,43592,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вони позували на камеру, всі четверо вже ... свої фото на мапу.'::text,'приклеїли'::text,'приклеїли'::text,'приклеюють'::text,'Поки вони позували на камеру, всі четверо вже приклеїли свої фото на мапу.'::text),
(392325,43592,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando posaron para la cámara, los cuatro ya ... sus fotos en el mapa.'::text,'habían pegado'::text,'han pegado'::text,'pegan'::text,'Para cuando posaron para la cámara, los cuatro ya habían pegado sus fotos en el mapa.'::text),
(392324,43592,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps qu''ils posent pour la caméra, tous les quatre ... leurs photos sur la carte.'::text,'avaient collé'::text,'ont collé'::text,'collent'::text,'Le temps qu''ils posent pour la caméra, tous les quatre avaient collé leurs photos sur la carte.'::text),
(392327,43592,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera için poz verdiklerinde dördü de fotoğraflarını haritaya çoktan ...'::text,'yapıştırmıştı'::text,'yapıştırdı'::text,'yapıştırıyor'::text,'Kamera için poz verdiklerinde dördü de fotoğraflarını haritaya çoktan yapıştırmıştı.'::text),
(392328,43592,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kamerának pózoltak, mind a négyen ... a fotóikat a térképre.'::text,'felragasztották'::text,'felragasztották'::text,'ragasztják'::text,'Mire a kamerának pózoltak, mind a négyen felragasztották a fotóikat a térképre.'::text),
(392331,43593,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie ein weiteres Land besuchen, ... sie eine neue Flagge auf die Karte.'::text,'stecken'::text,'würden'::text,'steckten'::text,'Wenn sie ein weiteres Land besuchen, stecken sie eine neue Flagge auf die Karte.'::text),
(392335,43593,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вони відвідають ще одну країну, вони ... новий прапорець на мапу.'::text,'встромлять'::text,'встромили б'::text,'встромили'::text,'Якщо вони відвідають ще одну країну, вони встромлять новий прапорець на мапу.'::text),
(392334,43593,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si visitan otro país, ... una bandera nueva en el mapa.'::text,'clavarán'::text,'clavarían'::text,'clavaron'::text,'Si visitan otro país, clavarán una bandera nueva en el mapa.'::text),
(392333,43593,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils visitent un autre pays, ils ... un nouveau drapeau sur la carte.'::text,'planteront'::text,'planteraient'::text,'ont planté'::text,'S''ils visitent un autre pays, ils planteront un nouveau drapeau sur la carte.'::text),
(392336,43593,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başka bir ülkeye giderlerse haritaya yeni bir bayrak ...'::text,'takacaklar'::text,'takarlardı'::text,'taktılar'::text,'Başka bir ülkeye giderlerse haritaya yeni bir bayrak takacaklar.'::text),
(392337,43593,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha elmennek egy másik országba, új zászlót ... a térképre.'::text,'tűznek ki'::text,'tűznének ki'::text,'tűztek ki'::text,'Ha elmennek egy másik országba, új zászlót tűznek ki a térképre.'::text),
(392340,43594,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Karte größer wäre, ... sie mehr Fotos darauf kleben.'::text,'würden'::text,'werden'::text,'kleben'::text,'Wenn die Karte größer wäre, würden sie mehr Fotos darauf kleben.'::text),
(392344,43594,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби мапа була більшою, вони ... на неї більше фото.'::text,'приклеїли б'::text,'приклеять'::text,'приклеюють'::text,'Якби мапа була більшою, вони приклеїли б на неї більше фото.'::text),
(392343,43594,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el mapa fuera más grande, ... más fotos en él.'::text,'pegarían'::text,'pegarán'::text,'pegan'::text,'Si el mapa fuera más grande, pegarían más fotos en él.'::text),
(392342,43594,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la carte était plus grande, ils y ... plus de photos.'::text,'colleraient'::text,'colleront'::text,'collent'::text,'Si la carte était plus grande, ils y colleraient plus de photos.'::text),
(392345,43594,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harita daha büyük olsaydı, üzerine daha fazla fotoğraf ...'::text,'yapıştırırlardı'::text,'yapıştıracaklar'::text,'yapıştırırlar'::text,'Harita daha büyük olsaydı, üzerine daha fazla fotoğraf yapıştırırlardı.'::text),
(392346,43594,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nagyobb lenne a térkép, több fotót ... rá.'::text,'ragasztanának'::text,'fognak ragasztani'::text,'ragasztanak'::text,'Ha nagyobb lenne a térkép, több fotót ragasztanának rá.'::text),
(392349,43595,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, ich ... meine Flagge als Erster auf Asien gesteckt! Jetzt ist mein Trip für immer ruiniert!'::text,'hätte'::text,'steckte'::text,'habe'::text,'Ich wünschte, ich hätte meine Flagge als Erster auf Asien gesteckt! Jetzt ist mein Trip für immer ruiniert!'::text),
(392353,43595,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ж я ... свій прапорець на Азію першим! Тепер моя подорож назавжди зіпсована!'::text,'встромив'::text,'встромив'::text,'встромив'::text,'Якби ж я встромив свій прапорець на Азію першим! Тепер моя подорож назавжди зіпсована!'::text),
(392352,43595,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ojalá ... mi bandera en Asia el primero! ¡Ahora mi viaje está arruinado para siempre!'::text,'hubiera clavado'::text,'clavara'::text,'he clavado'::text,'¡Ojalá hubiera clavado mi bandera en Asia el primero! ¡Ahora mi viaje está arruinado para siempre!'::text),
(392351,43595,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'J''aurais tellement voulu ... mon drapeau sur l''Asie en premier ! Maintenant mon voyage est gâché pour toujours !'::text,'avoir planté'::text,'planter'::text,'ai planté'::text,'J''aurais tellement voulu avoir planté mon drapeau sur l''Asie en premier ! Maintenant mon voyage est gâché pour toujours !'::text),
(392354,43595,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke bayrağımı Asya''ya ilk ben ...! Artık gezim sonsuza dek mahvoldu!'::text,'taksaydım'::text,'taksam'::text,'taktım'::text,'Keşke bayrağımı Asya''ya ilk ben taksaydım! Artık gezim sonsuza dek mahvoldu!'::text),
(392355,43595,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak én ... ki elsőként a zászlómat Ázsiára! Most örökre tönkrement az utam!'::text,'tűztem volna'::text,'tűzném'::text,'tűztem'::text,'Bárcsak én tűztem volna ki elsőként a zászlómat Ázsiára! Most örökre tönkrement az utam!'::text),
(392358,43596,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mitbewohner, ... Foto auf Asien klebt, wird nie, nie wieder aufhören, darüber zu reden!'::text,'dessen'::text,'der'::text,'welches'::text,'Der Mitbewohner, dessen Foto auf Asien klebt, wird nie, nie wieder aufhören, darüber zu reden!'::text),
(392362,43596,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сусід, ... фото приклеєне на Азії, ніколи-ніколи не перестане про це говорити!'::text,'чиє'::text,'який'::text,'що'::text,'Сусід, чиє фото приклеєне на Азії, ніколи-ніколи не перестане про це говорити!'::text),
(392361,43596,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El compañero de piso ... foto está pegada en Asia nunca, jamás dejará de hablar de ello!'::text,'cuya'::text,'que'::text,'el cual'::text,'¡El compañero de piso cuya foto está pegada en Asia nunca, jamás dejará de hablar de ello!'::text),
(392360,43596,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le coloc ... la photo est collée sur l''Asie n''arrêtera jamais, au grand jamais, d''en parler !'::text,'dont'::text,'qui'::text,'lequel'::text,'Le coloc dont la photo est collée sur l''Asie n''arrêtera jamais, au grand jamais, d''en parler !'::text),
(392363,43596,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fotoğrafı Asya''ya yapıştırılan ev arkadaşı bundan bahsetmeyi asla ama asla bırakmayacak!'::text,''::text,NULL::text,NULL::text,'Fotoğrafı Asya''ya yapıştırılan ev arkadaşı bundan bahsetmeyi asla ama asla bırakmayacak!'::text),
(392364,43596,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lakótárs, ... fotója Ázsián van, soha, de soha nem fogja abbahagyni, hogy erről beszéljen!'::text,'akinek a'::text,'aki'::text,'amely'::text,'A lakótárs, akinek a fotója Ázsián van, soha, de soha nem fogja abbahagyni, hogy erről beszéljen!'::text),
(392367,43597,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie stecken auf jeden Ort eine Flagge, ... sie ihn für immer vergessen!'::text,'falls'::text,'außer wenn'::text,'damit'::text,'Sie stecken auf jeden Ort eine Flagge, falls sie ihn für immer vergessen!'::text),
(392371,43597,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони чіпляють прапорець на кожне місце, ... забудуть його назавжди!'::text,'на випадок, якщо'::text,'хіба що'::text,'щоб'::text,'Вони чіпляють прапорець на кожне місце, на випадок, якщо забудуть його назавжди!'::text),
(392370,43597,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Clavan una bandera en cada lugar ... lo olvidan para siempre!'::text,'por si'::text,'a menos que'::text,'para que'::text,'¡Clavan una bandera en cada lugar por si lo olvidan para siempre!'::text),
(392369,43597,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils plantent un drapeau sur chaque endroit ... ils l''oublieraient pour toujours !'::text,'au cas où'::text,'à moins que'::text,'pour que'::text,'Ils plantent un drapeau sur chaque endroit au cas où ils l''oublieraient pour toujours !'::text),
(392372,43597,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her yere bir bayrak takıyorlar, ... orayı sonsuza dek unuturlar diye!'::text,'olur da'::text,'meğer ki'::text,'ki'::text,'Her yere bir bayrak takıyorlar, olur da orayı sonsuza dek unuturlar diye!'::text),
(392373,43597,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden helyre kitűznek egy zászlót, ... örökre elfelejtik!'::text,'arra az esetre, ha'::text,'hacsak nem'::text,'hogy'::text,'Minden helyre kitűznek egy zászlót, arra az esetre, ha örökre elfelejtik!'::text),
(370569,41175,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn diese Übelkeit noch schlimmer ..., würde ich nie wieder eine Fähre betreten!'::text,'würde'::text,'wird'::text,'würde werden'::text,'Wenn diese Übelkeit noch schlimmer würde, würde ich nie wieder eine Fähre betreten!'::text),
(370573,41175,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ця нудота ... сильнішою, я б ніколи більше не ступила на пором!'::text,'стала'::text,'стане'::text,'стала б'::text,'Якби ця нудота стала сильнішою, я б ніколи більше не ступила на пором!'::text),
(370572,41175,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si estas náuseas ... a peor, no volvería a subir a un ferri nunca más!'::text,'fueran'::text,'van'::text,'irían'::text,'¡Si estas náuseas fueran a peor, no volvería a subir a un ferri nunca más!'::text),
(370571,41175,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cette nausée ..., je ne remettrais plus jamais les pieds sur un ferry !'::text,'empirait'::text,'empire'::text,'empirerait'::text,'Si cette nausée empirait, je ne remettrais plus jamais les pieds sur un ferry !'::text),
(370574,41175,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu mide bulantısı daha da ..., bir daha asla feribota binmezdim!'::text,'kötüleşse'::text,'kötüleşirse'::text,'kötüleşirdi'::text,'Bu mide bulantısı daha da kötüleşse, bir daha asla feribota binmezdim!'::text),
(370575,41175,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ez a hányinger ..., soha többé nem szállnék komra!'::text,'rosszabbodna'::text,'rosszabbodik'::text,'rosszabbodna'::text,'Ha ez a hányinger rosszabbodna, soha többé nem szállnék komra!'::text),
(370578,41176,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Übelkeit ... durch das endlose Schaukeln der Fähre verursacht! Ein absoluter Albtraum!'::text,'wurde'::text,'verursachte'::text,'verursacht gerade'::text,'Ihre Übelkeit wurde durch das endlose Schaukeln der Fähre verursacht! Ein absoluter Albtraum!'::text),
(370582,41176,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її нудота ... нескінченним гойданням порома! Абсолютний жах!'::text,'була спричинена'::text,'спричинила'::text,'спричиняє'::text,'Її нудота була спричинена нескінченним гойданням порома! Абсолютний жах!'::text),
(370581,41176,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Sus náuseas ... por el balanceo interminable del ferri! ¡Una pesadilla total!'::text,'fueron causadas'::text,'causaron'::text,'están causando'::text,'¡Sus náuseas fueron causadas por el balanceo interminable del ferri! ¡Una pesadilla total!'::text),
(370580,41176,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa nausée ... par le roulis interminable du ferry ! Un cauchemar absolu !'::text,'a été causée'::text,'a causé'::text,'est en train de causer'::text,'Sa nausée a été causée par le roulis interminable du ferry ! Un cauchemar absolu !'::text),
(370583,41176,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mide bulantısı feribotun bitmek bilmeyen sallanmasıyla ...! Tam bir kâbus!'::text,'tetiklendi'::text,'tetikledi'::text,'tetikliyor'::text,'Mide bulantısı feribotun bitmek bilmeyen sallanmasıyla tetiklendi! Tam bir kâbus!'::text),
(370584,41176,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hányingerét a komp végtelen ringatózása ...! Abszolút rémálom!'::text,'okozta'::text,'okozta'::text,'okozza'::text,'A hányingerét a komp végtelen ringatózása okozta! Abszolút rémálom!'::text),
(370587,41177,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat mir erzählt, dass ihr die Fähre eine schreckliche Übelkeit ...'::text,'bescherte'::text,'beschert wurde'::text,'bescherend'::text,'Bestie, sie hat mir erzählt, dass ihr die Fähre eine schreckliche Übelkeit bescherte.'::text),
(370591,41177,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона мені сказала, що пором ... їй жахливу нудоту.'::text,'викликав'::text,'був викликаний'::text,'викликання'::text,'Подруго, вона мені сказала, що пором викликав їй жахливу нудоту.'::text),
(370590,41177,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que el ferri le ... unas náuseas horribles.'::text,'dio'::text,'fue dado'::text,'dando'::text,'Amiga, me dijo que el ferri le dio unas náuseas horribles.'::text),
(370589,41177,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit que le ferry lui ... une nausée horrible.'::text,'a donné'::text,'a été donné'::text,'donnant'::text,'Ma belle, elle m''a dit que le ferry lui a donné une nausée horrible.'::text),
(370592,41177,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana feribotun ona korkunç bir mide bulantısı ... söyledi.'::text,'verdiğini'::text,'verildiğini'::text,'vermeyi'::text,'Kanka, bana feribotun ona korkunç bir mide bulantısı verdiğini söyledi.'::text),
(370593,41177,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy a komp ... neki a szörnyű hányingert.'::text,'okozta'::text,'okozva lett'::text,'okozva'::text,'Csajszi, azt mondta, hogy a komp okozta neki a szörnyű hányingert.'::text),
(370596,41178,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hält sich den Mund zu, also ... ihre Übelkeit sehr stark sein.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Sie hält sich den Mund zu, also muss ihre Übelkeit sehr stark sein.'::text),
(370600,41178,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона затуляє рот, тож її нудота ... бути дуже сильною.'::text,'мусить'::text,'не може'::text,'повинна'::text,'Вона затуляє рот, тож її нудота мусить бути дуже сильною.'::text),
(370599,41178,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se está tapando la boca, así que sus náuseas ... ser muy fuertes.'::text,'deben de'::text,'no pueden'::text,'deberían'::text,'Se está tapando la boca, así que sus náuseas deben de ser muy fuertes.'::text),
(370598,41178,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle se tient la bouche, donc sa nausée ... être très forte.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Elle se tient la bouche, donc sa nausée doit être très forte.'::text),
(370601,41178,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ağzını tutuyor, yani mide bulantısı çok güçlü ...'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Ağzını tutuyor, yani mide bulantısı çok güçlü olmalı.'::text),
(370602,41178,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szájára szorítja a kezét, szóval a hányingere ... nagyon erős.'::text,'biztosan'::text,'nem lehet'::text,'kellene hogy legyen'::text,'A szájára szorítja a kezét, szóval a hányingere biztosan nagyon erős.'::text),
(370614,41180,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie erzählte einem Passagier, dass die Übelkeit ..., sobald die Fähre abgelegt hatte.'::text,'angefangen hatte'::text,'angefangen hat'::text,'anfängt'::text,'Sie erzählte einem Passagier, dass die Übelkeit angefangen hatte, sobald die Fähre abgelegt hatte.'::text),
(370618,41180,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала одному пасажирові, що нудота ..., щойно пором відплив.'::text,'почалася'::text,'почалася'::text,'починається'::text,'Вона сказала одному пасажирові, що нудота почалася, щойно пором відплив.'::text),
(370617,41180,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le contó a un pasajero que las náuseas ... en cuanto salió el ferri.'::text,'habían empezado'::text,'han empezado'::text,'empiezan'::text,'Le contó a un pasajero que las náuseas habían empezado en cuanto salió el ferri.'::text),
(370616,41180,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit à un passager que la nausée ... dès que le ferry était parti.'::text,'avait commencé'::text,'a commencé'::text,'commence'::text,'Elle a dit à un passager que la nausée avait commencé dès que le ferry était parti.'::text),
(370619,41180,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yolcuya mide bulantısının feribot kalkar kalkmaz ... söyledi.'::text,'başladığını'::text,'başladığını'::text,'başladığını'::text,'Bir yolcuya mide bulantısının feribot kalkar kalkmaz başladığını söyledi.'::text),
(370620,41180,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta egy utasnak, hogy a hányinger ..., amint a komp elindult.'::text,'elkezdődött'::text,'elkezdődött'::text,'elkezdődik'::text,'Azt mondta egy utasnak, hogy a hányinger elkezdődött, amint a komp elindult.'::text),
(370623,41181,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Früher ... du ohne Übelkeit Fähre gefahren, oder? Die petrolfarbene Jacke ist immer noch stylisch.'::text,'bist'::text,'warst es gewohnt'::text,'bist'::text,'Früher bist du ohne Übelkeit Fähre gefahren, oder? Die petrolfarbene Jacke ist immer noch stylisch.'::text),
(370627,41181,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... подорожувати поромом без нудоти, так? Ця бірюзова куртка досі стильна.'::text,'колись могла'::text,'звикла'::text,'колись могла'::text,'Ти колись могла подорожувати поромом без нудоти, так? Ця бірюзова куртка досі стильна.'::text),
(370626,41181,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes ... en ferri sin náuseas, ¿verdad? Esa chaqueta turquesa sigue siendo muy elegante.'::text,'viajabas'::text,'estabas acostumbrada a viajar'::text,'viajabas'::text,'Antes viajabas en ferri sin náuseas, ¿verdad? Esa chaqueta turquesa sigue siendo muy elegante.'::text),
(370625,41181,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, tu ... en ferry sans nausée, non ? Cette veste bleu canard est toujours stylée.'::text,'voyageais'::text,'étais habituée à voyager'::text,'voyageais'::text,'Avant, tu voyageais en ferry sans nausée, non ? Cette veste bleu canard est toujours stylée.'::text),
(370628,41181,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden feribotla mide bulantısı olmadan ..., değil mi? O petrol mavisi ceket hâlâ çok havalı.'::text,'seyahat ederdin'::text,'seyahat etmeye alışkındın'::text,'seyahat ederdin'::text,'Eskiden feribotla mide bulantısı olmadan seyahat ederdin, değil mi? O petrol mavisi ceket hâlâ çok havalı.'::text),
(370629,41181,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... hányinger nélkül komppal, igaz? Az a kékeszöld kabát még mindig menő.'::text,'utaztál'::text,'hozzá voltál szokva utazni'::text,'utaztál'::text,'Régen utaztál hányinger nélkül komppal, igaz? Az a kékeszöld kabát még mindig menő.'::text),
(370632,41182,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast dich trotz der Übelkeit geweigert, in der Kabine zu ...! Respekt.'::text,'bleiben'::text,'bleiben'::text,'bleiben'::text,'Du hast dich trotz der Übelkeit geweigert, in der Kabine zu bleiben! Respekt.'::text),
(370636,41182,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти відмовилася ... в каюті, попри нудоту. Респект.'::text,'залишатися'::text,'залишатися'::text,'залишатися'::text,'Ти відмовилася залишатися в каюті, попри нудоту. Респект.'::text),
(370635,41182,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te negaste a ... en el camarote a pesar de las náuseas. Respeto.'::text,'quedarte'::text,'quedarte'::text,'quedarte'::text,'Te negaste a quedarte en el camarote a pesar de las náuseas. Respeto.'::text),
(370634,41182,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as refusé de ... dans la cabine malgré la nausée. Respect.'::text,'rester'::text,'rester'::text,'rester'::text,'Tu as refusé de rester dans la cabine malgré la nausée. Respect.'::text),
(370637,41182,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mide bulantısına rağmen kamarada ... reddettin. Saygılar.'::text,'kalmayı'::text,'kalmayı'::text,'kalmayı'::text,'Mide bulantısına rağmen kamarada kalmayı reddettin. Saygılar.'::text),
(370638,41182,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem voltál hajlandó ... a kabinban a hányinger ellenére. Respekt.'::text,'maradni'::text,'maradni'::text,'maradni'::text,'Nem voltál hajlandó maradni a kabinban a hányinger ellenére. Respekt.'::text),
(370641,41183,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Was für eine entspannte Fährfahrt, natürlich. Ihre Übelkeit ist jetzt weg, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Was für eine entspannte Fährfahrt, natürlich. Ihre Übelkeit ist jetzt weg, oder?'::text),
(370645,41183,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Яка розслаблювальна подорож поромом, звісно. Її нудота вже минула, ...?'::text,'правда ж?'::text,'правда ж?'::text,'правда ж?'::text,'Яка розслаблювальна подорож поромом, звісно. Її нудота вже минула, правда ж?'::text),
(370644,41183,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Menudo viaje en ferri tan relajante, obviamente. Ya se le han pasado las náuseas, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Menudo viaje en ferri tan relajante, obviamente. Ya se le han pasado las náuseas, ¿verdad?'::text),
(370643,41183,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quel voyage en ferry reposant, évidemment. Sa nausée est passée maintenant, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Quel voyage en ferry reposant, évidemment. Sa nausée est passée maintenant, non ?'::text),
(370646,41183,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne kadar rahatlatıcı bir feribot yolculuğu, tabii ki. Mide bulantısı artık geçti, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Ne kadar rahatlatıcı bir feribot yolculuğu, tabii ki. Mide bulantısı artık geçti, değil mi?'::text),
(370647,41183,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda pihentető komputazás, nyilván. A hányingere már elmúlt, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Micsoda pihentető komputazás, nyilván. A hányingere már elmúlt, ugye?'::text),
(370650,41184,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Übelkeit geht nicht weg, und ... die Wellen. Tolle Reise, natürlich.'::text,'genauso wenig'::text,'genauso'::text,'genauso wenig'::text,'Ihre Übelkeit geht nicht weg, und genauso wenig die Wellen. Tolle Reise, natürlich.'::text),
(370654,41184,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її нудота не минає, ... хвилі. Чудова подорож, звісно.'::text,'як і'::text,'і'::text,'як і'::text,'Її нудота не минає, як і хвилі. Чудова подорож, звісно.'::text),
(370653,41184,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus náuseas no se van, y ... las olas. Gran viaje, obviamente.'::text,'tampoco'::text,'también'::text,'tampoco'::text,'Sus náuseas no se van, y tampoco las olas. Gran viaje, obviamente.'::text),
(370652,41184,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa nausée ne passe pas, ... les vagues. Super voyage, évidemment.'::text,'pas plus que'::text,'tout comme'::text,'pas plus que'::text,'Sa nausée ne passe pas, pas plus que les vagues. Super voyage, évidemment.'::text),
(370655,41184,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mide bulantısı geçmiyor, dalgalar ... dinmiyor. Harika bir yolculuk, tabii ki.'::text,'da'::text,'da'::text,'da'::text,'Mide bulantısı geçmiyor, dalgalar da dinmiyor. Harika bir yolculuk, tabii ki.'::text),
(370656,41184,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hányingere nem múlik el, és a hullámok ... csillapodnak. Remek út, nyilván.'::text,'sem'::text,'is'::text,'sem'::text,'A hányingere nem múlik el, és a hullámok sem csillapodnak. Remek út, nyilván.'::text),
(329934,36660,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie hat mir erzählt, sie ... gerade durch diese winzige Gasse, als ihr ein Typ den Weg versperrte.'::text,'lief'::text,'lief'::text,'ist gelaufen'::text,'Mädel, sie hat mir erzählt, sie lief gerade durch diese winzige Gasse, als ihr ein Typ den Weg versperrte.'::text),
(329938,36660,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона мені розповіла, що ... тим крихітним провулком, коли якийсь хлопець перегородив їй дорогу.'::text,'йшла'::text,'пройшла'::text,'пройшла'::text,'Подруго, вона мені розповіла, що йшла тим крихітним провулком, коли якийсь хлопець перегородив їй дорогу.'::text),
(329937,36660,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me contó que ... por ese callejón diminuto cuando un tío le cortó el paso.'::text,'iba caminando'::text,'caminó'::text,'ha caminado'::text,'Tía, me contó que iba caminando por ese callejón diminuto cuando un tío le cortó el paso.'::text),
(329936,36660,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit qu''elle ... dans cette ruelle minuscule quand un mec lui a barré la route.'::text,'marchait'::text,'a marché'::text,'a marché'::text,'Meuf, elle m''a dit qu''elle marchait dans cette ruelle minuscule quand un mec lui a barré la route.'::text),
(329939,36660,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana o minicik ara sokakta ... bir adamın yolunu kestiğini söyledi.'::text,'yürürken'::text,'yürüdü'::text,'yürümüş'::text,'Kızım, bana o minicik ara sokakta yürürken bir adamın yolunu kestiğini söyledi.'::text),
(329940,36660,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy épp ... abban a pici sikátorban, amikor egy srác elállta az útját.'::text,'sétált'::text,'végigsétált'::text,'végigsétált'::text,'Csajszi, azt mondta, hogy épp sétált abban a pici sikátorban, amikor egy srác elállta az útját.'::text),
(329952,36662,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie den Platz erreichte, ... sie durch eine sehr enge Gasse gelaufen.'::text,'war'::text,'ist'::text,'läuft'::text,'Bevor sie den Platz erreichte, war sie durch eine sehr enge Gasse gelaufen.'::text),
(329956,36662,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж дійти до площі, вона ... дуже вузьким провулком.'::text,'пройшла'::text,'пройшла'::text,'проходить'::text,'Перш ніж дійти до площі, вона пройшла дуже вузьким провулком.'::text),
(329955,36662,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de llegar a la plaza, ... por un callejón muy estrecho.'::text,'había pasado'::text,'ha pasado'::text,'pasa'::text,'Antes de llegar a la plaza, había pasado por un callejón muy estrecho.'::text),
(329954,36662,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant d''arriver sur la place, elle ... par une ruelle très étroite.'::text,'était passée'::text,'est passée'::text,'passe'::text,'Avant d''arriver sur la place, elle était passée par une ruelle très étroite.'::text),
(329957,36662,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meydana varmadan önce çok dar bir ara sokaktan ...'::text,'geçmişti'::text,'geçti'::text,'geçiyor'::text,'Meydana varmadan önce çok dar bir ara sokaktan geçmişti.'::text),
(329958,36662,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a térre ért, egy nagyon szűk sikátoron ... át.'::text,'ment'::text,'ment'::text,'megy'::text,'Mielőtt a térre ért, egy nagyon szűk sikátoron ment át.'::text),
(329961,36663,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie der Karte durch diese Gasse folgt, ... sie den großen Platz.'::text,'erreicht'::text,'würde erreichen'::text,'erreichte'::text,'Wenn sie der Karte durch diese Gasse folgt, erreicht sie den großen Platz.'::text),
(329965,36663,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона піде за мапою цим провулком, вона ... до великої площі.'::text,'дійде'::text,'дійшла б'::text,'дійшла'::text,'Якщо вона піде за мапою цим провулком, вона дійде до великої площі.'::text),
(329964,36663,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sigue el mapa por este callejón, ... a la plaza grande.'::text,'llegará'::text,'llegaría'::text,'llegó'::text,'Si sigue el mapa por este callejón, llegará a la plaza grande.'::text),
(329963,36663,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle suit la carte dans cette ruelle, elle ... la grande place.'::text,'atteindra'::text,'atteindrait'::text,'a atteint'::text,'Si elle suit la carte dans cette ruelle, elle atteindra la grande place.'::text),
(329966,36663,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haritayı takip edip bu ara sokaktan giderse büyük meydana ...'::text,'varacak'::text,'varırdı'::text,'vardı'::text,'Haritayı takip edip bu ara sokaktan giderse büyük meydana varacak.'::text),
(329967,36663,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a térkép szerint végigmegy ezen a sikátoron, ... a nagy térre.'::text,'eljut'::text,'eljutna'::text,'eljutott'::text,'Ha a térkép szerint végigmegy ezen a sikátoron, eljut a nagy térre.'::text),
(329970,36664,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Gasse noch enger wäre, ... ihr Rucksack nicht durchpassen.'::text,'würde'::text,'wird'::text,'passt'::text,'Wenn die Gasse noch enger wäre, würde ihr Rucksack nicht durchpassen.'::text),
(329974,36664,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби провулок був ще вужчим, її рюкзак ...'::text,'не пройшов би'::text,'не пройде'::text,'не проходить'::text,'Якби провулок був ще вужчим, її рюкзак не пройшов би.'::text),
(329973,36664,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el callejón fuera un poco más estrecho, su mochila no ...'::text,'cabría'::text,'cabrá'::text,'cabe'::text,'Si el callejón fuera un poco más estrecho, su mochila no cabría.'::text),
(329972,36664,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la ruelle était encore plus étroite, son sac à dos ...'::text,'ne passerait pas'::text,'ne passera pas'::text,'ne passe pas'::text,'Si la ruelle était encore plus étroite, son sac à dos ne passerait pas.'::text),
(329975,36664,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ara sokak biraz daha dar olsaydı, sırt çantası ...'::text,'sığmazdı'::text,'sığmayacak'::text,'sığmıyor'::text,'Ara sokak biraz daha dar olsaydı, sırt çantası sığmazdı.'::text),
(329976,36664,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sikátor még szűkebb lenne, a hátizsákja nem ... át.'::text,'férne'::text,'fog férni'::text,'fér'::text,'Ha a sikátor még szűkebb lenne, a hátizsákja nem férne át.'::text),
(329979,36665,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wände der Gasse ... vor langer Zeit blau und ocker gestrichen.'::text,'wurden'::text,'sind'::text,'strichen'::text,'Die Wände der Gasse wurden vor langer Zeit blau und ocker gestrichen.'::text),
(329983,36665,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стіни провулка ... в синій і вохристий кольори давним-давно.'::text,'були пофарбовані'::text,'пофарбовані'::text,'пофарбували'::text,'Стіни провулка були пофарбовані в синій і вохристий кольори давним-давно.'::text),
(329982,36665,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las paredes del callejón ... de azul y ocre hace mucho tiempo.'::text,'fueron pintadas'::text,'están pintadas'::text,'pintaron'::text,'Las paredes del callejón fueron pintadas de azul y ocre hace mucho tiempo.'::text),
(329981,36665,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les murs de la ruelle ... en bleu et en ocre il y a longtemps.'::text,'ont été peints'::text,'sont peints'::text,'ont peint'::text,'Les murs de la ruelle ont été peints en bleu et en ocre il y a longtemps.'::text),
(329984,36665,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ara sokağın duvarları uzun zaman önce maviye ve toprak sarısına ...'::text,'boyandı'::text,'boyanır'::text,'boyadı'::text,'Ara sokağın duvarları uzun zaman önce maviye ve toprak sarısına boyandı.'::text),
(329985,36665,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sikátor falait régen kékre és okkersárgára ...'::text,'festették'::text,'festik'::text,'festett'::text,'A sikátor falait régen kékre és okkersárgára festették.'::text),
(329988,36666,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich mit einem riesigen Rucksack an einem Mann in der Gasse vorbei. Makellos.'::text,'quetschte'::text,'wurde gequetscht'::text,'quetschend'::text,'Sie quetschte sich mit einem riesigen Rucksack an einem Mann in der Gasse vorbei. Makellos.'::text),
(329992,36666,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... повз чоловіка в провулку з величезним рюкзаком. Бездоганно.'::text,'протиснулася'::text,'була протиснута'::text,'протискання'::text,'Вона протиснулася повз чоловіка в провулку з величезним рюкзаком. Бездоганно.'::text),
(329991,36666,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... junto a un hombre en el callejón con una mochila enorme. Impecable.'::text,'se escurrió'::text,'fue escurrida'::text,'escurriéndose'::text,'Ella se escurrió junto a un hombre en el callejón con una mochila enorme. Impecable.'::text),
(329990,36666,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... devant un homme dans la ruelle avec un énorme sac à dos. Impeccable.'::text,'s''est faufilée'::text,'a été faufilée'::text,'se faufilant'::text,'Elle s''est faufilée devant un homme dans la ruelle avec un énorme sac à dos. Impeccable.'::text),
(329993,36666,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kocaman sırt çantasıyla ara sokaktaki bir adamın yanından ...! Kusursuz.'::text,'sıkışarak geçti'::text,'sıkıştırılarak geçirildi'::text,'sıkışarak geçen'::text,'Kocaman sırt çantasıyla ara sokaktaki bir adamın yanından sıkışarak geçti! Kusursuz.'::text),
(329994,36666,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy hatalmas hátizsákkal ... el egy férfi mellett a sikátorban. Hibátlan.'::text,'préselődött'::text,'el lett préselve'::text,'préselődve'::text,'Egy hatalmas hátizsákkal préselődött el egy férfi mellett a sikátorban. Hibátlan.'::text),
(329997,36667,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Handykarte ... falsch sein, klar; die Gasse führt direkt zum Platz.'::text,'kann nicht'::text,'muss'::text,'könnte'::text,'Ihre Handykarte kann nicht falsch sein, klar; die Gasse führt direkt zum Platz.'::text),
(330001,36667,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мапа в її телефоні ... помилятися, звісно; провулок веде просто на площу.'::text,'не може'::text,'мусить'::text,'може'::text,'Мапа в її телефоні не може помилятися, звісно; провулок веде просто на площу.'::text),
(330000,36667,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mapa de su móvil ... estar mal, obviamente; el callejón lleva directo a la plaza.'::text,'no puede'::text,'tiene que'::text,'podría'::text,'El mapa de su móvil no puede estar mal, obviamente; el callejón lleva directo a la plaza.'::text),
(329999,36667,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La carte de son téléphone ... se tromper, évidemment ; la ruelle mène droit à la place.'::text,'ne peut pas'::text,'doit'::text,'pourrait'::text,'La carte de son téléphone ne peut pas se tromper, évidemment ; la ruelle mène droit à la place.'::text),
(330002,36667,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefonundaki harita yanlış ..., tabii ki; ara sokak doğrudan meydana çıkıyor.'::text,'olamaz'::text,'olmalı'::text,'olabilir'::text,'Telefonundaki harita yanlış olamaz, tabii ki; ara sokak doğrudan meydana çıkıyor.'::text),
(330003,36667,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A telefonos térképe ..., nyilván; a sikátor egyenesen a térre vezet.'::text,'nem tévedhet'::text,'biztosan téved'::text,'tévedhet'::text,'A telefonos térképe nem tévedhet, nyilván; a sikátor egyenesen a térre vezet.'::text),
(330006,36668,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gasse, ... sie gewählt hat, ist eindeutig breit genug für ein Auto.'::text,'die'::text,'wer'::text,'deren'::text,'Die Gasse, die sie gewählt hat, ist eindeutig breit genug für ein Auto.'::text),
(330010,36668,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Провулок, ... вона обрала, явно достатньо широкий для машини.'::text,'який'::text,'хто'::text,'чий'::text,'Провулок, який вона обрала, явно достатньо широкий для машини.'::text),
(330009,36668,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El callejón ... eligió es claramente lo bastante ancho para un coche.'::text,'que'::text,'quien'::text,'cuyo'::text,'El callejón que eligió es claramente lo bastante ancho para un coche.'::text),
(330008,36668,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La ruelle ... elle a choisie est clairement assez large pour une voiture.'::text,'qu'''::text,'qui'::text,'dont'::text,'La ruelle qu'' elle a choisie est clairement assez large pour une voiture.'::text),
(330011,36668,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... seçtiği ara sokak belli ki bir araba geçecek kadar geniş.'::text,''::text,NULL::text,NULL::text,'Seçtiği ara sokak belli ki bir araba geçecek kadar geniş.'::text),
(330012,36668,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sikátor, ... választott, nyilvánvalóan elég széles egy autónak.'::text,'amelyiket'::text,'aki'::text,'akinek a'::text,'A sikátor, amelyiket választott, nyilvánvalóan elég széles egy autónak.'::text),
(330015,36669,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schrie, die Gasse ... nirgendwohin und sie sei für immer verloren!'::text,'führe'::text,'führt'::text,'werde führen'::text,'Sie schrie, die Gasse führe nirgendwohin und sie sei für immer verloren!'::text),
(330019,36669,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона кричала, що провулок ... в нікуди і вона назавжди заблукала!'::text,'веде'::text,'веде'::text,'поведе'::text,'Вона кричала, що провулок веде в нікуди і вона назавжди заблукала!'::text),
(330018,36669,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Gritó que el callejón no ... a ninguna parte y que estaba perdida para siempre!'::text,'llevaba'::text,'lleva'::text,'llevará'::text,'¡Gritó que el callejón no llevaba a ninguna parte y que estaba perdida para siempre!'::text),
(330017,36669,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a hurlé que la ruelle ne ... nulle part et qu''elle était perdue pour toujours !'::text,'menait'::text,'mène'::text,'mènera'::text,'Elle a hurlé que la ruelle ne menait nulle part et qu''elle était perdue pour toujours !'::text),
(330020,36669,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ara sokağın hiçbir yere ... ve sonsuza dek kaybolduğunu bağırdı!'::text,'çıkmadığını'::text,'çıkmadığını'::text,'çıkmayacağını'::text,'Ara sokağın hiçbir yere çıkmadığını ve sonsuza dek kaybolduğunu bağırdı!'::text),
(330021,36669,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt sikította, hogy a sikátor sehová sem ..., és ő örökre eltévedt!'::text,'vezet'::text,'vezet'::text,'fog vezetni'::text,'Azt sikította, hogy a sikátor sehová sem vezet, és ő örökre eltévedt!'::text),
(330024,36670,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... enge Gassen, und jede Reise war ein Albtraum!'::text,'hasste früher'::text,'würde hassen'::text,'war es gewohnt zu hassen'::text,'Sie hasste früher enge Gassen, und jede Reise war ein Albtraum!'::text),
(330028,36670,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... вузькі провулки, і кожна подорож була кошмаром!'::text,'колись ненавиділа'::text,'ненавиділа б'::text,'звикла ненавидіти'::text,'Вона колись ненавиділа вузькі провулки, і кожна подорож була кошмаром!'::text),
(330027,36670,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Antes ... los callejones estrechos, y cada viaje era una pesadilla!'::text,'odiaba'::text,'odiaría'::text,'estaba acostumbrada a odiar'::text,'¡Antes odiaba los callejones estrechos, y cada viaje era una pesadilla!'::text),
(330026,36670,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, elle ... les ruelles étroites, et chaque voyage était un cauchemar !'::text,'détestait'::text,'détesterait'::text,'avait l''habitude de détester'::text,'Avant, elle détestait les ruelles étroites, et chaque voyage était un cauchemar !'::text),
(330029,36670,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden dar ara sokaklardan ... ve her gezi bir kâbustu!'::text,'nefret ederdi'::text,'nefret edecekti'::text,'nefret etmeye alışkındı'::text,'Eskiden dar ara sokaklardan nefret ederdi ve her gezi bir kâbustu!'::text),
(330030,36670,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a szűk sikátorokat, és minden utazás rémálom volt!'::text,'utálta'::text,'utálná'::text,'hozzá volt szokva utálni'::text,'Régen utálta a szűk sikátorokat, és minden utazás rémálom volt!'::text),
(402933,44771,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... durch das Tulpenfeld, während sich hinter ihr die Flügel der Windmühle drehten.'::text,'lief'::text,'ist gelaufen'::text,'läuft'::text,'Sie lief durch das Tulpenfeld, während sich hinter ihr die Flügel der Windmühle drehten.'::text),
(402937,44771,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... тюльпановим полем, поки за нею оберталися крила вітряка.'::text,'йшла'::text,'пройшла'::text,'йде'::text,'Вона йшла тюльпановим полем, поки за нею оберталися крила вітряка.'::text),
(402936,44771,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... por el campo de tulipanes mientras las aspas del molino giraban detrás de ella.'::text,'Caminaba'::text,'Ha caminado'::text,'Camina'::text,'Caminaba por el campo de tulipanes mientras las aspas del molino giraban detrás de ella.'::text),
(402935,44771,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... dans le champ de tulipes pendant que les ailes du moulin tournaient derrière elle.'::text,'marchait'::text,'a marché'::text,'marche'::text,'Elle marchait dans le champ de tulipes pendant que les ailes du moulin tournaient derrière elle.'::text),
(402938,44771,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkasında yel değirmeninin kanatları dönerken lale tarlasında ...'::text,'yürüyordu'::text,'yürüdü'::text,'yürüyor'::text,'Arkasında yel değirmeninin kanatları dönerken lale tarlasında yürüyordu.'::text),
(402939,44771,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a tulipánmezőn, miközben mögötte forogtak a szélmalom lapátjai.'::text,'Sétált'::text,'Végigsétált'::text,'Sétál'::text,'Sétált a tulipánmezőn, miközben mögötte forogtak a szélmalom lapátjai.'::text),
(402942,44772,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Windmühle ... schon den ganzen Tag ihre Flügel, und ich kann buchstäblich nicht aufhören hinzustarren!'::text,'dreht'::text,'dreht'::text,'dreht'::text,'Diese Windmühle dreht schon den ganzen Tag ihre Flügel, und ich kann buchstäblich nicht aufhören hinzustarren!'::text),
(402946,44772,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей вітряк ... крилами цілий день, і я буквально не можу перестати витріщатися!'::text,'крутить'::text,'крутить'::text,'крутить'::text,'Цей вітряк крутить крилами цілий день, і я буквально не можу перестати витріщатися!'::text),
(402945,44772,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ese molino ... las aspas todo el día y literalmente no puedo dejar de mirarlo!'::text,'ha estado girando'::text,'está girando'::text,'gira'::text,'¡Ese molino ha estado girando las aspas todo el día y literalmente no puedo dejar de mirarlo!'::text),
(402944,44772,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce moulin ... ses ailes depuis toute la journée, et je ne peux littéralement pas arrêter de le fixer !'::text,'tourne'::text,'tourne'::text,'tourne'::text,'Ce moulin tourne ses ailes depuis toute la journée, et je ne peux littéralement pas arrêter de le fixer !'::text),
(402947,44772,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yel değirmeni bütün gün kanatlarını ... ve ben resmen bakmadan duramıyorum!'::text,'döndürüyor'::text,'döndürüyor'::text,'döndürür'::text,'O yel değirmeni bütün gün kanatlarını döndürüyor ve ben resmen bakmadan duramıyorum!'::text),
(402948,44772,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a szélmalom egész nap ... a lapátjait, és szó szerint nem bírom abbahagyni a bámulást!'::text,'forgatja'::text,'forgatja'::text,'forgatja'::text,'Az a szélmalom egész nap forgatja a lapátjait, és szó szerint nem bírom abbahagyni a bámulást!'::text),
(402951,44773,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Windmühle ... vor über 300 Jahren gebaut, und sie hat absolut alles überlebt!'::text,'wurde'::text,'ist'::text,'baute'::text,'Diese Windmühle wurde vor über 300 Jahren gebaut, und sie hat absolut alles überlebt!'::text),
(402955,44773,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей вітряк ... понад 300 років тому, і він пережив абсолютно все!'::text,'був збудований'::text,'збудований'::text,'збудував'::text,'Цей вітряк був збудований понад 300 років тому, і він пережив абсолютно все!'::text),
(402954,44773,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este molino ... hace más de 300 años y ha sobrevivido a absolutamente todo!'::text,'fue construido'::text,'está construido'::text,'construyó'::text,'¡Este molino fue construido hace más de 300 años y ha sobrevivido a absolutamente todo!'::text),
(402953,44773,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce moulin ... il y a plus de 300 ans, et il a absolument tout traversé !'::text,'a été construit'::text,'est construit'::text,'a construit'::text,'Ce moulin a été construit il y a plus de 300 ans, et il a absolument tout traversé !'::text),
(402956,44773,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yel değirmeni 300 yıldan uzun süre önce ... ve kesinlikle her şeyi atlattı!'::text,'inşa edildi'::text,'inşa edilir'::text,'inşa etti'::text,'Bu yel değirmeni 300 yıldan uzun süre önce inşa edildi ve kesinlikle her şeyi atlattı!'::text),
(402957,44773,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a szélmalom több mint 300 éve ..., és abszolút mindent túlélt!'::text,'épült'::text,'épül'::text,'épített'::text,'Ez a szélmalom több mint 300 éve épült, és abszolút mindent túlélt!'::text),
(402960,44774,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, ich hab gehört, die Flügel dieser Windmühle ... vom Wind gedreht, nicht von einem Motor.'::text,'werden'::text,'drehen'::text,'drehen gerade'::text,'Okay, ich hab gehört, die Flügel dieser Windmühle werden vom Wind gedreht, nicht von einem Motor.'::text),
(402964,44774,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що крила того вітряка ... вітром, а не мотором.'::text,'обертаються'::text,'обертають'::text,'обертаються'::text,'Коротше, я чула, що крила того вітряка обертаються вітром, а не мотором.'::text),
(402963,44774,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, he oído que las aspas de ese molino ... por el viento, no por un motor.'::text,'son movidas'::text,'mueven'::text,'están moviendo'::text,'Vale, he oído que las aspas de ese molino son movidas por el viento, no por un motor.'::text),
(402962,44774,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu dire que les ailes de ce moulin ... par le vent, pas par un moteur.'::text,'sont actionnées'::text,'actionnent'::text,'sont en train d''actionner'::text,'Bon, j''ai entendu dire que les ailes de ce moulin sont actionnées par le vent, pas par un moteur.'::text),
(402965,44774,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duydum ki o yel değirmeninin kanatları motorla değil, rüzgârla ...'::text,'döndürülüyormuş'::text,'döndürüyormuş'::text,'dönüyormuş'::text,'Tamam, duydum ki o yel değirmeninin kanatları motorla değil, rüzgârla döndürülüyormuş.'::text),
(402966,44774,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt hallottam, hogy annak a szélmalomnak a lapátjait a szél ..., nem motor.'::text,'hajtja'::text,'hajtják'::text,'hajtja'::text,'Szóval azt hallottam, hogy annak a szélmalomnak a lapátjait a szél hajtja, nem motor.'::text),
(402969,44775,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, die Windmühle ... echt alt sein, aber er ist sich nicht sicher.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Hör zu, er hat mir gesagt, die Windmühle könnte echt alt sein, aber er ist sich nicht sicher.'::text),
(402973,44775,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він мені сказав, що той вітряк ... бути дуже старим, але він не впевнений.'::text,'може'::text,'мусить'::text,'не може'::text,'Слухай, він мені сказав, що той вітряк може бути дуже старим, але він не впевнений.'::text),
(402972,44775,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que ese molino ... ser muy antiguo, pero no está seguro.'::text,'podría'::text,'debe de'::text,'no puede'::text,'Escucha, me dijo que ese molino podría ser muy antiguo, pero no está seguro.'::text),
(402971,44775,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que ce moulin ... être très vieux, mais il n''est pas sûr.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'Écoute, il m''a dit que ce moulin pourrait être très vieux, mais il n''est pas sûr.'::text),
(402974,44775,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana o yel değirmeninin çok eski ... söyledi ama emin değilmiş.'::text,'olabileceğini'::text,'olması gerektiğini'::text,'olamayacağını'::text,'Dinle, bana o yel değirmeninin çok eski olabileceğini söyledi ama emin değilmiş.'::text),
(402975,44775,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy az a szélmalom ... nagyon régi, de nem biztos benne.'::text,'talán'::text,'biztosan'::text,'nem lehet'::text,'Figyelj, azt mondta, hogy az a szélmalom talán nagyon régi, de nem biztos benne.'::text),
(402987,44777,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie meinte, sie ... am nächsten Tag wieder zur Windmühle radeln, weil''s irgendwie magisch war.'::text,'würde'::text,'werde'::text,'radle'::text,'Sie meinte, sie würde am nächsten Tag wieder zur Windmühle radeln, weil''s irgendwie magisch war.'::text),
(402991,44777,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що наступного дня знову ... до вітряка на велику, бо це було якось магічно.'::text,'поїде'::text,'поїде'::text,'їздить'::text,'Вона сказала, що наступного дня знову поїде до вітряка на велику, бо це було якось магічно.'::text),
(402990,44777,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que al día siguiente ... otra vez en bici hasta el molino, porque era como mágico.'::text,'iría'::text,'irá'::text,'va'::text,'Dijo que al día siguiente iría otra vez en bici hasta el molino, porque era como mágico.'::text),
(402989,44777,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... à vélo jusqu''au moulin le lendemain, parce que c''était un peu magique.'::text,'retournerait'::text,'retournera'::text,'retourne'::text,'Elle a dit qu''elle retournerait à vélo jusqu''au moulin le lendemain, parce que c''était un peu magique.'::text),
(402992,44777,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ertesi gün yine bisikletle yel değirmenine ... söyledi, çünkü baya büyülüymüş.'::text,'gideceğini'::text,'gideceğini'::text,'gittiğini'::text,'Ertesi gün yine bisikletle yel değirmenine gideceğini söyledi, çünkü baya büyülüymüş.'::text),
(402993,44777,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy másnap megint ... a szélmalomhoz, mert elég varázslatos volt.'::text,'elbiciklizik'::text,'el fog biciklizni'::text,'biciklizik'::text,'Azt mondta, hogy másnap megint elbiciklizik a szélmalomhoz, mert elég varázslatos volt.'::text),
(402996,44778,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Windmühle ... einer Mehlfirma mit 40 Beschäftigten.'::text,'gehörte früher'::text,'würde gehören'::text,'war es gewohnt zu gehören'::text,'Diese Windmühle gehörte früher einer Mehlfirma mit 40 Beschäftigten.'::text),
(403000,44778,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей вітряк ... борошняній компанії з 40 працівниками.'::text,'колись належав'::text,'належав би'::text,'звик належати'::text,'Цей вітряк колись належав борошняній компанії з 40 працівниками.'::text),
(402999,44778,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este molino ... a una empresa de harina con una plantilla de 40 personas.'::text,'pertenecía antes'::text,'pertenecería'::text,'estaba acostumbrado a pertenecer'::text,'Este molino pertenecía antes a una empresa de harina con una plantilla de 40 personas.'::text),
(402998,44778,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce moulin ... autrefois à une minoterie employant 40 personnes.'::text,'appartenait'::text,'appartiendrait'::text,'était habitué à appartenir'::text,'Ce moulin appartenait autrefois à une minoterie employant 40 personnes.'::text),
(403001,44778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yel değirmeni eskiden 40 çalışanı olan bir un şirketine ...'::text,'aitti'::text,'ait olurdu'::text,'ait olmaya alışkındı'::text,'Bu yel değirmeni eskiden 40 çalışanı olan bir un şirketine aitti.'::text),
(403002,44778,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a szélmalom régen egy 40 fős lisztgyártó cégé ...'::text,'volt'::text,'lenne'::text,'volt hozzászokva, hogy legyen'::text,'Ez a szélmalom régen egy 40 fős lisztgyártó cégé volt.'::text),
(403005,44779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gern in der Nähe der Windmühle, weil Spazierengehen in der Nähe der Windmühle Spaß macht.'::text,'spaziert'::text,'spaziert'::text,'spaziert'::text,'Sie spaziert gern in der Nähe der Windmühle, weil Spazierengehen in der Nähe der Windmühle Spaß macht.'::text),
(403009,44779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй подобається ... біля вітряка, бо гуляти біля вітряка весело.'::text,'гуляти'::text,'гуляти'::text,'гуляти'::text,'Їй подобається гуляти біля вітряка, бо гуляти біля вітряка весело.'::text),
(403008,44779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gusta ... cerca del molino, porque pasear cerca del molino es divertido.'::text,'pasear'::text,'pasear'::text,'pasear'::text,'Le gusta pasear cerca del molino, porque pasear cerca del molino es divertido.'::text),
(403007,44779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aime ... près du moulin, parce que se promener près du moulin, c''est amusant.'::text,'se promener'::text,'se promener'::text,'se promener'::text,'Elle aime se promener près du moulin, parce que se promener près du moulin, c''est amusant.'::text),
(403010,44779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yel değirmeninin yakınında ... seviyor, çünkü yel değirmeninin yakınında yürümek eğlenceli.'::text,'yürümeyi'::text,'yürümeyi'::text,'yürümeyi'::text,'Yel değirmeninin yakınında yürümeyi seviyor, çünkü yel değirmeninin yakınında yürümek eğlenceli.'::text),
(403011,44779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szeret ... a szélmalom közelében, mert a szélmalom közelében sétálni jó móka.'::text,'sétálni'::text,'sétálni'::text,'sétálni'::text,'Szeret sétálni a szélmalom közelében, mert a szélmalom közelében sétálni jó móka.'::text),
(403023,44781,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... sich die Flügel der Windmühle langsam im Wind.'::text,'drehen'::text,'drehen'::text,'haben gedreht'::text,'Gerade drehen sich die Flügel der Windmühle langsam im Wind.'::text),
(403027,44781,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз крила вітряка повільно ... на вітрі.'::text,'обертаються'::text,'обертаються'::text,'оберталися'::text,'Просто зараз крила вітряка повільно обертаються на вітрі.'::text),
(403026,44781,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, las aspas del molino ... despacio con el viento.'::text,'están girando'::text,'giran'::text,'han girado'::text,'Ahora mismo, las aspas del molino están girando despacio con el viento.'::text),
(403025,44781,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, les ailes du moulin ... lentement dans le vent.'::text,'tournent'::text,'tournent'::text,'ont tourné'::text,'En ce moment, les ailes du moulin tournent lentement dans le vent.'::text),
(403028,44781,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda yel değirmeninin kanatları rüzgârda yavaşça ...'::text,'dönüyor'::text,'döner'::text,'döndü'::text,'Şu anda yel değirmeninin kanatları rüzgârda yavaşça dönüyor.'::text),
(403029,44781,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a szélmalom lapátjai lassan ... a szélben.'::text,'forognak'::text,'forognak'::text,'forogtak'::text,'Épp most a szélmalom lapátjai lassan forognak a szélben.'::text),
(343947,38217,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie das Baby im Arm ..., war es in ihren Armen, also war es nicht im Bettchen.'::text,'wiegten'::text,'wiegten'::text,'gewiegt haben'::text,'Während sie das Baby im Arm wiegten, war es in ihren Armen, also war es nicht im Bettchen.'::text),
(343951,38217,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вони ... малятко на руках, воно було в них на руках, тож не було в ліжечку.'::text,'колисали'::text,'поколисали'::text,'поколисали'::text,'Поки вони колисали малятко на руках, воно було в них на руках, тож не було в ліжечку.'::text),
(343950,38217,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... a la bebé en brazos, estaba en sus brazos, así que no estaba en la cuna.'::text,'mecían'::text,'mecieron'::text,'han mecido'::text,'Mientras mecían a la bebé en brazos, estaba en sus brazos, así que no estaba en la cuna.'::text),
(343949,38217,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''ils ... le bébé, il était dans leurs bras, donc il n''était pas dans le berceau.'::text,'berçaient'::text,'ont bercé'::text,'ont bercé'::text,'Pendant qu''ils berçaient le bébé, il était dans leurs bras, donc il n''était pas dans le berceau.'::text),
(343952,38217,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bebeği kucaklarında ... bebek kollarındaydı, yani beşikte değildi.'::text,'sallarken'::text,'salladılar'::text,'sallamışlar'::text,'Bebeği kucaklarında sallarken bebek kollarındaydı, yani beşikte değildi.'::text),
(343953,38217,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ... a babát, a karjukban volt, tehát nem volt a kiságyban.'::text,'ringatták'::text,'megringatták'::text,'megringatták'::text,'Miközben ringatták a babát, a karjukban volt, tehát nem volt a kiságyban.'::text),
(343956,38218,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Eltern ... das Neugeborene minutenlang im Arm und legten es anschließend ins Bettchen.'::text,'wiegten'::text,'wiegten gerade'::text,'haben gewiegt'::text,'Die Eltern wiegten das Neugeborene minutenlang im Arm und legten es anschließend ins Bettchen.'::text),
(343960,38218,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Батьки кілька хвилин ... новонароджену, а потім поклали її в ліжечко.'::text,'колисали'::text,'колисали'::text,'поколисали'::text,'Батьки кілька хвилин колисали новонароджену, а потім поклали її в ліжечко.'::text),
(343959,38218,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los padres ... a la recién nacida durante minutos y a continuación la colocaron en la cuna.'::text,'mecieron'::text,'estaban meciendo'::text,'han mecido'::text,'Los padres mecieron a la recién nacida durante minutos y a continuación la colocaron en la cuna.'::text),
(343958,38218,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les parents ... le nouveau-né pendant plusieurs minutes, puis l''ont déposé dans le berceau.'::text,'ont bercé'::text,'berçaient'::text,'ont bercé'::text,'Les parents ont bercé le nouveau-né pendant plusieurs minutes, puis l''ont déposé dans le berceau.'::text),
(343961,38218,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebeveynler yenidoğanı dakikalarca kucaklarında ... ve ardından onu beşiğe yatırdılar.'::text,'salladılar'::text,'sallıyorlardı'::text,'sallamışlar'::text,'Ebeveynler yenidoğanı dakikalarca kucaklarında salladılar ve ardından onu beşiğe yatırdılar.'::text),
(343962,38218,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szülők percekig ... az újszülöttet, majd ezt követően a kiságyba fektették.'::text,'ringatták'::text,'ringatták'::text,'megringatták'::text,'A szülők percekig ringatták az újszülöttet, majd ezt követően a kiságyba fektették.'::text),
(343965,38219,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie haben das Baby in einer Stunde buchstäblich fünfmal ...!'::text,'gewiegt'::text,'gewiegt'::text,'gewiegt'::text,'Sie haben das Baby in einer Stunde buchstäblich fünfmal gewiegt!'::text),
(343969,38219,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... те малятко буквально п''ять разів за годину!'::text,'поколисали'::text,'колисали'::text,'поколисали'::text,'Вони поколисали те малятко буквально п''ять разів за годину!'::text),
(343968,38219,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... a esa bebé literalmente cinco veces en una hora!'::text,'Han mecido'::text,'Han estado meciendo'::text,'Mecieron'::text,'¡Han mecido a esa bebé literalmente cinco veces en una hora!'::text),
(343967,38219,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... ce bébé littéralement cinq fois en une heure !'::text,'ont bercé'::text,'bercent depuis'::text,'ont bercé'::text,'Ils ont bercé ce bébé littéralement cinq fois en une heure !'::text),
(343970,38219,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bebeği bir saatte resmen beş kez ...!'::text,'salladılar'::text,'sallayıp durdular'::text,'salladılar'::text,'O bebeği bir saatte resmen beş kez salladılar!'::text),
(343971,38219,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy óra alatt szó szerint ötször ... azt a babát!'::text,'ringatták meg'::text,'ringatták'::text,'ringatták'::text,'Egy óra alatt szó szerint ötször ringatták meg azt a babát!'::text),
(343974,38220,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor die Krankenschwester kam, ... sie das Baby zum ersten Mal im Arm gewiegt! Absolut unvergesslich!'::text,'hatten'::text,'haben'::text,'wiegen'::text,'Bevor die Krankenschwester kam, hatten sie das Baby zum ersten Mal im Arm gewiegt! Absolut unvergesslich!'::text),
(343978,38220,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ще до приходу медсестри вони ... малятко вперше! Абсолютно незабутньо!'::text,'поколисали'::text,'поколисали'::text,'колишуть'::text,'Ще до приходу медсестри вони поколисали малятко вперше! Абсолютно незабутньо!'::text),
(343977,38220,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Antes de que llegara la enfermera, ya ... a la bebé por primera vez! ¡Absolutamente inolvidable!'::text,'habían mecido'::text,'han mecido'::text,'mecen'::text,'¡Antes de que llegara la enfermera, ya habían mecido a la bebé por primera vez! ¡Absolutamente inolvidable!'::text),
(343976,38220,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant l''arrivée de l''infirmière, ils ... le bébé pour la première fois ! Absolument inoubliable !'::text,'avaient bercé'::text,'ont bercé'::text,'bercent'::text,'Avant l''arrivée de l''infirmière, ils avaient bercé le bébé pour la première fois ! Absolument inoubliable !'::text),
(343979,38220,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hemşire gelmeden önce bebeği ilk kez ...! Kesinlikle unutulmaz!'::text,'sallamışlardı'::text,'salladılar'::text,'sallıyorlar'::text,'Hemşire gelmeden önce bebeği ilk kez sallamışlardı! Kesinlikle unutulmaz!'::text),
(343980,38220,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a nővér megérkezett, először ... a babát! Abszolút felejthetetlen!'::text,'ringatták'::text,'ringatták'::text,'ringatják'::text,'Mielőtt a nővér megérkezett, először ringatták a babát! Abszolút felejthetetlen!'::text),
(343983,38221,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um drei Uhr nachts ... sie ein schreiendes Baby! Das Ende des Schlafs für immer!'::text,'wiegen'::text,'wiegen'::text,'wiegen'::text,'Morgen um drei Uhr nachts wiegen sie ein schreiendes Baby! Das Ende des Schlafs für immer!'::text),
(343987,38221,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о третій ночі вони ... малюка, що плаче! Кінець сну назавжди!'::text,'колисатимуть'::text,'поколишуть'::text,'колишуть'::text,'Завтра о третій ночі вони колисатимуть малюка, що плаче! Кінець сну назавжди!'::text),
(343986,38221,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a las 3 de la madrugada ... a un bebé llorando! ¡Adiós al sueño para siempre!'::text,'estarán meciendo'::text,'mecerán'::text,'mecen'::text,'¡Mañana a las 3 de la madrugada estarán meciendo a un bebé llorando! ¡Adiós al sueño para siempre!'::text),
(343985,38221,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à 3 h du matin, ils ... un bébé qui pleure ! La fin du sommeil pour toujours !'::text,'seront en train de bercer'::text,'berceront'::text,'bercent'::text,'Demain à 3 h du matin, ils seront en train de bercer un bébé qui pleure ! La fin du sommeil pour toujours !'::text),
(343988,38221,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın gece saat 3''te ağlayan bir bebeği ...! Uykuya sonsuza dek elveda!'::text,'sallıyor olacaklar'::text,'sallayacaklar'::text,'sallıyorlar'::text,'Yarın gece saat 3''te ağlayan bir bebeği sallıyor olacaklar! Uykuya sonsuza dek elveda!'::text),
(343989,38221,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap hajnali háromkor egy síró babát ...! Örökre vége az alvásnak!'::text,'fognak ringatni'::text,'ringatnak meg'::text,'ringatnak'::text,'Holnap hajnali háromkor egy síró babát fognak ringatni! Örökre vége az alvásnak!'::text),
(343992,38222,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er schwört, dass er nachts das Baby ..., damit sie schlafen kann.'::text,'wiegen wird'::text,'wiegen wird'::text,'wiegt'::text,'Bestie, er schwört, dass er nachts das Baby wiegen wird, damit sie schlafen kann.'::text),
(343996,38222,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він клянеться, що вночі ... малятко, щоб вона могла поспати.'::text,'колисатиме'::text,'колисатиме'::text,'колише'::text,'Подруго, він клянеться, що вночі колисатиме малятко, щоб вона могла поспати.'::text),
(343995,38222,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, él jura que por la noche ... a la bebé para que ella pueda dormir.'::text,'mecerá'::text,'estará meciendo'::text,'mece'::text,'Amiga, él jura que por la noche mecerá a la bebé para que ella pueda dormir.'::text),
(343994,38222,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il jure qu''il ... le bébé la nuit pour qu''elle puisse dormir.'::text,'bercera'::text,'sera en train de bercer'::text,'berce'::text,'Ma belle, il jure qu''il bercera le bébé la nuit pour qu''elle puisse dormir.'::text),
(343997,38222,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, geceleri o uyuyabilsin diye bebeği ... yemin ediyor.'::text,'sallayacağına'::text,'sallıyor olacağına'::text,'salladığına'::text,'Kanka, geceleri o uyuyabilsin diye bebeği sallayacağına yemin ediyor.'::text),
(343998,38222,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, esküszik, hogy éjjel ő ... a babát, hogy aludni tudjon.'::text,'ringatja'::text,'fogja ringatni'::text,'ringatja'::text,'Csajszi, esküszik, hogy éjjel ő ringatja a babát, hogy aludni tudjon.'::text),
(344001,38223,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Elternteil ein Neugeborenes sanft ..., schläft es meistens ein.'::text,'wiegt'::text,'wiegte'::text,'wiegen wird'::text,'Wenn ein Elternteil ein Neugeborenes sanft wiegt, schläft es meistens ein.'::text),
(344005,38223,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо батько чи мати ніжно ... новонароджене, воно зазвичай засинає.'::text,'колише'::text,'колисав'::text,'колисатиме'::text,'Якщо батько чи мати ніжно колише новонароджене, воно зазвичай засинає.'::text),
(344004,38223,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un padre o una madre ... con suavidad a un recién nacido, normalmente se duerme.'::text,'mece'::text,'meció'::text,'mecerá'::text,'Si un padre o una madre mece con suavidad a un recién nacido, normalmente se duerme.'::text),
(344003,38223,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand un parent ... doucement un nouveau-né, il s''endort généralement.'::text,'berce'::text,'berçait'::text,'bercera'::text,'Quand un parent berce doucement un nouveau-né, il s''endort généralement.'::text),
(344006,38223,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir ebeveyn yenidoğanı nazikçe ..., bebek genellikle uykuya dalar.'::text,'sallarsa'::text,'salladıysa'::text,'sallayacaksa'::text,'Bir ebeveyn yenidoğanı nazikçe sallarsa, bebek genellikle uykuya dalar.'::text),
(344007,38223,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy szülő gyengéden ... egy újszülöttet, az általában elalszik.'::text,'ringat'::text,'ringatott'::text,'ringatni fog'::text,'Ha egy szülő gyengéden ringat egy újszülöttet, az általában elalszik.'::text),
(344019,38225,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Eltern können nicht aufhören, ihr Neugeborenes im Arm zu ...'::text,'wiegen'::text,'wiegen'::text,'wiegen'::text,'Die Eltern können nicht aufhören, ihr Neugeborenes im Arm zu wiegen.'::text),
(344023,38225,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Батьки не можуть перестати ... свою новонароджену на руках.'::text,'колисати'::text,'колисати'::text,'колисати'::text,'Батьки не можуть перестати колисати свою новонароджену на руках.'::text),
(344022,38225,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los padres no pueden dejar de ... a su recién nacida en brazos.'::text,'mecer'::text,'mecer'::text,'mecer'::text,'Los padres no pueden dejar de mecer a su recién nacida en brazos.'::text),
(344021,38225,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les parents n''arrivent pas à arrêter de ... leur nouveau-né dans leurs bras.'::text,'bercer'::text,'bercer'::text,'bercer'::text,'Les parents n''arrivent pas à arrêter de bercer leur nouveau-né dans leurs bras.'::text),
(344024,38225,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anne baba yenidoğanlarını kucaklarında ... duramıyor.'::text,'sallamadan'::text,'sallamadan'::text,'sallamadan'::text,'Anne baba yenidoğanlarını kucaklarında sallamadan duramıyor.'::text),
(344025,38225,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szülők nem tudják abbahagyni, hogy a karjukban ... az újszülöttjüket.'::text,'ringassák'::text,'ringassák'::text,'ringassák'::text,'A szülők nem tudják abbahagyni, hogy a karjukban ringassák az újszülöttjüket.'::text),
(344028,38226,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mutter und Vater ... in diesem Moment ihr Neugeborenes.'::text,'wiegen'::text,'wiegen'::text,'haben gewiegt'::text,'Mutter und Vater wiegen in diesem Moment ihr Neugeborenes.'::text),
(344032,38226,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мама й тато в цю мить ... свою новонароджену.'::text,'колишуть'::text,'колишуть'::text,'поколисали'::text,'Мама й тато в цю мить колишуть свою новонароджену.'::text),
(344031,38226,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La madre y el padre ... a su recién nacida en este momento.'::text,'están meciendo'::text,'mecen'::text,'han mecido'::text,'La madre y el padre están meciendo a su recién nacida en este momento.'::text),
(344030,38226,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mère et le père ... leur nouveau-né en ce moment.'::text,'bercent'::text,'bercent'::text,'ont bercé'::text,'La mère et le père bercent leur nouveau-né en ce moment.'::text),
(344033,38226,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anne ve baba şu anda yenidoğanlarını ...'::text,'sallıyor'::text,'sallar'::text,'salladı'::text,'Anne ve baba şu anda yenidoğanlarını sallıyor.'::text),
(344034,38226,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az anya és az apa ebben a pillanatban ... az újszülöttjüket.'::text,'ringatják'::text,'ringatják'::text,'megringatták'::text,'Az anya és az apa ebben a pillanatban ringatják az újszülöttjüket.'::text),
(354099,39345,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang wirst du jeden Flamingo in dem Notizbuch ..., ganz ehrlich.'::text,'gezählt haben'::text,'zählen'::text,'zählst'::text,'Bis Sonnenuntergang wirst du jeden Flamingo in dem Notizbuch gezählt haben, ganz ehrlich.'::text),
(354103,39345,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця ти ... кожного фламінго в тому блокноті, не брехатиму.'::text,'вже порахуєш'::text,'порахуєш'::text,'рахуєш'::text,'До заходу сонця ти вже порахуєш кожного фламінго в тому блокноті, не брехатиму.'::text),
(354102,39345,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer ya ... todos los flamencos de esa libreta, no te voy a mentir.'::text,'habrás contado'::text,'contarás'::text,'estás contando'::text,'Para el atardecer ya habrás contado todos los flamencos de esa libreta, no te voy a mentir.'::text),
(354101,39345,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, tu ... chaque flamant de ce carnet, j''te mens pas.'::text,'auras compté'::text,'compteras'::text,'comptes'::text,'D''ici le coucher du soleil, tu auras compté chaque flamant de ce carnet, j''te mens pas.'::text),
(354104,39345,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar o defterdeki her flamingoyu ..., yalan yok.'::text,'saymış olacaksın'::text,'sayacaksın'::text,'sayıyorsun'::text,'Gün batımına kadar o defterdeki her flamingoyu saymış olacaksın, yalan yok.'::text),
(354105,39345,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementére már ... az összes flamingót abban a füzetben, nem hazudok.'::text,'megszámolod'::text,'meg fogod számolni'::text,'számolod'::text,'Naplementére már megszámolod az összes flamingót abban a füzetben, nem hazudok.'::text),
(354108,39346,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um sechs Uhr ... die Gruppe die Flamingos schon seit drei Stunden.'::text,'beobachtet'::text,'beobachtet'::text,'beobachtet'::text,'Um sechs Uhr beobachtet die Gruppe die Flamingos schon seit drei Stunden.'::text),
(354112,39346,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О шостій група вже три години ... фламінго.'::text,'спостерігатиме за'::text,'спостерігатиме за'::text,'спостерігає за'::text,'О шостій група вже три години спостерігатиме за фламінго.'::text),
(354111,39346,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A las seis, el grupo ... tres horas observando a los flamencos.'::text,'llevará'::text,'estará'::text,'lleva'::text,'A las seis, el grupo llevará tres horas observando a los flamencos.'::text),
(354110,39346,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À six heures, ça fera trois heures que le groupe ... les flamants.'::text,'observe'::text,'observe'::text,'observe'::text,'À six heures, ça fera trois heures que le groupe observe les flamants.'::text),
(354113,39346,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat altıda grup üç saattir flamingoları ... olacak.'::text,'izliyor'::text,'izliyor'::text,'izliyor'::text,'Saat altıda grup üç saattir flamingoları izliyor olacak.'::text),
(354114,39346,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hat órára a csoport már három órája ... a flamingókat.'::text,'figyeli'::text,'figyeli'::text,'figyeli'::text,'Hat órára a csoport már három órája figyeli a flamingókat.'::text),
(354126,39348,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wären sie später gekommen, ... sie die Flamingos jetzt nicht in der Luft sehen.'::text,'würden'::text,'hätten'::text,'werden'::text,'Wären sie später gekommen, würden sie die Flamingos jetzt nicht in der Luft sehen.'::text),
(354130,39348,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони прийшли пізніше, вони ... фламінго в повітрі просто зараз.'::text,'не спостерігали б за'::text,'не спостерігали б за'::text,'не спостерігатимуть за'::text,'Якби вони прийшли пізніше, вони не спостерігали б за фламінго в повітрі просто зараз.'::text),
(354129,39348,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubieran llegado más tarde, ahora no ... a los flamencos en el aire.'::text,'estarían viendo'::text,'habrían visto'::text,'verán'::text,'Si hubieran llegado más tarde, ahora no estarían viendo a los flamencos en el aire.'::text),
(354128,39348,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils étaient arrivés plus tard, ils ne ... pas les flamants en vol en ce moment.'::text,'regarderaient'::text,'auraient regardé'::text,'regarderont'::text,'S''ils étaient arrivés plus tard, ils ne regarderaient pas les flamants en vol en ce moment.'::text),
(354131,39348,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha geç gelselerdi, şu anda flamingoları havada ...'::text,'izlemiyor olurlardı'::text,'izlemezlerdi'::text,'izlemeyecekler'::text,'Daha geç gelselerdi, şu anda flamingoları havada izlemiyor olurlardı.'::text),
(354132,39348,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha később értek volna oda, most nem ... a flamingókat a levegőben.'::text,'néznék'::text,'nézték volna'::text,'fogják nézni'::text,'Ha később értek volna oda, most nem néznék a flamingókat a levegőben.'::text),
(354135,39349,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Art, der Flamingo, ist dafür bekannt, seine rosa Farbe aus der Nahrung zu ...'::text,'beziehen'::text,'beziehend'::text,'bezogen werden'::text,'Diese Art, der Flamingo, ist dafür bekannt, seine rosa Farbe aus der Nahrung zu beziehen.'::text),
(354139,39349,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відомо, що цей вид, фламінго, ... свій рожевий колір з їжі.'::text,'отримує'::text,'отримуючи'::text,'отримується'::text,'Відомо, що цей вид, фламінго, отримує свій рожевий колір з їжі.'::text),
(354138,39349,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se sabe que esta especie, el flamenco, ... su color rosa de su alimento.'::text,'obtiene'::text,'obteniendo'::text,'es obtenido'::text,'Se sabe que esta especie, el flamenco, obtiene su color rosa de su alimento.'::text),
(354137,39349,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette espèce, le flamant, est connue pour ... sa couleur rose de son alimentation.'::text,'tirer'::text,'tirant'::text,'être tirée'::text,'Cette espèce, le flamant, est connue pour tirer sa couleur rose de son alimentation.'::text),
(354140,39349,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu türün, yani flamingonun, pembe rengini besinlerinden ... bilinir.'::text,'aldığı'::text,'alması'::text,'alındığı'::text,'Bu türün, yani flamingonun, pembe rengini besinlerinden aldığı bilinir.'::text),
(354141,39349,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erről a fajról, a flamingóról, köztudott, hogy rózsaszín színét a táplálékából ...'::text,'nyeri'::text,'nyerve'::text,'nyeretik'::text,'Erről a fajról, a flamingóról, köztudott, hogy rózsaszín színét a táplálékából nyeri.'::text),
(354144,39350,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der alte Mann bestritt, die Flamingos mit seinem Geschrei ...! Totale Katastrophe!'::text,'verscheucht zu haben'::text,'zu verscheuchen'::text,'verscheuchte'::text,'Der alte Mann bestritt, die Flamingos mit seinem Geschrei verscheucht zu haben! Totale Katastrophe!'::text),
(354148,39350,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старий заперечив, що ... фламінго своїм криком! Суцільна катастрофа!'::text,'сполохав'::text,'сполохати'::text,'сполохав'::text,'Старий заперечив, що сполохав фламінго своїм криком! Суцільна катастрофа!'::text),
(354147,39350,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El anciano negó ... a los flamencos con sus gritos! ¡Un desastre total!'::text,'haber espantado'::text,'espantar'::text,'espantó'::text,'¡El anciano negó haber espantado a los flamencos con sus gritos! ¡Un desastre total!'::text),
(354146,39350,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vieil homme a nié ... les flamants avec ses cris ! Un désastre absolu !'::text,'avoir fait fuir'::text,'faire fuir'::text,'a fait fuir'::text,'Le vieil homme a nié avoir fait fuir les flamants avec ses cris ! Un désastre absolu !'::text),
(354149,39350,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı adam bağırarak flamingoları ... inkâr etti! Tam bir felaket!'::text,'kaçırdığını'::text,'kaçırmayı'::text,'kaçırdı'::text,'Yaşlı adam bağırarak flamingoları kaçırdığını inkâr etti! Tam bir felaket!'::text),
(354150,39350,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idős férfi tagadta, hogy a kiabálásával ... a flamingókat! Teljes katasztrófa!'::text,'elriasztotta'::text,'elriasztani'::text,'elriasztotta'::text,'Az idős férfi tagadta, hogy a kiabálásával elriasztotta a flamingókat! Teljes katasztrófa!'::text),
(354153,39351,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wir ... eine bessere Kamera mitbringen sollen! Die Flamingos sind für immer weg!'::text,'hätten'::text,'müssen'::text,'sollten'::text,'Wir hätten eine bessere Kamera mitbringen sollen! Die Flamingos sind für immer weg!'::text),
(354157,39351,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Нам ... взяти кращу камеру! Фламінго зникли назавжди!'::text,'треба було'::text,'мусили'::text,'варто'::text,'Нам треба було взяти кращу камеру! Фламінго зникли назавжди!'::text),
(354156,39351,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... traído una cámara mejor! ¡Los flamencos se han ido para siempre!'::text,'Deberíamos haber'::text,'Debemos de haber'::text,'Deberíamos'::text,'¡Deberíamos haber traído una cámara mejor! ¡Los flamencos se han ido para siempre!'::text),
(354155,39351,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On ... apporter un meilleur appareil photo ! Les flamants sont partis pour toujours !'::text,'aurait dû'::text,'a dû'::text,'devrait'::text,'On aurait dû apporter un meilleur appareil photo ! Les flamants sont partis pour toujours !'::text),
(354158,39351,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha iyi bir fotoğraf makinesi ...! Flamingolar sonsuza dek gitti!'::text,'getirmeliydik'::text,'getirmiş olmalıyız'::text,'getirmeliyiz'::text,'Daha iyi bir fotoğraf makinesi getirmeliydik! Flamingolar sonsuza dek gitti!'::text),
(354159,39351,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jobb fényképezőgépet ... volna hoznunk! A flamingók örökre eltűntek!'::text,'kellett'::text,'kellett'::text,'kellene'::text,'Jobb fényképezőgépet kellett volna hoznunk! A flamingók örökre eltűntek!'::text),
(354162,39352,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie ... ich so viele Flamingos auf einmal abheben sehen! Absolut unvergesslich!'::text,'habe'::text,'habe'::text,'habe'::text,'Nie habe ich so viele Flamingos auf einmal abheben sehen! Absolut unvergesslich!'::text),
(354166,39352,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ... стільки фламінго, що злітають одночасно! Абсолютно незабутньо!'::text,'я не бачив'::text,'я не бачив'::text,'я не бачив'::text,'Ніколи я не бачив стільки фламінго, що злітають одночасно! Абсолютно незабутньо!'::text),
(354165,39352,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca ... despegar tantos flamencos a la vez! ¡Absolutamente inolvidable!'::text,'he visto'::text,'he visto'::text,'vi'::text,'¡Nunca he visto despegar tantos flamencos a la vez! ¡Absolutamente inolvidable!'::text),
(354164,39352,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... autant de flamants s''envoler d''un coup ! Absolument inoubliable !'::text,'je n''ai vu'::text,'j''ai vu'::text,'je ne vis'::text,'Jamais je n''ai vu autant de flamants s''envoler d''un coup ! Absolument inoubliable !'::text),
(354167,39352,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç bu kadar çok flamingonun aynı anda havalandığını ...! Kesinlikle unutulmaz!'::text,'görmedim'::text,'görmedim'::text,'görmedim'::text,'Hiç bu kadar çok flamingonun aynı anda havalandığını görmedim! Kesinlikle unutulmaz!'::text),
(354168,39352,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... még ennyi flamingót egyszerre felszállni! Abszolút felejthetetlen!'::text,'nem láttam'::text,'nem láttam'::text,'nem láttam'::text,'Soha nem láttam még ennyi flamingót egyszerre felszállni! Abszolút felejthetetlen!'::text),
(354171,39353,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich hat er seinen Kumpel jeden Flamingo ins Notizbuch ... lassen.'::text,'eintragen'::text,'einzutragen'::text,'eingetragen'::text,'Mädel, angeblich hat er seinen Kumpel jeden Flamingo ins Notizbuch eintragen lassen.'::text),
(354175,39353,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він попросив друга ... кожного фламінго в блокнот.'::text,'записати'::text,'записати'::text,'записаного'::text,'Подруго, кажуть, він попросив друга записати кожного фламінго в блокнот.'::text),
(354174,39353,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer hizo que su amigo ... cada flamenco en la libreta.'::text,'apuntara'::text,'apuntar'::text,'apuntado'::text,'Tía, al parecer hizo que su amigo apuntara cada flamenco en la libreta.'::text),
(354173,39353,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment, il a fait ... chaque flamant dans le carnet par son pote.'::text,'noter'::text,'noter'::text,'noté'::text,'Meuf, apparemment, il a fait noter chaque flamant dans le carnet par son pote.'::text),
(354176,39353,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre her flamingoyu deftere arkadaşına ...'::text,'yazdırmış'::text,'yazmak'::text,'yazılmış'::text,'Kızım, duyduğuma göre her flamingoyu deftere arkadaşına yazdırmış.'::text),
(354177,39353,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag minden flamingót ... a barátjával a füzetbe.'::text,'beíratott'::text,'beírni'::text,'beírva'::text,'Csajszi, állítólag minden flamingót beíratott a barátjával a füzetbe.'::text),
(354180,39354,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir erzählt, sie wünschte, sie ... näher an die Flamingos rankommen.'::text,'könnte'::text,'kann'::text,'wird'::text,'Hör zu, sie hat mir erzählt, sie wünschte, sie könnte näher an die Flamingos rankommen.'::text),
(354184,39354,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона мені сказала, що шкодує, що не ... підійти ближче до фламінго.'::text,'може'::text,'може'::text,'зможе'::text,'Слухай, вона мені сказала, що шкодує, що не може підійти ближче до фламінго.'::text),
(354183,39354,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que ojalá ... acercarse más a los flamencos.'::text,'pudiera'::text,'puede'::text,'podrá'::text,'Escucha, me dijo que ojalá pudiera acercarse más a los flamencos.'::text),
(354182,39354,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit qu''elle aimerait ... s''approcher plus près des flamants.'::text,'pouvoir'::text,'peut'::text,'pourra'::text,'Écoute, elle m''a dit qu''elle aimerait pouvoir s''approcher plus près des flamants.'::text),
(354185,39354,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana keşke flamingolara daha çok ... dediğini söyledi.'::text,'yaklaşabilsem'::text,'yaklaşabiliyorum'::text,'yaklaşacağım'::text,'Dinle, bana keşke flamingolara daha çok yaklaşabilsem dediğini söyledi.'::text),
(354186,39354,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, bárcsak közelebb ... menni a flamingókhoz.'::text,'tudna'::text,'tud'::text,'fog tudni'::text,'Figyelj, azt mondta, bárcsak közelebb tudna menni a flamingókhoz.'::text),
(354189,39355,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, der See, ... Hunderte Flamingos leben, ist hier in der Nähe.'::text,'wo'::text,'welcher'::text,'der'::text,'Bestie, ich hab gehört, der See, wo Hunderte Flamingos leben, ist hier in der Nähe.'::text),
(354193,39355,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що озеро, ... живуть сотні фламінго, десь поруч.'::text,'де'::text,'яке'::text,'що'::text,'Подруго, я чула, що озеро, де живуть сотні фламінго, десь поруч.'::text),
(354192,39355,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, he oído que el lago, ... viven cientos de flamencos, está cerca de aquí.'::text,'donde'::text,'el cual'::text,'que'::text,'Amiga, he oído que el lago, donde viven cientos de flamencos, está cerca de aquí.'::text),
(354191,39355,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît que le lac, ... vivent des centaines de flamants, est tout près d''ici.'::text,'où'::text,'lequel'::text,'que'::text,'Ma belle, il paraît que le lac, où vivent des centaines de flamants, est tout près d''ici.'::text),
(354194,39355,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki ... yüzlerce flamingonun yaşadığı göl buraya yakınmış.'::text,''::text,NULL::text,NULL::text,'Kanka, duydum ki yüzlerce flamingonun yaşadığı göl buraya yakınmış.'::text),
(354195,39355,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy a tó, ... több száz flamingó él, itt van a közelben.'::text,'ahol'::text,'amely'::text,'ami'::text,'Csajszi, azt hallottam, hogy a tó, ahol több száz flamingó él, itt van a közelben.'::text),
(335595,37289,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn diese Buchhandlung Kaffee verkaufen würde, ... er den ganzen Tag dort bleiben.'::text,'würde'::text,'wird'::text,'bleibt'::text,'Wenn diese Buchhandlung Kaffee verkaufen würde, würde er den ganzen Tag dort bleiben.'::text),
(335599,37289,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ця книгарня продавала каву, він ... там цілий день.'::text,'залишався б'::text,'залишиться'::text,'залишається'::text,'Якби ця книгарня продавала каву, він залишався б там цілий день.'::text),
(335598,37289,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si esta librería vendiera café, ... allí todo el día.'::text,'se quedaría'::text,'se quedará'::text,'se queda'::text,'Si esta librería vendiera café, se quedaría allí todo el día.'::text),
(335597,37289,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cette librairie vendait du café, il y ... toute la journée.'::text,'resterait'::text,'restera'::text,'reste'::text,'Si cette librairie vendait du café, il y resterait toute la journée.'::text),
(335600,37289,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kitapçı kahve satsaydı bütün gün orada ...'::text,'kalırdı'::text,'kalacak'::text,'kalıyor'::text,'Bu kitapçı kahve satsaydı bütün gün orada kalırdı.'::text),
(335601,37289,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ez a könyvesbolt kávét árulna, egész nap ott ...'::text,'maradna'::text,'fog maradni'::text,'marad'::text,'Ha ez a könyvesbolt kávét árulna, egész nap ott maradna.'::text),
(335604,37290,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das riesige Buch, das er umarmt, ... letzte Woche an diese Buchhandlung geliefert.'::text,'wurde'::text,'wird'::text,'lieferte'::text,'Das riesige Buch, das er umarmt, wurde letzte Woche an diese Buchhandlung geliefert.'::text),
(335608,37290,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Величезна книжка, яку він обіймає, ... до цієї книгарні минулого тижня.'::text,'була доставлена'::text,'доставляється'::text,'доставила'::text,'Величезна книжка, яку він обіймає, була доставлена до цієї книгарні минулого тижня.'::text),
(335607,37290,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El libro enorme que abraza ... a esta librería la semana pasada.'::text,'fue entregado'::text,'es entregado'::text,'entregó'::text,'El libro enorme que abraza fue entregado a esta librería la semana pasada.'::text),
(335606,37290,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''énorme livre qu''il serre dans ses bras ... à cette librairie la semaine dernière.'::text,'a été livré'::text,'est livré'::text,'a livré'::text,'L''énorme livre qu''il serre dans ses bras a été livré à cette librairie la semaine dernière.'::text),
(335609,37290,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarıldığı kocaman kitap geçen hafta bu kitapçıya ...'::text,'teslim edildi'::text,'teslim edilir'::text,'teslim etti'::text,'Sarıldığı kocaman kitap geçen hafta bu kitapçıya teslim edildi.'::text),
(335610,37290,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hatalmas könyvet, amit ölel, múlt héten ... ebbe a könyvesboltba.'::text,'szállították'::text,'szállítják'::text,'szállította'::text,'A hatalmas könyvet, amit ölel, múlt héten szállították ebbe a könyvesboltba.'::text),
(335613,37291,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... mitten in der Buchhandlung ein riesiges Buch. Mäßig interessiert.'::text,'umarmt'::text,'wird umarmt'::text,'umarmend'::text,'Er umarmt mitten in der Buchhandlung ein riesiges Buch. Mäßig interessiert.'::text),
(335617,37291,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... величезну книжку посеред книгарні. Трохи зацікавлений.'::text,'обіймає'::text,'обіймається'::text,'обіймаючи'::text,'Він обіймає величезну книжку посеред книгарні. Трохи зацікавлений.'::text),
(335616,37291,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un libro enorme en mitad de la librería. Ligeramente interesado.'::text,'Abraza'::text,'Es abrazado'::text,'Abrazando'::text,'Abraza un libro enorme en mitad de la librería. Ligeramente interesado.'::text),
(335615,37291,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... un énorme livre au milieu de la librairie. Vaguement intéressé.'::text,'serre dans ses bras'::text,'est serré dans ses bras'::text,'serrant dans ses bras'::text,'Il serre dans ses bras un énorme livre au milieu de la librairie. Vaguement intéressé.'::text),
(335618,37291,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kitapçının ortasında kocaman bir kitaba ..., azıcık ilgili.'::text,'sarılıyor'::text,'sarılınıyor'::text,'sarılan'::text,'Kitapçının ortasında kocaman bir kitaba sarılıyor, azıcık ilgili.'::text),
(335619,37291,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... egy hatalmas könyvet a könyvesbolt közepén. Enyhén érdeklődő.'::text,'Ölel'::text,'Ölelve van'::text,'Ölelve'::text,'Ölel egy hatalmas könyvet a könyvesbolt közepén. Enyhén érdeklődő.'::text),
(335622,37292,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, er ... sich in dieser Buchhandlung nicht langweilen. Er hat nur fünf Bücher umarmt.'::text,'kann'::text,'muss'::text,'könnte'::text,'Klar, er kann sich in dieser Buchhandlung nicht langweilen. Er hat nur fünf Bücher umarmt.'::text),
(335626,37292,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, він ... нудьгувати в цій книгарні. Він обійняв лише п''ять книжок.'::text,'не може'::text,'мусить'::text,'може'::text,'Очевидно, він не може нудьгувати в цій книгарні. Він обійняв лише п''ять книжок.'::text),
(335625,37292,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está claro que ... aburrirse en esta librería. Solo ha abrazado cinco libros.'::text,'no puede'::text,'debe de'::text,'podría'::text,'Está claro que no puede aburrirse en esta librería. Solo ha abrazado cinco libros.'::text),
(335624,37292,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement, il ... s''ennuyer dans cette librairie. Il n''a serré que cinq livres dans ses bras.'::text,'ne peut pas'::text,'doit'::text,'pourrait'::text,'Clairement, il ne peut pas s''ennuyer dans cette librairie. Il n''a serré que cinq livres dans ses bras.'::text),
(335627,37292,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki bu kitapçıda sıkılmış ..., sadece beş kitaba sarıldı.'::text,'olamaz'::text,'olmalı'::text,'olabilir'::text,'Belli ki bu kitapçıda sıkılmış olamaz, sadece beş kitaba sarıldı.'::text),
(335628,37292,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilvánvaló, hogy ... ebben a könyvesboltban. Csak öt könyvet ölelt meg.'::text,'nem unatkozhat'::text,'biztosan unatkozik'::text,'unatkozhat'::text,'Nyilvánvaló, hogy nem unatkozhat ebben a könyvesboltban. Csak öt könyvet ölelt meg.'::text),
(335631,37293,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Buchhandlung, ... Regale bis zur Decke reichen, ist natürlich ein bisschen klein für ihn.'::text,'deren'::text,'welche'::text,'die'::text,'Die Buchhandlung, deren Regale bis zur Decke reichen, ist natürlich ein bisschen klein für ihn.'::text),
(335635,37293,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Книгарня, ... полиці сягають стелі, для нього, звісно, трохи замала.'::text,'чиї'::text,'яка'::text,'що'::text,'Книгарня, чиї полиці сягають стелі, для нього, звісно, трохи замала.'::text),
(335634,37293,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La librería, ... estanterías llegan hasta el techo, es obviamente un poco pequeña para él.'::text,'cuyas'::text,'la cual'::text,'que'::text,'La librería, cuyas estanterías llegan hasta el techo, es obviamente un poco pequeña para él.'::text),
(335633,37293,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La librairie, ... les étagères touchent le plafond, est évidemment un peu petite pour lui.'::text,'dont'::text,'laquelle'::text,'que'::text,'La librairie, dont les étagères touchent le plafond, est évidemment un peu petite pour lui.'::text),
(335636,37293,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... rafları tavana kadar uzanan kitapçı, belli ki onun için biraz küçük.'::text,''::text,NULL::text,NULL::text,'Rafları tavana kadar uzanan kitapçı, belli ki onun için biraz küçük.'::text),
(335637,37293,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A könyvesbolt, ... polcai a plafonig érnek, nyilván kicsit kicsi neki.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A könyvesbolt, amelynek a polcai a plafonig érnek, nyilván kicsit kicsi neki.'::text),
(335640,37294,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schrie, die Buchhandlung ... absolut die besten Bücher der Welt!'::text,'habe'::text,'hat'::text,'werde haben'::text,'Er schrie, die Buchhandlung habe absolut die besten Bücher der Welt!'::text),
(335644,37294,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він кричав, що в книгарні ... абсолютно найкращі книжки на світі!'::text,'є'::text,'є'::text,'будуть'::text,'Він кричав, що в книгарні є абсолютно найкращі книжки на світі!'::text),
(335643,37294,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Gritó que la librería ... absolutamente los mejores libros del mundo!'::text,'tenía'::text,'tiene'::text,'tendrá'::text,'¡Gritó que la librería tenía absolutamente los mejores libros del mundo!'::text),
(335642,37294,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a hurlé que la librairie ... absolument les meilleurs livres du monde !'::text,'avait'::text,'a'::text,'aura'::text,'Il a hurlé que la librairie avait absolument les meilleurs livres du monde !'::text),
(335645,37294,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kitapçıda dünyanın kesinlikle en iyi kitaplarının ... bağırdı!'::text,'olduğunu'::text,'olduğunu'::text,'olacağını'::text,'Kitapçıda dünyanın kesinlikle en iyi kitaplarının olduğunu bağırdı!'::text),
(335646,37294,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt üvöltötte, hogy a könyvesboltban ... abszolút a világ legjobb könyvei!'::text,'vannak'::text,'vannak'::text,'lesznek'::text,'Azt üvöltötte, hogy a könyvesboltban vannak abszolút a világ legjobb könyvei!'::text),
(335649,37295,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... ganze Wochenenden in dieser Buchhandlung, bis es ihn fast ruiniert hätte!'::text,'verbrachte immer'::text,'verbrachte früher'::text,'war es gewohnt zu verbringen'::text,'Er verbrachte immer ganze Wochenenden in dieser Buchhandlung, bis es ihn fast ruiniert hätte!'::text),
(335653,37295,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... цілі вихідні в цій книгарні, аж поки це мало не розорило його!'::text,'проводив'::text,'колись проводив'::text,'звик проводити'::text,'Він проводив цілі вихідні в цій книгарні, аж поки це мало не розорило його!'::text),
(335652,37295,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... fines de semana enteros en esta librería hasta que casi lo arruinó!'::text,'Pasaba'::text,'Solía pasar'::text,'Estaba acostumbrado a pasar'::text,'¡Pasaba fines de semana enteros en esta librería hasta que casi lo arruinó!'::text),
(335651,37295,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des week-ends entiers dans cette librairie, jusqu''à ce que ça le ruine presque !'::text,'passait'::text,'avait l''habitude de passer'::text,'était habitué à passer'::text,'Il passait des week-ends entiers dans cette librairie, jusqu''à ce que ça le ruine presque !'::text),
(335654,37295,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neredeyse onu mahvedene kadar bu kitapçıda koca hafta sonları ...!'::text,'geçirirdi'::text,'geçirirdi'::text,'geçirmeye alışkındı'::text,'Neredeyse onu mahvedene kadar bu kitapçıda koca hafta sonları geçirirdi!'::text),
(335655,37295,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész hétvégéket ... ebben a könyvesboltban, míg ez majdnem tönkre nem tette!'::text,'töltött'::text,'töltött régen'::text,'hozzá volt szokva tölteni'::text,'Egész hétvégéket töltött ebben a könyvesboltban, míg ez majdnem tönkre nem tette!'::text),
(335658,37296,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich weigert er sich, die Buchhandlung ohne das Riesenbuch zu ...'::text,'verlassen'::text,'verlassen'::text,'verlassen'::text,'Bestie, angeblich weigert er sich, die Buchhandlung ohne das Riesenbuch zu verlassen.'::text),
(335662,37296,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він відмовляється ... з книгарні без тієї гігантської книжки.'::text,'піти'::text,'піти'::text,'піти'::text,'Подруго, кажуть, він відмовляється піти з книгарні без тієї гігантської книжки.'::text),
(335661,37296,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer se niega a ... de la librería sin ese libro gigante.'::text,'salir'::text,'salir'::text,'salir'::text,'Amiga, al parecer se niega a salir de la librería sin ese libro gigante.'::text),
(335660,37296,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment, il refuse de ... la librairie sans ce livre géant.'::text,'quitter'::text,'quitter'::text,'quitter'::text,'Ma belle, apparemment, il refuse de quitter la librairie sans ce livre géant.'::text),
(335663,37296,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre o dev kitap olmadan kitapçıdan ... reddediyormuş.'::text,'çıkmayı'::text,'çıkmayı'::text,'çıkmayı'::text,'Kanka, duyduğuma göre o dev kitap olmadan kitapçıdan çıkmayı reddediyormuş.'::text),
(335664,37296,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag nem hajlandó ... a könyvesboltból az óriási könyv nélkül.'::text,'kijönni'::text,'kijönni'::text,'kijönni'::text,'Csajszi, állítólag nem hajlandó kijönni a könyvesboltból az óriási könyv nélkül.'::text),
(335667,37297,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ist er schon den ganzen Tag in dieser Buchhandlung, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Hör zu, angeblich ist er schon den ganzen Tag in dieser Buchhandlung, oder?'::text),
(335671,37297,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він у цій книгарні вже цілий день, ...?'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Слухай, кажуть, він у цій книгарні вже цілий день, правда?'::text),
(335670,37297,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer lleva todo el día en esta librería, ¿...?'::text,'no?'::text,'no?'::text,'no?'::text,'Escucha, al parecer lleva todo el día en esta librería, ¿no?'::text),
(335669,37297,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il est dans cette librairie depuis toute la journée, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Écoute, apparemment il est dans cette librairie depuis toute la journée, non ?'::text),
(335672,37297,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre bütün gün bu kitapçıdaymış, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Dinle, duyduğuma göre bütün gün bu kitapçıdaymış, değil mi?'::text),
(335673,37297,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag egész nap ebben a könyvesboltban volt, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Figyelj, állítólag egész nap ebben a könyvesboltban volt, ugye?'::text),
(335685,37299,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... stundenlang in Büchern geblättert, bevor er in der Buchhandlung das riesige fand.'::text,'hatte'::text,'hat'::text,'blättert'::text,'Er hatte stundenlang in Büchern geblättert, bevor er in der Buchhandlung das riesige fand.'::text),
(335689,37299,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... книжки годинами, перш ніж знайшов у книгарні ту величезну.'::text,'гортав'::text,'гортає'::text,'гортає'::text,'Він гортав книжки годинами, перш ніж знайшов у книгарні ту величезну.'::text),
(335688,37299,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... libros durante horas antes de encontrar el gigante en la librería.'::text,'Había estado hojeando'::text,'Ha estado hojeando'::text,'Está hojeando'::text,'Había estado hojeando libros durante horas antes de encontrar el gigante en la librería.'::text),
(335687,37299,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des livres pendant des heures avant de trouver le géant dans la librairie.'::text,'avait feuilleté'::text,'feuillette depuis'::text,'feuillette'::text,'Il avait feuilleté des livres pendant des heures avant de trouver le géant dans la librairie.'::text),
(335690,37299,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kitapçıda o dev kitabı bulmadan önce saatlerce kitapları ...'::text,'karıştırıyordu'::text,'karıştırıyor'::text,'karıştırıyor'::text,'Kitapçıda o dev kitabı bulmadan önce saatlerce kitapları karıştırıyordu.'::text),
(335691,37299,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Órákig ... a könyveket, mielőtt megtalálta a könyvesboltban az óriásit.'::text,'lapozgatta'::text,'lapozgatja'::text,'lapozgatja'::text,'Órákig lapozgatta a könyveket, mielőtt megtalálta a könyvesboltban az óriásit.'::text),
(394356,43818,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Chirurg ... heute drei Operationen gemacht. Offensichtlich ein lockeres Pensum.'::text,'hat'::text,'macht'::text,'macht'::text,'Der Chirurg hat heute drei Operationen gemacht. Offensichtlich ein lockeres Pensum.'::text),
(394360,43818,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хірург сьогодні ... три операції. Очевидно, легке навантаження.'::text,'провів'::text,'проводить'::text,'проводить'::text,'Хірург сьогодні провів три операції. Очевидно, легке навантаження.'::text),
(394359,43818,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cirujano ... tres operaciones hoy. Obviamente, una carga de trabajo ligera.'::text,'ha hecho'::text,'ha estado haciendo'::text,'hace'::text,'El cirujano ha hecho tres operaciones hoy. Obviamente, una carga de trabajo ligera.'::text),
(394358,43818,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chirurgien ... trois opérations aujourd''hui. Évidemment, une charge de travail légère.'::text,'a fait'::text,'fait depuis'::text,'fait'::text,'Le chirurgien a fait trois opérations aujourd''hui. Évidemment, une charge de travail légère.'::text),
(394361,43818,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cerrah bugün üç ameliyat ..., belli ki hafif bir iş yükü.'::text,'yaptı'::text,'yapıyor'::text,'yapar'::text,'Cerrah bugün üç ameliyat yaptı, belli ki hafif bir iş yükü.'::text),
(394362,43818,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sebész ma ... három műtétet. Nyilván könnyű munkanap.'::text,'végzett el'::text,'végez'::text,'végez'::text,'A sebész ma végzett el három műtétet. Nyilván könnyű munkanap.'::text),
(394365,43819,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Kamera kam, ... der Chirurg schon die Hälfte der Operation beendet. Perfektes Timing.'::text,'hatte'::text,'hat'::text,'beendet'::text,'Als die Kamera kam, hatte der Chirurg schon die Hälfte der Operation beendet. Perfektes Timing.'::text),
(394369,43819,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки прибула камера, хірург уже ... половину операції. Бездоганний таймінг.'::text,'завершив'::text,'завершив'::text,'завершує'::text,'Поки прибула камера, хірург уже завершив половину операції. Бездоганний таймінг.'::text),
(394368,43819,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegó la cámara, el cirujano ya ... la mitad de la operación. Un timing impecable.'::text,'había terminado'::text,'ha terminado'::text,'termina'::text,'Para cuando llegó la cámara, el cirujano ya había terminado la mitad de la operación. Un timing impecable.'::text),
(394367,43819,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que la caméra arrive, le chirurgien ... la moitié de l''opération. Timing impeccable.'::text,'avait terminé'::text,'a terminé'::text,'termine'::text,'Le temps que la caméra arrive, le chirurgien avait terminé la moitié de l''opération. Timing impeccable.'::text),
(394370,43819,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera geldiğinde cerrah ameliyatın yarısını çoktan ..., kusursuz zamanlama.'::text,'bitirmişti'::text,'bitirdi'::text,'bitiriyor'::text,'Kamera geldiğinde cerrah ameliyatın yarısını çoktan bitirmişti, kusursuz zamanlama.'::text),
(394371,43819,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kamera odaért, a sebész már ... a műtét felét. Hibátlan időzítés.'::text,'befejezte'::text,'befejezte'::text,'befejezi'::text,'Mire a kamera odaért, a sebész már befejezte a műtét felét. Hibátlan időzítés.'::text),
(394374,43820,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, morgen um 9 Uhr ... dieser Chirurg schon wieder, ohne Witz.'::text,'operiert'::text,'wird operieren'::text,'operiert'::text,'Bro, morgen um 9 Uhr operiert dieser Chirurg schon wieder, ohne Witz.'::text),
(394378,43820,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, завтра о 9:00 той хірург знову ..., без жартів.'::text,'оперуватиме'::text,'прооперує'::text,'оперує'::text,'Бро, завтра о 9:00 той хірург знову оперуватиме, без жартів.'::text),
(394377,43820,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, mañana a las 9 ese cirujano ... otra vez, en serio.'::text,'estará operando'::text,'operará'::text,'opera'::text,'Bro, mañana a las 9 ese cirujano estará operando otra vez, en serio.'::text),
(394376,43820,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, demain à 9 h, ce chirurgien ... encore, sans mentir.'::text,'sera en train d''opérer'::text,'opérera'::text,'opère'::text,'Frérot, demain à 9 h, ce chirurgien sera en train d''opérer encore, sans mentir.'::text),
(394379,43820,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın sabah 9''da o cerrah yine ..., cidden.'::text,'ameliyat yapıyor olacak'::text,'ameliyat yapacak'::text,'ameliyat yapıyor'::text,'Kanka, yarın sabah 9''da o cerrah yine ameliyat yapıyor olacak, cidden.'::text),
(394380,43820,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnap reggel 9-kor az a sebész megint ..., komolyan.'::text,'operálni fog'::text,'operál majd'::text,'operál'::text,'Tesó, holnap reggel 9-kor az a sebész megint operálni fog, komolyan.'::text),
(394383,43821,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Chirurg so: „Klemme? Okay, ich ... sie selbst“, echt.'::text,'halte'::text,'werde halten'::text,'halte'::text,'Yo, der Chirurg so: „Klemme? Okay, ich halte sie selbst“, echt.'::text),
(394387,43821,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, хірург такий: «Затискач? Добре, я ... його сам», реально.'::text,'потримаю'::text,'триматиму'::text,'тримаю'::text,'Йо, хірург такий: «Затискач? Добре, я потримаю його сам», реально.'::text),
(394386,43821,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el cirujano en plan: «¿La pinza? Vale, la ... yo mismo», en serio.'::text,'sujeto'::text,'estaré sujetando'::text,'estoy sujetando'::text,'Tío, el cirujano en plan: «¿La pinza? Vale, la sujeto yo mismo», en serio.'::text),
(394385,43821,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, le chirurgien genre : « Une pince ? OK, je la ... moi-même », grave.'::text,'tiens'::text,'serai en train de tenir'::text,'tiens'::text,'Wesh, le chirurgien genre : « Une pince ? OK, je la tiens moi-même », grave.'::text),
(394388,43821,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, cerrah resmen: “Pens mi? Tamam, kendim ...”, cidden.'::text,'tutarım'::text,'tutuyor olacağım'::text,'tutuyorum'::text,'Kanka, cerrah resmen: “Pens mi? Tamam, kendim tutarım”, cidden.'::text),
(394389,43821,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a sebész meg: „Csipesz? Oké, majd én ... magam”, komolyan.'::text,'megfogom'::text,'fogom tartani'::text,'tartom'::text,'Tesó, a sebész meg: „Csipesz? Oké, majd én megfogom magam”, komolyan.'::text),
(394392,43822,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Chirurg über 10 Stunden ..., schreibt das Protokoll eine Pause vor.'::text,'arbeitet'::text,'arbeitete'::text,'arbeiten wird'::text,'Wenn ein Chirurg über 10 Stunden arbeitet, schreibt das Protokoll eine Pause vor.'::text),
(394396,43822,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо хірург ... понад 10 годин, протокол вимагає перерви.'::text,'працює'::text,'працював'::text,'працюватиме'::text,'Якщо хірург працює понад 10 годин, протокол вимагає перерви.'::text),
(394395,43822,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un cirujano ... más de 10 horas, el protocolo exige un descanso.'::text,'trabaja'::text,'trabajó'::text,'trabajará'::text,'Si un cirujano trabaja más de 10 horas, el protocolo exige un descanso.'::text),
(394394,43822,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un chirurgien ... plus de 10 heures, le protocole impose une pause.'::text,'travaille'::text,'travaillait'::text,'travaillera'::text,'Si un chirurgien travaille plus de 10 heures, le protocole impose une pause.'::text),
(394397,43822,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir cerrah 10 saatten fazla ..., protokol mola gerektirir.'::text,'çalışırsa'::text,'çalıştıysa'::text,'çalışacaksa'::text,'Bir cerrah 10 saatten fazla çalışırsa, protokol mola gerektirir.'::text),
(394398,43822,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy sebész több mint 10 órát ..., a protokoll szünetet ír elő.'::text,'dolgozik'::text,'dolgozott'::text,'fog dolgozni'::text,'Ha egy sebész több mint 10 órát dolgozik, a protokoll szünetet ír elő.'::text),
(394401,43823,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Chirurg pünktlich fertig wird, ... das Team einen Daumen hoch in die Kamera.'::text,'zeigt'::text,'würde zeigen'::text,'zeigte'::text,'Wenn der Chirurg pünktlich fertig wird, zeigt das Team einen Daumen hoch in die Kamera.'::text),
(394405,43823,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо хірург закінчить вчасно, команда ... в камеру великий палець угору.'::text,'покаже'::text,'показала б'::text,'показала'::text,'Якщо хірург закінчить вчасно, команда покаже в камеру великий палець угору.'::text),
(394404,43823,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el cirujano termina a tiempo, el equipo ... un pulgar arriba a la cámara.'::text,'hará'::text,'haría'::text,'hizo'::text,'Si el cirujano termina a tiempo, el equipo hará un pulgar arriba a la cámara.'::text),
(394403,43823,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le chirurgien termine à l''heure, l''équipe ... un pouce levé à la caméra.'::text,'fera'::text,'ferait'::text,'a fait'::text,'Si le chirurgien termine à l''heure, l''équipe fera un pouce levé à la caméra.'::text),
(394406,43823,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cerrah zamanında bitirirse ekip kameraya başparmak ...'::text,'kaldıracak'::text,'kaldırırdı'::text,'kaldırdı'::text,'Cerrah zamanında bitirirse ekip kameraya başparmak kaldıracak.'::text),
(394407,43823,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sebész időben végez, a csapat ... a kamerának a hüvelykujját.'::text,'felmutatja'::text,'felmutatná'::text,'felmutatta'::text,'Ha a sebész időben végez, a csapat felmutatja a kamerának a hüvelykujját.'::text),
(394410,43824,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich Chirurg wäre, ... ich jeden Tag unter dieser großen runden Lampe arbeiten.'::text,'würde'::text,'werde'::text,'arbeite'::text,'Wenn ich Chirurg wäre, würde ich jeden Tag unter dieser großen runden Lampe arbeiten.'::text),
(394414,43824,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби я був хірургом, я ... під тією великою круглою лампою щодня.'::text,'працював би'::text,'працюватиму'::text,'працюю'::text,'Якби я був хірургом, я працював би під тією великою круглою лампою щодня.'::text),
(394413,43824,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si fuera cirujano, ... bajo esa gran lámpara redonda todos los días.'::text,'trabajaría'::text,'trabajaré'::text,'trabajo'::text,'Si fuera cirujano, trabajaría bajo esa gran lámpara redonda todos los días.'::text),
(394412,43824,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si j''étais chirurgien, je ... sous cette grande lampe ronde tous les jours.'::text,'travaillerais'::text,'travaillerai'::text,'travaille'::text,'Si j''étais chirurgien, je travaillerais sous cette grande lampe ronde tous les jours.'::text),
(394415,43824,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cerrah olsaydım, her gün o büyük yuvarlak lambanın altında ...'::text,'çalışırdım'::text,'çalışacağım'::text,'çalışırım'::text,'Cerrah olsaydım, her gün o büyük yuvarlak lambanın altında çalışırdım.'::text),
(394416,43824,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha sebész lennék, minden nap az alatt a nagy kerek lámpa alatt ...'::text,'dolgoznék'::text,'fogok dolgozni'::text,'dolgozom'::text,'Ha sebész lennék, minden nap az alatt a nagy kerek lámpa alatt dolgoznék.'::text),
(394419,43825,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Skalpell ... dem Chirurgen über das Metalltablett gereicht.'::text,'wird'::text,'reicht'::text,'reichte'::text,'Ein Skalpell wird dem Chirurgen über das Metalltablett gereicht.'::text),
(394423,43825,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Скальпель ... хірургові над металевим лотком.'::text,'передається'::text,'передає'::text,'передавав'::text,'Скальпель передається хірургові над металевим лотком.'::text),
(394422,43825,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un bisturí ... al cirujano por encima de la bandeja metálica.'::text,'es pasado'::text,'pasa'::text,'estaba pasando'::text,'Un bisturí es pasado al cirujano por encima de la bandeja metálica.'::text),
(394421,43825,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un scalpel ... au chirurgien au-dessus du plateau en métal.'::text,'est passé'::text,'passe'::text,'passait'::text,'Un scalpel est passé au chirurgien au-dessus du plateau en métal.'::text),
(394424,43825,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Metal tepsinin üzerinden cerraha bir neşter ...'::text,'uzatılıyor'::text,'uzatıyor'::text,'uzatıyordu'::text,'Metal tepsinin üzerinden cerraha bir neşter uzatılıyor.'::text),
(394425,43825,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy szikét ... a sebésznek a fémtálca fölött.'::text,'adnak át'::text,'átad'::text,'adott át'::text,'Egy szikét adnak át a sebésznek a fémtálca fölött.'::text),
(394428,43826,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte mal, laut der Krankenschwester ... der Chirurg die ganze Operation in weniger als einer Stunde.'::text,'beendete'::text,'wurde beendet'::text,'beendend'::text,'Warte mal, laut der Krankenschwester beendete der Chirurg die ganze Operation in weniger als einer Stunde.'::text),
(394432,43826,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, за словами медсестри, хірург ... всю операцію менш ніж за годину.'::text,'завершив'::text,'був завершений'::text,'завершення'::text,'Стривай, за словами медсестри, хірург завершив всю операцію менш ніж за годину.'::text),
(394431,43826,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, según la enfermera, el cirujano ... toda la operación en menos de una hora.'::text,'terminó'::text,'fue terminado'::text,'terminando'::text,'Espera, según la enfermera, el cirujano terminó toda la operación en menos de una hora.'::text),
(394430,43826,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, d''après l''infirmière, le chirurgien ... toute l''opération en moins d''une heure.'::text,'a terminé'::text,'a été terminé'::text,'terminant'::text,'Attends, d''après l''infirmière, le chirurgien a terminé toute l''opération en moins d''une heure.'::text),
(394433,43826,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur bir dakika, hemşireye göre cerrah bütün ameliyatı bir saatten kısa sürede ...'::text,'bitirmiş'::text,'bitirilmiş'::text,'bitiren'::text,'Dur bir dakika, hemşireye göre cerrah bütün ameliyatı bir saatten kısa sürede bitirmiş.'::text),
(394434,43826,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, a nővér szerint a sebész ... az egész műtétet kevesebb mint egy óra alatt.'::text,'befejezte'::text,'be lett fejezve'::text,'befejezve'::text,'Várj, a nővér szerint a sebész befejezte az egész műtétet kevesebb mint egy óra alatt.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
